INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C1','sci',4,1,'u3',1,'깃발 쓰러뜨리기 놀이 차례 — 흙에 물을 조금 넣어 섞기 → 컵에 가득 담기 → 컵을 뒤집어 성 만들기 → 성 위쪽 가운데에 깃발 꽂기 → 스포이트로 물 뿌리기 · 물이 너무 적으면 안 다져지고 너무 많으면 쉽게 무너짐',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C2','sci',4,1,'u3',1,'물이 흙 성에 한 일 — 물이 닿은 곳의 흙이 깎이고, 깎인 흙이 흙탕물과 함께 아래로 흘러, 성 아래쪽에 쌓임 → 성이 무너져 깃발이 쓰러짐(깎다·옮기다·쌓다)',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C3','sci',4,1,'u3',1,'깃발을 더 빨리 쓰러뜨리는 방법 — 물을 성의 한곳에 집중해서 뿌림 · 스포이트를 세게 눌러 물을 강하게 뿌림',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C4','sci',4,1,'u3',1,'땅의 모습도 조금씩 변함 — 흙 성처럼 실제 땅(강 주변·바닷가 모래사장·산)도 조금씩 변함 · 비가 많이 온 다음 날 흙 언덕에 깎이거나 무너진 곳이 생김',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C5','sci',4,1,'u3',1,'흙 놀이 안전과 정리 — 흙 만진 손으로 얼굴·눈 만지지 않기 · 활동 뒤 손 씻기 · 쇳조각·유리 조각 조심 · 쓴 흙은 제자리에 · 승패보다 협동',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C6','sci',4,1,'u3',2,'흙 언덕 실험 방법 — 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌림 · 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냄 · 색 모래로 흙이 이동하는 모습이 잘 보임',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C7','sci',4,1,'u3',2,'흙 언덕 관찰 결과 — 흙과 색 모래가 물이 흐르는 방향(위 → 아래)으로 이동 · 가장 많이 깎인 곳 = 위쪽 · 가장 많이 쌓인 곳 = 아래쪽',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C8','sci',4,1,'u3',2,'침식 작용 — 흐르는 물이 지표의 바위나 돌 등을 깎아 내는 것',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
