INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C10','sci',4,1,'u3',2,'퇴적 작용 — 운반된 돌이나 흙 등이 쌓이는 것 · 물의 흐름이 느려지는 곳에 모임',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C11','sci',4,1,'u3',2,'세 작용은 보통 동시에 — 침식·운반·퇴적 작용은 보통 함께 일어나고, 곳에 따라 더 활발한 작용이 있을 뿐 · 위쪽 = 침식이 더 활발, 아래쪽 = 퇴적이 더 활발',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C12','sci',4,1,'u3',2,'물의 양과 변화의 크기 — 구멍이 더 큰 종이컵(물이 많음) → 위쪽은 더 많이 깎이고 아래쪽에 더 많이 쌓임 · 물의 양이 많을수록 많이 변함',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C13','sci',4,1,'u3',2,'실험과 실제 자연·뒷정리 — 실험은 실제 자연보다 작고 경사가 달라 실제 모습과 다를 수 있음 · 색 모래는 너무 많이 쓰지 않고 섞인 흙은 걷어 냄 · 흙은 제자리에',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
