INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C15','sci',4,1,'u3',3,'강 하류의 모습 — 강폭이 넓고 강의 경사가 완만함 · 고운 모래와 흙이 많이 쌓여 있음',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C16','sci',4,1,'u3',3,'위치마다 더 활발한 작용 — 상류 = 침식 작용이 퇴적 작용보다 활발 · 하류 = 퇴적 작용이 침식 작용보다 활발 · 한 곳에서 한 작용만 일어나는 것이 아님',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C17','sci',4,1,'u3',3,'하류에 모래가 많은 까닭 — 상류의 바위가 깎이고 운반되며 작아져 생긴 모래가 하류에 쌓이기 때문',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C18','sci',4,1,'u3',3,'모난 돌이 둥글어짐 — 모난 돌이 물에 실려 가며 부딪치고 깎여 점점 둥글어짐(운반 중의 변화)',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C19','sci',4,1,'u3',3,'굽은 강의 바깥쪽과 안쪽 — 같은 곳이라도 바깥쪽은 물이 빨라 침식 작용이, 안쪽은 느려 퇴적 작용이 주로 일어남 → 강이 점점 구불구불해짐',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C20','sci',4,1,'u3',3,'오랜 시간에 걸친 변화와 낱말 뜻 — 흐르는 물은 오랜 시간에 걸쳐 강 주변을 변화시킴 · 강폭 = 강을 가로질러 잰 길이 · 경사 = 기울어진 정도',ARRAY['[4과11-01] 흐르는 물이 지표를 침식·운반·퇴적하여 지표의 모습을 변화시킴을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C21','sci',4,1,'u3',4,'마그마 — 땅속 깊은 곳에서 암석이 녹아 있는 것',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C22','sci',4,1,'u3',4,'화산과 분화구 — 화산 = 땅속의 마그마가 분출하여 만들어진 산 · 분화구 = 분출하면서 생긴 움푹 파인 곳, 물이 고이면 호수가 되기도 함',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C23','sci',4,1,'u3',4,'화산과 화산이 아닌 산 구분 — 물질이 분출하는지·분화구가 있는지로 구분 · 화산은 크기와 생김새가 다양함 · 꼭대기의 눈은 화산의 특징이 아님',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C24','sci',4,1,'u3',4,'용암 — 마그마가 지표의 약한 틈을 타고 땅 위로 분출하여 흐르는 것 · 땅속에 있으면 마그마, 땅 위로 나와 흐르면 용암',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C25','sci',4,1,'u3',4,'화산 활동과 화산 분출물 — 화산 활동 = 분출하며 여러 물질이 나오는 일 · 화산 분출물 = 나온 물질 — 기체 화산 가스 · 액체 용암 · 고체 화산재·화산 암석 조각',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C26','sci',4,1,'u3',4,'용암이 없어도 화산 — 화산은 마그마가 지표를 뚫고 나와 생긴 지형 · 분출물이 모두 나올 때도, 한두 가지만 주로 나올 때도 있음',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C27','sci',4,1,'u3',4,'화산 활동 모형실험 — 포일 화산 모형 + 마시멜로 + 빨간 색소를 가열 · 연기 = 화산 가스 · 흘러내린 마시멜로 = 용암 · 튄 덩어리 = 화산 암석 조각',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C28','sci',4,1,'u3',4,'모형과 실제의 같은 점·다른 점 — 같은 점 = 연기가 나고 붉은 액체가 흘러나와 굳음 · 다른 점 = 모형엔 단단한 암석 조각이 없음, 연기 색이 다름',ARRAY['[4과11-02] 화산 활동으로 나오는 여러 가지 물질을 조사하고, 화산 활동 모형으로 실제 화산 활동과 비교할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
