INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C44','sci',4,1,'u3',7,'흔들릴 때 대처 — 교실 = 책상 아래로 들어가 머리와 몸 보호 · 승강기 = 모든 층 버튼, 먼저 열리는 층에서 내림 · 야외 = 머리 보호, 건물·벽에서 먼 곳 · 할인점 = 머리 보호, 진열대에서 떨어짐',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C45','sci',4,1,'u3',7,'흔들림이 멈췄을 때 — 전기·가스 차단 · 문을 열어 출구 확보 · 승강기 대신 계단으로 대피(전기가 끊기면 승강기가 멈춰 갇힐 수 있음)',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C46','sci',4,1,'u3',7,'평소 대비와 침착함 — 가구·가전제품 고정 · 생존 가방 · 대피장소 알아 두기 · 가족 대비 계획 · 당황하지 않고 침착하게',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C47','sci',4,1,'u3',8,'재난과 재난방송 — 재난 = 화산 활동이나 지진처럼 큰 피해를 주는 현상 · 재난방송 = 재난 상황을 전달하고 대처 방법을 안내하는 방송',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C48','sci',4,1,'u3',8,'안내 자료에 담을 내용 — 발생 일시·발생 장소·피해 내용·대처 방법 · 무서운 장면만 잔뜩·확인 안 된 소문은 담지 않음',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C49','sci',4,1,'u3',8,'재난방송 역할 — 촬영 감독 = 영상 촬영 · 기자 = 피해 사례 취재 · 진행자 = 방송 진행 · 재난 전문가 = 대처 방법 안내',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C50','sci',4,1,'u3',8,'좋은 안내 자료와 나누기 — 꾸미기·소품보다 내용 · 출처 확인, 옳은 정보와 거짓 정보 구분 · 역할은 골고루 · 발표는 귀 기울여 듣고 비난하지 않고 칭찬할 점 찾기',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C51','sci',4,1,'u3',8,'재난 대비 가방 — 물·비상식량·구급약품·손전등·라디오·마스크 등 · 무겁거나 쓸모없는 물건은 넣지 않음',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u3-C52','sci',4,1,'u3',8,'화산이 만든 섬 제주도 — 한라산(꼭대기 백록담) · 오름 = 작은 화산 · 용암 동굴 = 용암이 지하를 뚫고 지나가며 생김 · 성산일출봉 = 바다에서 마그마가 분출해 생긴 화산 · 세계자연유산, 소중히 보존',ARRAY['[4과11-04] 화산 활동과 지진이 우리 생활에 미치는 영향을 조사하고, 피해를 줄이기 위한 대처 방법을 토의할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X01','sci',4,'u3',ARRAY['SC4-1-u3-C2']::text[],'물을 뿌려도 흙 성은 변하지 않거나 오히려 단단해진다고 여긴다','물이 흙을 깎아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X02','sci',4,'u3',ARRAY['SC4-1-u3-C2']::text[],'깎인 흙이 사라지거나 위로 올라간다고 여긴다','아래로 흘러 쌓여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X03','sci',4,'u3',ARRAY['SC4-1-u3-C3']::text[],'물을 흩뿌리거나 약하게 뿌려야 깃발이 빨리 쓰러진다고 여긴다','한곳에 세게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X04','sci',4,'u3',ARRAY['SC4-1-u3-C4']::text[],'실제 땅의 모습은 절대 변하지 않는다고 여긴다','조금씩 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X05','sci',4,'u3',ARRAY['SC4-1-u3-C5']::text[],'흙 놀이의 안전과 정리를 지키지 않거나 이기는 것만 생각한다','손 씻기 · 제자리 · 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X06','sci',4,'u3',ARRAY['SC4-1-u3-C1']::text[],'흙 성 만들기 차례나 물의 양을 잘못 안다(물이 많을수록 단단함)','알맞은 물의 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X07','sci',4,'u3',ARRAY['SC4-1-u3-C8','SC4-1-u3-C9','SC4-1-u3-C10']::text[],'침식·운반·퇴적 작용의 이름과 뜻을 뒤바꾼다','깎기 · 옮기기 · 쌓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X08','sci',4,'u3',ARRAY['SC4-1-u3-C11']::text[],'세 작용이 각각 따로만 일어난다고 여긴다(위쪽은 깎이기만, 아래쪽은 쌓이기만)','보통 동시에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X09','sci',4,'u3',ARRAY['SC4-1-u3-C7','SC4-1-u3-C11']::text[],'가장 많이 깎이는 곳과 쌓이는 곳, 더 활발한 작용을 거꾸로 안다','위 깎임 · 아래 쌓임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X10','sci',4,'u3',ARRAY['SC4-1-u3-C7']::text[],'흙이 물의 흐름을 거슬러 위로 이동한다고 여긴다','물이 흐르는 방향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X11','sci',4,'u3',ARRAY['SC4-1-u3-C12']::text[],'흐르는 물의 양이 많아도 땅의 변화는 같거나 줄어든다고 여긴다','많을수록 많이 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X12','sci',4,'u3',ARRAY['SC4-1-u3-C6','SC4-1-u3-C13']::text[],'흙 언덕 실험의 방법·뒷정리의 까닭을 잘못 알거나 실험이 실제 자연과 똑같다고 여긴다','색 모래는 보이게 · 실제와 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X13','sci',4,'u3',ARRAY['SC4-1-u3-C9']::text[],'깎인 흙이 물과 함께 이동하지 않는다고 여긴다','물과 함께 옮겨져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X14','sci',4,'u3',ARRAY['SC4-1-u3-C14','SC4-1-u3-C15']::text[],'강 상류와 하류의 모습(강폭·경사·돌의 크기)을 뒤바꾼다','상류 좁고 급함 · 하류 넓고 완만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X15','sci',4,'u3',ARRAY['SC4-1-u3-C16']::text[],'상류에서는 침식만, 하류에서는 퇴적만 일어난다고 여긴다','더 활발할 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X16','sci',4,'u3',ARRAY['SC4-1-u3-C16']::text[],'상류와 하류에서 더 활발한 작용을 뒤바꾼다','상류 침식 · 하류 퇴적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X17','sci',4,'u3',ARRAY['SC4-1-u3-C17']::text[],'하류에 모래가 많은 까닭을 엉뚱하게 안다(비·사람이 가져옴)','상류에서 깎여 옮겨져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X18','sci',4,'u3',ARRAY['SC4-1-u3-C18']::text[],'돌이 물에 실려 가도 모양이 그대로이거나 더 모가 난다고 여긴다','부딪쳐 둥글어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X19','sci',4,'u3',ARRAY['SC4-1-u3-C19']::text[],'강의 한 곳에서는 물이 흐르는 빠르기가 같다고 여긴다','바깥쪽 빠름 · 안쪽 느림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X20','sci',4,'u3',ARRAY['SC4-1-u3-C19']::text[],'굽은 강의 바깥쪽과 안쪽에서 주로 일어나는 작용을 뒤바꾼다','바깥쪽 침식 · 안쪽 퇴적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X21','sci',4,'u3',ARRAY['SC4-1-u3-C20']::text[],'강 주변이 짧은 시간에 바뀐다고 여기거나 강폭·경사의 뜻을 헷갈린다','오랜 시간 · 낱말 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X22','sci',4,'u3',ARRAY['SC4-1-u3-C21','SC4-1-u3-C24']::text[],'마그마와 용암을 뒤바꾼다','땅속 마그마 · 땅 위 용암') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X23','sci',4,'u3',ARRAY['SC4-1-u3-C26']::text[],'용암이 분출해야만 화산이라고 여긴다','여러 물질이 나와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X24','sci',4,'u3',ARRAY['SC4-1-u3-C23']::text[],'꼭대기에 눈이 쌓였거나 높으면 화산이라고 여긴다','분출·분화구로 구분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X25','sci',4,'u3',ARRAY['SC4-1-u3-C23']::text[],'화산은 모두 크기와 생김새가 같다고 여긴다','다양해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u3-X26','sci',4,'u3',ARRAY['SC4-1-u3-C25']::text[],'화산 분출물과 그 상태(기체·액체·고체)를 뒤바꾼다','가스 기체 · 용암 액체 · 재 고체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
