INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#1','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C2',1,'mc','auto','흙으로 만든 성에 물을 뿌리면 어떻게 되나요?',ARRAY['SC4-1-u3-X01']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C2","difficulty":1,"kind":"mc","stem":"흙으로 만든 성에 물을 뿌리면 어떻게 되나요?","options":[{"t":"흙이 깎이며 조금씩 무너진다","correct":true},{"t":"성이 더 단단해진다","mis":"SC4-1-u3-X01"},{"t":"아무 일도 일어나지 않는다","mis":"SC4-1-u3-X01"},{"t":"성이 더 높아진다","mis":"SC4-1-u3-X01"}],"explanation":["⑤를 떠올려요.","물이 닿은 곳을 봐요.","깎이며 무너져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#2','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C1',1,'mc','auto','깃발 쓰러뜨리기 놀이에서 흙으로 성을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-1-u3-X06']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C1","difficulty":1,"kind":"mc","stem":"깃발 쓰러뜨리기 놀이에서 흙으로 성을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"흙에 물을 조금 넣어 잘 섞는다","correct":true},{"t":"성 위에 깃발을 꽂는다","mis":"SC4-1-u3-X06"},{"t":"스포이트로 물을 뿌린다","mis":"SC4-1-u3-X06"},{"t":"컵을 뒤집어 성을 만든다","mis":"SC4-1-u3-X06"}],"explanation":["①을 읽어요.","흙부터 준비해요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 흙에 물을 조금 넣고 잘 섞어 컵에 가득 담았다.","② 컵을 뒤집어 흙으로 성을 만들었다.","③ 성 위쪽 가운데에 깃발을 꽂았다.","④ 스포이트로 성에 물을 뿌렸다.","⑤ 물이 닿은 곳의 흙이 깎이고 흙탕물이 아래로 흘렀다.","⑥ 성 아래쪽에 흙이 쌓이고 깃발이 쓰러졌다."],"title":"깃발 쓰러뜨리기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#3','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C5',1,'ox','auto','흙 놀이가 끝나면 손을 꼭 씻어요.',ARRAY['SC4-1-u3-X05']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C5","difficulty":1,"kind":"ox","stem":"흙 놀이가 끝나면 손을 꼭 씻어요.","answer":"O","reason_options":[{"t":"흙에 있던 더러운 것이 몸에 들어가지 않게 하려고","correct":true},{"t":"흙은 늘 깨끗해서 씻지 않아도 되기 때문에","mis":"SC4-1-u3-X05"}],"mis":"SC4-1-u3-X05","explanation":["흙을 만졌어요.","손에 묻었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#4','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C2',1,'sa','auto','물을 뿌린 뒤 성 아래쪽의 흙은 깎였나요, 쌓였나요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C2","difficulty":1,"kind":"sa","stem":"물을 뿌린 뒤 성 아래쪽의 흙은 깎였나요, 쌓였나요? 한 낱말로 쓰세요.","answer":["쌓였어요","쌓였다","쌓임","쌓여요"],"explanation":["⑥을 읽어요.","아래쪽에 모였어요.","쌓였어요."],"mis":"SC4-1-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#5','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C2',2,'match','auto','놀이에서 본 곳과 변한 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C2","difficulty":2,"kind":"match","stem":"놀이에서 본 곳과 변한 모습을 알맞게 이으세요.","pairs":[{"l":"물을 뿌린 곳","r":"흙이 깎였다"},{"l":"성 아래쪽","r":"흙이 쌓였다"},{"l":"깃발","r":"쓰러졌다"}],"mis":"SC4-1-u3-X02","explanation":["⑤와 ⑥을 읽어요.","곳마다 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 흙에 물을 조금 넣고 잘 섞어 컵에 가득 담았다.","② 컵을 뒤집어 흙으로 성을 만들었다.","③ 성 위쪽 가운데에 깃발을 꽂았다.","④ 스포이트로 성에 물을 뿌렸다.","⑤ 물이 닿은 곳의 흙이 깎이고 흙탕물이 아래로 흘렀다.","⑥ 성 아래쪽에 흙이 쌓이고 깃발이 쓰러졌다."],"title":"깃발 쓰러뜨리기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#6','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C3',2,'mc','auto','깃발을 더 빨리 쓰러뜨리려면 물을 어떻게 뿌리는 것이 좋을까요?',ARRAY['SC4-1-u3-X03']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C3","difficulty":2,"kind":"mc","stem":"깃발을 더 빨리 쓰러뜨리려면 물을 어떻게 뿌리는 것이 좋을까요?","options":[{"t":"물을 성의 한곳에 집중해서 뿌린다","correct":true},{"t":"물을 여기저기 조금씩 흩뿌린다","mis":"SC4-1-u3-X03"},{"t":"물 대신 바람을 살짝 분다","mis":"SC4-1-u3-X03"},{"t":"깃발을 더 깊이 꽂는다","mis":"SC4-1-u3-X03"}],"explanation":["한곳을 노려요.","그곳이 많이 깎여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#7','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C2',2,'ox','auto','물에 깎인 흙은 흙탕물과 함께 아래로 흘러갔어요.',ARRAY['SC4-1-u3-X02']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C2","difficulty":2,"kind":"ox","stem":"물에 깎인 흙은 흙탕물과 함께 아래로 흘러갔어요.","answer":"O","reason_options":[{"t":"물이 흙을 깎아 함께 옮겼기 때문에","correct":true},{"t":"깎인 흙은 그 자리에서 사라지기 때문에","mis":"SC4-1-u3-X02"}],"mis":"SC4-1-u3-X02","explanation":["⑤를 읽어요.","흙탕물이 흘렀어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 흙에 물을 조금 넣고 잘 섞어 컵에 가득 담았다.","② 컵을 뒤집어 흙으로 성을 만들었다.","③ 성 위쪽 가운데에 깃발을 꽂았다.","④ 스포이트로 성에 물을 뿌렸다.","⑤ 물이 닿은 곳의 흙이 깎이고 흙탕물이 아래로 흘렀다.","⑥ 성 아래쪽에 흙이 쌓이고 깃발이 쓰러졌다."],"title":"깃발 쓰러뜨리기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#8','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C5',2,'mc','auto','흙 놀이를 바르게 마무리하는 방법은 무엇인가요?',ARRAY['SC4-1-u3-X05']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C5","difficulty":2,"kind":"mc","stem":"흙 놀이를 바르게 마무리하는 방법은 무엇인가요?","options":[{"t":"놀이에 쓴 흙은 원래 있던 자리에 가져다 놓는다","correct":true},{"t":"쓴 흙은 아무 데나 버린다","mis":"SC4-1-u3-X05"},{"t":"흙 묻은 손으로 눈을 비빈다","mis":"SC4-1-u3-X05"},{"t":"남은 흙을 친구에게 던진다","mis":"SC4-1-u3-X05"}],"explanation":["흙은 어디서 왔나요?","제자리로요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#9','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C4',2,'mc','auto','놀이로 알게 된 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X04','SC4-1-u3-X01']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C4","difficulty":2,"kind":"mc","stem":"놀이로 알게 된 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리가 사는 땅의 모습도 조금씩 변할 수 있다","correct":true},{"t":"땅의 모습은 절대 변하지 않는다","mis":"SC4-1-u3-X04"},{"t":"흙은 물에 닿아도 변하지 않는다","mis":"SC4-1-u3-X01"},{"t":"흙 성은 물을 뿌릴수록 단단해진다","mis":"SC4-1-u3-X01"}],"explanation":["흙 성이 변했어요.","진짜 땅도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_basic#10','sci',4,1,'u3','L01','g4_1_sci_u3_L01_basic','lesson_basic','SC4-1-u3-C4',3,'mc','auto','비가 아주 많이 온 다음 날 흙 언덕은 어떤 모습일까요?',ARRAY['SC4-1-u3-X01','SC4-1-u3-X04','SC4-1-u3-X02']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C4","difficulty":3,"kind":"mc","stem":"비가 아주 많이 온 다음 날 흙 언덕은 어떤 모습일까요?","options":[{"t":"흙이 깎이거나 무너진 곳이 있다","correct":true},{"t":"비를 맞아 더 높아졌다","mis":"SC4-1-u3-X01"},{"t":"아무것도 변하지 않았다","mis":"SC4-1-u3-X04"},{"t":"흙이 언덕 위로 올라가 쌓였다","mis":"SC4-1-u3-X02"}],"explanation":["빗물도 흘러요.","흙을 깎아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#1','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C2',2,'blank','auto','「물은 흙을 깎고, (      ), 쌓았어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X01','SC4-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C2","difficulty":2,"kind":"blank","stem":"「물은 흙을 깎고, (      ), 쌓았어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"옮기고","correct":true},{"t":"굳히고","mis":"SC4-1-u3-X01"},{"t":"없애고","mis":"SC4-1-u3-X02"},{"t":"높이고","mis":"SC4-1-u3-X01"}],"explanation":["흙탕물을 떠올려요.","흙이 아래로 갔어요.","「옮기고」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#2','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C1',2,'mc','auto','성을 만들 흙에 물을 너무 많이 넣으면 어떻게 될까요?',ARRAY['SC4-1-u3-X06']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C1","difficulty":2,"kind":"mc","stem":"성을 만들 흙에 물을 너무 많이 넣으면 어떻게 될까요?","options":[{"t":"성이 쉽게 무너진다","correct":true},{"t":"물을 많이 넣을수록 성이 단단해진다","mis":"SC4-1-u3-X06"},{"t":"물의 양은 성과 아무 상관이 없다","mis":"SC4-1-u3-X06"},{"t":"깃발이 더 깊이 꽂힌다","mis":"SC4-1-u3-X06"}],"explanation":["질척한 흙을 떠올려요.","모양이 무너져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#3','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C2',3,'error','auto','놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X02','SC4-1-u3-X01']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C2","difficulty":3,"kind":"error","stem":"놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「물에 깎인 흙은 그 자리에서 사라졌어.」","correct":true,"mis_target":"SC4-1-u3-X02"},{"t":"친구 가 — 「물이 닿은 곳의 흙이 깎였어.」","mis":"SC4-1-u3-X01"},{"t":"친구 다 — 「깎인 흙은 성 아래쪽에 쌓였어.」","mis":"SC4-1-u3-X02"}],"explanation":["⑤와 ⑥을 읽어요.","흙은 아래로 갔어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 흙에 물을 조금 넣고 잘 섞어 컵에 가득 담았다.","② 컵을 뒤집어 흙으로 성을 만들었다.","③ 성 위쪽 가운데에 깃발을 꽂았다.","④ 스포이트로 성에 물을 뿌렸다.","⑤ 물이 닿은 곳의 흙이 깎이고 흙탕물이 아래로 흘렀다.","⑥ 성 아래쪽에 흙이 쌓이고 깃발이 쓰러졌다."],"title":"깃발 쓰러뜨리기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#4','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C3',3,'mc','auto','깃발이 더 빨리 쓰러지는 방법 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X03','SC4-1-u3-X06']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C3","difficulty":3,"kind":"mc","stem":"깃발이 더 빨리 쓰러지는 방법 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"한곳에 집중해서 뿌리고, 스포이트를 세게 누른다","correct":true},{"t":"여러 곳에 흩뿌리고, 스포이트를 살살 누른다","mis":"SC4-1-u3-X03"},{"t":"물을 아주 조금만 뿌리고 기다린다","mis":"SC4-1-u3-X03"},{"t":"물을 뿌리지 않고 성을 흔든다","mis":"SC4-1-u3-X06"}],"explanation":["어디에 뿌릴까요?","얼마나 세게요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#5','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C2',3,'mc','auto','우리가 한 일이 아니라 물이 한 일은 무엇인가요?',ARRAY['SC4-1-u3-X06']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C2","difficulty":3,"kind":"mc","stem":"우리가 한 일이 아니라 물이 한 일은 무엇인가요?","options":[{"t":"흙을 아래로 옮겨 쌓았다","correct":true},{"t":"흙으로 성을 만들었다","mis":"SC4-1-u3-X06"},{"t":"성 위에 깃발을 꽂았다","mis":"SC4-1-u3-X06"},{"t":"흙에 물을 섞어 컵에 담았다","mis":"SC4-1-u3-X06"}],"explanation":["①~④는 우리가 했어요.","⑤~⑥을 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#6','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C4',3,'ox','auto','강 주변이나 바닷가 모래사장의 모습도 시간이 지나면 변할 수 있어요.',ARRAY['SC4-1-u3-X04']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C4","difficulty":3,"kind":"ox","stem":"강 주변이나 바닷가 모래사장의 모습도 시간이 지나면 변할 수 있어요.","answer":"O","reason_options":[{"t":"흙 성처럼 실제 땅도 조금씩 변하기 때문에","correct":true},{"t":"실제 땅은 한번 생기면 그대로이기 때문에","mis":"SC4-1-u3-X04"}],"mis":"SC4-1-u3-X04","explanation":["흙 성을 떠올려요.","진짜 땅도 변해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#7','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C5',3,'mc','auto','놀이를 할 때 생각할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X05']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C5","difficulty":3,"kind":"mc","stem":"놀이를 할 때 생각할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구와 힘을 모아 쓰러뜨릴 방법을 함께 궁리한다","correct":true},{"t":"누가 먼저 쓰러뜨렸는지만 따진다","mis":"SC4-1-u3-X05"},{"t":"흙을 친구 얼굴에 뿌린다","mis":"SC4-1-u3-X05"},{"t":"흙에 유리 조각이 섞여도 그냥 만진다","mis":"SC4-1-u3-X05"}],"explanation":["함께 하는 놀이예요.","안전도 생각해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#8','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C2',4,'mc','auto','친구가 「흙 성은 물 때문에 무너진 게 아니라 원래 약해서 그래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X01','SC4-1-u3-X02']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C2","difficulty":4,"kind":"mc","stem":"친구가 「흙 성은 물 때문에 무너진 게 아니라 원래 약해서 그래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물이 닿은 곳부터 흙이 깎여 아래로 쌓였으니 물이 성의 모습을 바꾼 거야.」","correct":true},{"t":"「맞아, 물은 흙을 바꾸지 못해.」","mis":"SC4-1-u3-X01"},{"t":"「깎인 흙은 공기 중으로 사라졌어.」","mis":"SC4-1-u3-X02"},{"t":"「물을 뿌리면 성이 더 단단해져.」","mis":"SC4-1-u3-X01"}],"explanation":["물이 닿은 곳을 봐요.","깎이고 쌓였어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#9','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C4',4,'mc','auto','친구가 「산이나 강 같은 진짜 땅은 너무 커서 모습이 바뀌지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X04','SC4-1-u3-X03','SC4-1-u3-X02']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C4","difficulty":4,"kind":"mc","stem":"친구가 「산이나 강 같은 진짜 땅은 너무 커서 모습이 바뀌지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「진짜 땅도 물 때문에 조금씩 깎이고 쌓이며 모습이 변하고 있어.」","correct":true},{"t":"「맞아, 땅은 절대 변하지 않아.」","mis":"SC4-1-u3-X04"},{"t":"「땅은 물이 아니라 깃발 때문에 변해.」","mis":"SC4-1-u3-X03"},{"t":"「흙은 물에 닿으면 사라져.」","mis":"SC4-1-u3-X02"}],"explanation":["흙 성을 떠올려요.","크기만 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L01_challenge#10','sci',4,1,'u3','L01','g4_1_sci_u3_L01_challenge','lesson_challenge','SC4-1-u3-C2',4,'essay','teacher','「깃발 쓰러뜨리기 놀이」를 보고 물이 흙 성에 한 일을 차례대로 쓰고, 깃발이 쓰러진 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C2","difficulty":4,"kind":"essay","stem":"「깃발 쓰러뜨리기 놀이」를 보고 물이 흙 성에 한 일을 차례대로 쓰고, 깃발이 쓰러진 까닭을 쓰세요.","answer_guide":{"answer":"예: 물이 닿은 곳의 흙을 깎았고, 깎인 흙을 흙탕물과 함께 아래로 옮겼고, 옮긴 흙을 성 아래쪽에 쌓았다. 흙이 깎여 성이 무너졌기 때문에 깃발이 쓰러졌다.","scoring_points":["흙을 깎았다고 썼는가","옮기고 쌓았다고 차례대로 썼는가","깃발이 쓰러진 까닭을 성이 무너진 것과 이었는가"]},"explanation":["⑤와 ⑥을 읽어요.","세 가지 일이에요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 흙에 물을 조금 넣고 잘 섞어 컵에 가득 담았다.","② 컵을 뒤집어 흙으로 성을 만들었다.","③ 성 위쪽 가운데에 깃발을 꽂았다.","④ 스포이트로 성에 물을 뿌렸다.","⑤ 물이 닿은 곳의 흙이 깎이고 흙탕물이 아래로 흘렀다.","⑥ 성 아래쪽에 흙이 쌓이고 깃발이 쓰러졌다."],"title":"깃발 쓰러뜨리기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#1','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C8',1,'mc','auto','흐르는 물이 지표의 바위나 돌 등을 깎아 내는 것을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X07']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C8","difficulty":1,"kind":"mc","stem":"흐르는 물이 지표의 바위나 돌 등을 깎아 내는 것을 무엇이라고 하나요?","options":[{"t":"침식 작용","correct":true},{"t":"운반 작용","mis":"SC4-1-u3-X07"},{"t":"퇴적 작용","mis":"SC4-1-u3-X07"},{"t":"아무 작용도 아니다","mis":"SC4-1-u3-X07"}],"explanation":["깎아 내요.","이름을 떠올려요.","침식 작용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#2','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C9',1,'mc','auto','깎인 돌이나 흙 등이 물과 함께 이동하는 것을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X13']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C9","difficulty":1,"kind":"mc","stem":"깎인 돌이나 흙 등이 물과 함께 이동하는 것을 무엇이라고 하나요?","options":[{"t":"운반 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X07"},{"t":"퇴적 작용","mis":"SC4-1-u3-X07"},{"t":"흙은 물과 함께 이동하지 않는다","mis":"SC4-1-u3-X13"}],"explanation":["옮겨요.","이름을 떠올려요.","운반 작용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#3','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C10',1,'sa','auto','운반된 돌이나 흙 등이 쌓이는 것을 무엇이라고 하나요? 「○○ 작용」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC4-1-u3-C10","difficulty":1,"kind":"sa","stem":"운반된 돌이나 흙 등이 쌓이는 것을 무엇이라고 하나요? 「○○ 작용」의 ○○에 알맞은 말을 쓰세요.","answer":["퇴적"],"explanation":["쌓여요.","이름을 떠올려요.","퇴적이에요."],"mis":"SC4-1-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#4','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C7',1,'ox','auto','흙 언덕 실험에서 흙과 색 모래는 물이 흐르는 방향으로 이동했어요.',ARRAY['SC4-1-u3-X10']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C7","difficulty":1,"kind":"ox","stem":"흙 언덕 실험에서 흙과 색 모래는 물이 흐르는 방향으로 이동했어요.","answer":"O","reason_options":[{"t":"흐르는 물이 흙과 색 모래를 함께 옮겼기 때문에","correct":true},{"t":"흙은 물을 거슬러 위로 올라가기 때문에","mis":"SC4-1-u3-X10"}],"mis":"SC4-1-u3-X10","explanation":["③을 읽어요.","위에서 아래로요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌렸다.","② 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냈다.","③ 흙과 색 모래가 물이 흐르는 방향으로 이동했다.","④ 언덕 위쪽은 움푹 파였다.","⑤ 언덕 아래쪽에는 흙과 색 모래가 쌓였다."],"title":"흙 언덕 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#5','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C7',2,'match','auto','흙 언덕의 곳과 관찰한 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C7","difficulty":2,"kind":"match","stem":"흙 언덕의 곳과 관찰한 모습을 알맞게 이으세요.","pairs":[{"l":"언덕 위쪽","r":"흙이 가장 많이 깎였다"},{"l":"언덕 아래쪽","r":"흙이 가장 많이 쌓였다"},{"l":"흘러가는 물","r":"흙탕물이 되었다"}],"mis":"SC4-1-u3-X09","explanation":["④와 ⑤를 읽어요.","위와 아래가 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌렸다.","② 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냈다.","③ 흙과 색 모래가 물이 흐르는 방향으로 이동했다.","④ 언덕 위쪽은 움푹 파였다.","⑤ 언덕 아래쪽에는 흙과 색 모래가 쌓였다."],"title":"흙 언덕 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#6','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C11',2,'mc','auto','흙 언덕의 위쪽에서 일어나는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X08','SC4-1-u3-X09']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C11","difficulty":2,"kind":"mc","stem":"흙 언덕의 위쪽에서 일어나는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"침식 작용이 더 활발하지만 운반·퇴적 작용도 함께 일어난다","correct":true},{"t":"침식 작용 하나만 일어나고 다른 작용은 전혀 없다","mis":"SC4-1-u3-X08"},{"t":"퇴적 작용이 가장 활발하다","mis":"SC4-1-u3-X09"},{"t":"아무 작용도 일어나지 않는다","mis":"SC4-1-u3-X08"}],"explanation":["위쪽은 많이 깎여요.","다른 일도 함께요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#7','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C6',2,'mc','auto','흙 언덕 실험에서 꼭대기에 색 모래를 뿌리는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X12']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C6","difficulty":2,"kind":"mc","stem":"흙 언덕 실험에서 꼭대기에 색 모래를 뿌리는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"흙이 어디로 이동하는지 눈에 잘 띄게 하려고","correct":true},{"t":"흙 언덕을 더 단단하게 만들려고","mis":"SC4-1-u3-X12"},{"t":"물이 흐르지 않게 막으려고","mis":"SC4-1-u3-X12"},{"t":"흙 언덕을 예쁘게 꾸미려고","mis":"SC4-1-u3-X12"}],"explanation":["색이 달라요.","움직임이 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#8','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C12',2,'ox','auto','구멍이 더 큰 종이컵으로 물을 흘려 보내면 흙 언덕의 모습이 더 많이 변해요.',ARRAY['SC4-1-u3-X11']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C12","difficulty":2,"kind":"ox","stem":"구멍이 더 큰 종이컵으로 물을 흘려 보내면 흙 언덕의 모습이 더 많이 변해요.","answer":"O","reason_options":[{"t":"흐르는 물의 양이 많을수록 더 많이 깎이고 더 많이 쌓이기 때문에","correct":true},{"t":"물의 양이 많아도 흙 언덕의 변화는 똑같기 때문에","mis":"SC4-1-u3-X11"}],"mis":"SC4-1-u3-X11","explanation":["구멍이 크면 물이 많아요.","더 많이 변해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#9','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C9',2,'mc','auto','「흙 언덕 실험」 ③에서 흙과 색 모래가 아래로 이동한 것은 어떤 작용인가요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X13']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C9","difficulty":2,"kind":"mc","stem":"「흙 언덕 실험」 ③에서 흙과 색 모래가 아래로 이동한 것은 어떤 작용인가요?","options":[{"t":"운반 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X07"},{"t":"퇴적 작용","mis":"SC4-1-u3-X07"},{"t":"흙이 물 없이 스스로 움직인 것이다","mis":"SC4-1-u3-X13"}],"explanation":["③을 읽어요.","옮겨졌어요.","운반 작용이에요."],"asset":{"type":"passage","lines":["① 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌렸다.","② 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냈다.","③ 흙과 색 모래가 물이 흐르는 방향으로 이동했다.","④ 언덕 위쪽은 움푹 파였다.","⑤ 언덕 아래쪽에는 흙과 색 모래가 쌓였다."],"title":"흙 언덕 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_basic#10','sci',4,1,'u3','L02','g4_1_sci_u3_L02_basic','lesson_basic','SC4-1-u3-C10',3,'mc','auto','「흙 언덕 실험」 ⑤처럼 언덕 아래쪽에 흙과 색 모래가 모인 것과 가장 관계 깊은 작용은 무엇인가요?',ARRAY['SC4-1-u3-X09','SC4-1-u3-X07','SC4-1-u3-X10']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C10","difficulty":3,"kind":"mc","stem":"「흙 언덕 실험」 ⑤처럼 언덕 아래쪽에 흙과 색 모래가 모인 것과 가장 관계 깊은 작용은 무엇인가요?","options":[{"t":"퇴적 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X09"},{"t":"운반 작용","mis":"SC4-1-u3-X07"},{"t":"물이 흙을 거슬러 올려 보낸 것","mis":"SC4-1-u3-X10"}],"explanation":["⑤를 읽어요.","쌓였어요.","퇴적 작용이에요."],"asset":{"type":"passage","lines":["① 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌렸다.","② 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냈다.","③ 흙과 색 모래가 물이 흐르는 방향으로 이동했다.","④ 언덕 위쪽은 움푹 파였다.","⑤ 언덕 아래쪽에는 흙과 색 모래가 쌓였다."],"title":"흙 언덕 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#1','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C11',2,'blank','auto','「침식, 운반, 퇴적 작용은 보통 (      ) 일어나고, 곳에 따라 더 활발한 작용이 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X08']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C11","difficulty":2,"kind":"blank","stem":"「침식, 운반, 퇴적 작용은 보통 (      ) 일어나고, 곳에 따라 더 활발한 작용이 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"동시에","correct":true},{"t":"따로따로만","mis":"SC4-1-u3-X08"},{"t":"차례대로 한 번씩만","mis":"SC4-1-u3-X08"},{"t":"비가 그친 뒤에만","mis":"SC4-1-u3-X08"}],"explanation":["세 작용을 떠올려요.","함께 일어나요.","「동시에」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#2','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C13',2,'mc','auto','흙 언덕 실험을 마친 뒤 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X12']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C13","difficulty":2,"kind":"mc","stem":"흙 언덕 실험을 마친 뒤 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"색 모래가 섞인 흙은 걷어 내고 흙을 제자리에 가져다 놓는다","correct":true},{"t":"색 모래가 섞인 흙을 화단에 그대로 뿌린다","mis":"SC4-1-u3-X12"},{"t":"흙 만진 손으로 얼굴을 닦는다","mis":"SC4-1-u3-X12"},{"t":"다음에는 색 모래를 더 많이 뿌린다","mis":"SC4-1-u3-X12"}],"explanation":["색 모래는 흙을 더럽혀요.","걷어 내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#3','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C11',3,'error','auto','흙 언덕 실험을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X08','SC4-1-u3-X09']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C11","difficulty":3,"kind":"error","stem":"흙 언덕 실험을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「언덕 위쪽에서는 깎이기만 하고 아래쪽에서는 쌓이기만 해.」","correct":true,"mis_target":"SC4-1-u3-X08"},{"t":"친구 나 — 「위쪽은 침식 작용이 더 활발해.」","mis":"SC4-1-u3-X09"},{"t":"친구 다 — 「세 작용은 보통 함께 일어나.」","mis":"SC4-1-u3-X08"}],"explanation":["세 작용을 떠올려요.","함께 일어나요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#4','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C12',3,'mc','auto','구멍이 더 큰 종이컵으로 물을 흘려 보내면 어떻게 될까요?',ARRAY['SC4-1-u3-X11','SC4-1-u3-X09']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C12","difficulty":3,"kind":"mc","stem":"구멍이 더 큰 종이컵으로 물을 흘려 보내면 어떻게 될까요?","options":[{"t":"위쪽은 더 많이 깎이고 아래쪽에는 더 많이 쌓인다","correct":true},{"t":"흙 언덕이 변하지 않는다","mis":"SC4-1-u3-X11"},{"t":"위쪽에 흙이 더 많이 쌓인다","mis":"SC4-1-u3-X09"},{"t":"물이 많을수록 덜 깎인다","mis":"SC4-1-u3-X11"}],"explanation":["물이 많아져요.","더 많이 변해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#5','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C11',3,'mc','auto','흙 언덕에서 물이 빠르게 흐르는 곳과 느려지는 곳을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X09','SC4-1-u3-X08','SC4-1-u3-X10']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C11","difficulty":3,"kind":"mc","stem":"흙 언덕에서 물이 빠르게 흐르는 곳과 느려지는 곳을 바르게 말한 것은 무엇인가요?","options":[{"t":"빠른 곳은 침식 작용이, 느려지는 곳은 퇴적 작용이 더 활발하다","correct":true},{"t":"빠른 곳은 퇴적 작용이, 느려지는 곳은 침식 작용이 더 활발하다","mis":"SC4-1-u3-X09"},{"t":"두 곳 모두 아무 작용이 없다","mis":"SC4-1-u3-X08"},{"t":"빠른 곳에서는 흙이 위로 거슬러 올라간다","mis":"SC4-1-u3-X10"}],"explanation":["빠르면 깎아요.","느리면 내려놓아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#6','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C13',3,'ox','auto','흙 언덕 실험의 모습은 실제 자연의 모습과 언제나 똑같아요.',ARRAY['SC4-1-u3-X12']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C13","difficulty":3,"kind":"ox","stem":"흙 언덕 실험의 모습은 실제 자연의 모습과 언제나 똑같아요.","answer":"X","reason_options":[{"t":"실험은 실제 자연보다 작아 실제와 다를 수 있기 때문에","correct":true},{"t":"실험 결과가 곧 실제 자연의 모습이기 때문에","mis":"SC4-1-u3-X12"}],"mis":"SC4-1-u3-X12","explanation":["크기를 견줘요.","실제 자연은 훨씬 커요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#7','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C8',3,'mc','auto','다음 가운데 침식 작용이 일어난 모습은 무엇인가요?',ARRAY['SC4-1-u3-X07']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C8","difficulty":3,"kind":"mc","stem":"다음 가운데 침식 작용이 일어난 모습은 무엇인가요?","options":[{"t":"언덕 위쪽이 물에 깎여 움푹 파였다","correct":true},{"t":"언덕 아래쪽에 색 모래가 모였다","mis":"SC4-1-u3-X07"},{"t":"흙이 물과 함께 흘러갔다","mis":"SC4-1-u3-X07"},{"t":"흙탕물 속 흙이 가라앉아 쌓였다","mis":"SC4-1-u3-X07"}],"explanation":["깎아 낸 모습을 찾아요.","파인 곳이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#8','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C11',4,'mc','auto','친구가 「흙이 쌓이는 언덕 아래쪽에서는 흙이 깎이는 일이 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X08','SC4-1-u3-X09','SC4-1-u3-X10']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C11","difficulty":4,"kind":"mc","stem":"친구가 「흙이 쌓이는 언덕 아래쪽에서는 흙이 깎이는 일이 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「아래쪽에서도 깎이고 옮겨지는 일이 함께 일어나. 쌓이는 일이 더 활발할 뿐이야.」","correct":true},{"t":"「맞아, 아래쪽은 쌓이기만 해.」","mis":"SC4-1-u3-X08"},{"t":"「아래쪽은 침식 작용이 가장 활발해.」","mis":"SC4-1-u3-X09"},{"t":"「아래쪽 흙은 위로 올라가.」","mis":"SC4-1-u3-X10"}],"explanation":["세 작용은 함께예요.","더 활발한 것만 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#9','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C9',4,'mc','auto','친구가 「흐르는 물은 흙을 깎기만 하고, 깎인 흙은 그 자리에 그대로 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X13','SC4-1-u3-X07','SC4-1-u3-X10']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C9","difficulty":4,"kind":"mc","stem":"친구가 「흐르는 물은 흙을 깎기만 하고, 깎인 흙은 그 자리에 그대로 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「깎인 흙은 물과 함께 이동해. 그게 운반 작용이야.」","correct":true},{"t":"「맞아, 흙은 물과 함께 움직이지 않아.」","mis":"SC4-1-u3-X13"},{"t":"「깎인 흙이 이동하는 건 퇴적 작용이야.」","mis":"SC4-1-u3-X07"},{"t":"「깎인 흙은 물을 거슬러 위로 가.」","mis":"SC4-1-u3-X10"}],"explanation":["③을 떠올려요.","흙이 이동했어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L02_challenge#10','sci',4,1,'u3','L02','g4_1_sci_u3_L02_challenge','lesson_challenge','SC4-1-u3-C11',4,'essay','teacher','「흙 언덕 실험」을 보고 침식·운반·퇴적 작용이 언덕의 어디에서 어떻게 일어났는지 쓰고, 세 작용이 어떻게 일어나는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C11","difficulty":4,"kind":"essay","stem":"「흙 언덕 실험」을 보고 침식·운반·퇴적 작용이 언덕의 어디에서 어떻게 일어났는지 쓰고, 세 작용이 어떻게 일어나는지 쓰세요.","answer_guide":{"answer":"예: 언덕 위쪽의 흙이 깎인 것은 침식 작용, 흙과 색 모래가 물과 함께 아래로 이동한 것은 운반 작용, 언덕 아래쪽에 쌓인 것은 퇴적 작용이다. 세 작용은 보통 동시에 일어나고, 위쪽은 침식 작용이, 아래쪽은 퇴적 작용이 더 활발하다.","scoring_points":["세 작용을 곳과 바르게 이었는가","세 작용이 동시에 일어난다고 썼는가","곳에 따라 더 활발한 작용을 썼는가"]},"explanation":["③~⑤를 읽어요.","곳마다 짝 지어요.","함께 일어남을 써요."],"asset":{"type":"passage","lines":["① 흙 언덕을 쌓고 꼭대기에 색 모래를 뿌렸다.","② 구멍 뚫린 종이컵으로 꼭대기에 물을 흘려 보냈다.","③ 흙과 색 모래가 물이 흐르는 방향으로 이동했다.","④ 언덕 위쪽은 움푹 파였다.","⑤ 언덕 아래쪽에는 흙과 색 모래가 쌓였다."],"title":"흙 언덕 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#1','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C14',1,'mc','auto','강폭이 좁고 강의 경사가 급한 곳은 어디인가요?',ARRAY['SC4-1-u3-X14']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C14","difficulty":1,"kind":"mc","stem":"강폭이 좁고 강의 경사가 급한 곳은 어디인가요?","options":[{"t":"강 상류","correct":true},{"t":"강 하류","mis":"SC4-1-u3-X14"},{"t":"강의 어느 곳이든 똑같다","mis":"SC4-1-u3-X14"},{"t":"바다와 만나는 곳","mis":"SC4-1-u3-X14"}],"explanation":["좁고 급해요.","산에 가까워요.","강 상류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#2','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C15',1,'mc','auto','고운 모래와 흙을 많이 볼 수 있는 곳은 어디인가요?',ARRAY['SC4-1-u3-X14']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C15","difficulty":1,"kind":"mc","stem":"고운 모래와 흙을 많이 볼 수 있는 곳은 어디인가요?","options":[{"t":"강 하류","correct":true},{"t":"강 상류","mis":"SC4-1-u3-X14"},{"t":"강폭이 좁고 경사가 급한 곳","mis":"SC4-1-u3-X14"},{"t":"큰 바위가 많은 곳","mis":"SC4-1-u3-X14"}],"explanation":["모래가 쌓여요.","넓고 완만해요.","강 하류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#3','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C16',1,'ox','auto','강 상류에서는 침식 작용이 퇴적 작용보다 활발해요.',ARRAY['SC4-1-u3-X16']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C16","difficulty":1,"kind":"ox","stem":"강 상류에서는 침식 작용이 퇴적 작용보다 활발해요.","answer":"O","reason_options":[{"t":"강 상류는 경사가 급해 물이 빠르게 흐르기 때문에","correct":true},{"t":"강 상류에서는 흙이 쌓이는 일이 가장 활발하기 때문에","mis":"SC4-1-u3-X16"}],"mis":"SC4-1-u3-X16","explanation":["경사가 급해요.","물이 빨라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#4','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C20',1,'sa','auto','강을 가로질러 잰 길이를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C20","difficulty":1,"kind":"sa","stem":"강을 가로질러 잰 길이를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["강폭"],"explanation":["강의 너비예요.","「강○」이에요.","강폭이에요."],"mis":"SC4-1-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#5','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C16',2,'match','auto','강의 곳과 그곳의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C16","difficulty":2,"kind":"match","stem":"강의 곳과 그곳의 모습을 알맞게 이으세요.","pairs":[{"l":"강 상류","r":"침식 작용이 더 활발하다"},{"l":"강 하류","r":"퇴적 작용이 더 활발하다"},{"l":"굽은 강의 바깥쪽","r":"물이 빠르게 흐른다"}],"mis":"SC4-1-u3-X16","explanation":["상류는 깎여요.","하류는 쌓여요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#6','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C17',2,'mc','auto','강 상류보다 강 하류에서 모래를 더 많이 볼 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X17']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C17","difficulty":2,"kind":"mc","stem":"강 상류보다 강 하류에서 모래를 더 많이 볼 수 있는 까닭은 무엇인가요?","options":[{"t":"상류의 바위가 깎이고 운반되며 생긴 모래가 하류에 쌓이기 때문에","correct":true},{"t":"강 하류에 비가 더 많이 오기 때문에","mis":"SC4-1-u3-X17"},{"t":"사람들이 모래를 가져다 놓았기 때문에","mis":"SC4-1-u3-X17"},{"t":"강 하류에서만 물이 흐르기 때문에","mis":"SC4-1-u3-X17"}],"explanation":["모래는 어디서 왔을까요?","상류에서 깎여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#7','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C14',2,'mc','auto','「강 주변의 모습 ㉮와 ㉯」에서 ㉮는 어디의 모습인가요?',ARRAY['SC4-1-u3-X14']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C14","difficulty":2,"kind":"mc","stem":"「강 주변의 모습 ㉮와 ㉯」에서 ㉮는 어디의 모습인가요?","options":[{"t":"강 상류","correct":true},{"t":"강 하류","mis":"SC4-1-u3-X14"},{"t":"㉮와 ㉯ 모두 강 하류","mis":"SC4-1-u3-X14"},{"t":"알 수 없다","mis":"SC4-1-u3-X14"}],"explanation":["㉮를 읽어요.","좁고 급해요.","강 상류예요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 강의 경사가 급하다.","㉮ 큰 바위와 모난 돌이 많다.","㉯ 강폭이 넓고 강의 경사가 완만하다.","㉯ 고운 모래와 흙이 많이 쌓여 있다."],"title":"강 주변의 모습 ㉮와 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#8','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C16',2,'ox','auto','강 하류에서는 침식 작용이 전혀 일어나지 않고 퇴적 작용만 일어나요.',ARRAY['SC4-1-u3-X15']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C16","difficulty":2,"kind":"ox","stem":"강 하류에서는 침식 작용이 전혀 일어나지 않고 퇴적 작용만 일어나요.","answer":"X","reason_options":[{"t":"하류에서도 침식 작용이 일어나지만 퇴적 작용이 더 활발할 뿐이기 때문에","correct":true},{"t":"하류에서는 한 가지 작용만 일어나기 때문에","mis":"SC4-1-u3-X15"}],"mis":"SC4-1-u3-X15","explanation":["세 작용을 떠올려요.","더 활발할 뿐이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#9','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C18',2,'mc','auto','강 상류의 모난 돌이 물에 실려 하류 쪽으로 옮겨 가면 어떻게 될까요?',ARRAY['SC4-1-u3-X18']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C18","difficulty":2,"kind":"mc","stem":"강 상류의 모난 돌이 물에 실려 하류 쪽으로 옮겨 가면 어떻게 될까요?","options":[{"t":"서로 부딪치고 깎여 점점 둥글어진다","correct":true},{"t":"점점 더 뾰족하게 모가 난다","mis":"SC4-1-u3-X18"},{"t":"모양이 조금도 변하지 않는다","mis":"SC4-1-u3-X18"},{"t":"물속에서 녹아 없어진다","mis":"SC4-1-u3-X18"}],"explanation":["옮겨 가며 부딪쳐요.","모서리가 닳아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_basic#10','sci',4,1,'u3','L03','g4_1_sci_u3_L03_basic','lesson_basic','SC4-1-u3-C20',3,'mc','auto','흐르는 물이 강 주변의 모습을 바꾸는 데 걸리는 시간으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X21']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C20","difficulty":3,"kind":"mc","stem":"흐르는 물이 강 주변의 모습을 바꾸는 데 걸리는 시간으로 알맞은 것은 무엇인가요?","options":[{"t":"오랜 시간에 걸쳐 조금씩 바꾼다","correct":true},{"t":"하루 만에 모두 바꾼다","mis":"SC4-1-u3-X21"},{"t":"한 번 바꾸면 다시는 바꾸지 않는다","mis":"SC4-1-u3-X21"},{"t":"물은 강 주변의 모습을 바꾸지 못한다","mis":"SC4-1-u3-X21"}],"explanation":["강은 아주 오래 흘러요.","조금씩 변해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#1','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C14',2,'blank','auto','「강의 (      )에서는 큰 바위를 더 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X14']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C14","difficulty":2,"kind":"blank","stem":"「강의 (      )에서는 큰 바위를 더 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"상류","correct":true},{"t":"하류","mis":"SC4-1-u3-X14"},{"t":"바다","mis":"SC4-1-u3-X14"},{"t":"모래밭","mis":"SC4-1-u3-X14"}],"explanation":["큰 바위를 떠올려요.","깎이는 곳이에요.","상류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#2','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C20',2,'mc','auto','「경사」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X21','SC4-1-u3-X19']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C20","difficulty":2,"kind":"mc","stem":"「경사」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"기울어진 정도","correct":true},{"t":"강을 가로질러 잰 길이","mis":"SC4-1-u3-X21"},{"t":"물이 흐르는 빠르기","mis":"SC4-1-u3-X19"},{"t":"강에 쌓인 모래의 양","mis":"SC4-1-u3-X21"}],"explanation":["비탈을 떠올려요.","얼마나 기울었나요?","기울어진 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#3','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C16',3,'error','auto','강 사진을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X15','SC4-1-u3-X16']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C16","difficulty":3,"kind":"error","stem":"강 사진을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「강 상류에서는 침식 작용만 일어나.」","correct":true,"mis_target":"SC4-1-u3-X15"},{"t":"친구 가 — 「상류는 침식 작용이 더 활발해.」","mis":"SC4-1-u3-X16"},{"t":"친구 나 — 「하류는 퇴적 작용이 더 활발해.」","mis":"SC4-1-u3-X16"}],"explanation":["「만」을 조심해요.","더 활발할 뿐이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#4','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C19',3,'mc','auto','굽은 강에서 물의 빠르기와 일어나는 일을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X19','SC4-1-u3-X20']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C19","difficulty":3,"kind":"mc","stem":"굽은 강에서 물의 빠르기와 일어나는 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"바깥쪽은 물이 빨라 침식 작용이, 안쪽은 물이 느려 퇴적 작용이 주로 일어난다","correct":true},{"t":"바깥쪽과 안쪽의 물 빠르기는 똑같다","mis":"SC4-1-u3-X19"},{"t":"바깥쪽은 물이 느려 퇴적 작용이 주로 일어난다","mis":"SC4-1-u3-X20"},{"t":"안쪽은 물이 빨라 침식 작용이 주로 일어난다","mis":"SC4-1-u3-X20"}],"explanation":["바깥쪽은 빨라요.","안쪽은 느려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#5','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C19',3,'ox','auto','강의 같은 곳이라도 바깥쪽과 안쪽은 물이 흐르는 빠르기가 달라요.',ARRAY['SC4-1-u3-X19']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C19","difficulty":3,"kind":"ox","stem":"강의 같은 곳이라도 바깥쪽과 안쪽은 물이 흐르는 빠르기가 달라요.","answer":"O","reason_options":[{"t":"굽은 강의 바깥쪽은 빠르고 안쪽은 느리기 때문에","correct":true},{"t":"강의 한 곳에서는 물이 늘 같은 빠르기로 흐르기 때문에","mis":"SC4-1-u3-X19"}],"mis":"SC4-1-u3-X19","explanation":["굽은 곳을 떠올려요.","빠르기가 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#6','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C17',3,'mc','auto','강 상류의 큰 바위와 강 하류의 고운 모래 사이의 관계로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X17']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C17","difficulty":3,"kind":"mc","stem":"강 상류의 큰 바위와 강 하류의 고운 모래 사이의 관계로 가장 알맞은 것은 무엇인가요?","options":[{"t":"상류에서 깎인 바위 조각이 운반되며 작아져 하류에 쌓인다","correct":true},{"t":"하류의 모래가 물을 거슬러 상류로 올라가 바위가 된다","mis":"SC4-1-u3-X17"},{"t":"둘은 아무 관계가 없다","mis":"SC4-1-u3-X17"},{"t":"하류의 모래는 비에 섞여 하늘에서 내린 것이다","mis":"SC4-1-u3-X17"}],"explanation":["물은 위에서 아래로요.","깎이고 옮겨져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#7','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C15',3,'mc','auto','「강 주변의 모습 ㉮와 ㉯」에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X16','SC4-1-u3-X14','SC4-1-u3-X15']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C15","difficulty":3,"kind":"mc","stem":"「강 주변의 모습 ㉮와 ㉯」에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"㉯는 퇴적 작용이 침식 작용보다 활발한 곳이다","correct":true},{"t":"㉮는 퇴적 작용이 침식 작용보다 활발한 곳이다","mis":"SC4-1-u3-X16"},{"t":"㉯는 강 상류의 모습이다","mis":"SC4-1-u3-X14"},{"t":"㉮와 ㉯는 같은 작용만 일어나 모습이 같다","mis":"SC4-1-u3-X15"}],"explanation":["㉯는 모래가 쌓였어요.","하류예요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 강의 경사가 급하다.","㉮ 큰 바위와 모난 돌이 많다.","㉯ 강폭이 넓고 강의 경사가 완만하다.","㉯ 고운 모래와 흙이 많이 쌓여 있다."],"title":"강 주변의 모습 ㉮와 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#8','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C19',4,'mc','auto','친구가 「강은 처음 생길 때부터 지금처럼 구불구불했어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X21','SC4-1-u3-X20','SC4-1-u3-X19']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C19","difficulty":4,"kind":"mc","stem":"친구가 「강은 처음 생길 때부터 지금처럼 구불구불했어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「바깥쪽은 깎이고 안쪽은 쌓이면서 오랜 시간에 걸쳐 점점 구불구불해진 거야.」","correct":true},{"t":"「맞아, 강의 모양은 변하지 않아.」","mis":"SC4-1-u3-X21"},{"t":"「강 안쪽이 깎이고 바깥쪽이 쌓여서 그래.」","mis":"SC4-1-u3-X20"},{"t":"「강의 모든 곳은 물이 똑같이 흘러.」","mis":"SC4-1-u3-X19"}],"explanation":["바깥쪽과 안쪽을 봐요.","오랜 시간이 걸려요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#9','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C16',4,'mc','auto','친구가 「강 상류는 깎이는 곳이니까 모래나 흙이 하나도 쌓이지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X15','SC4-1-u3-X16','SC4-1-u3-X14']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C16","difficulty":4,"kind":"mc","stem":"친구가 「강 상류는 깎이는 곳이니까 모래나 흙이 하나도 쌓이지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「상류에서도 쌓이는 일이 일어나. 다만 깎이는 일이 더 활발할 뿐이야.」","correct":true},{"t":"「맞아, 상류는 침식 작용만 일어나.」","mis":"SC4-1-u3-X15"},{"t":"「상류는 퇴적 작용이 가장 활발해.」","mis":"SC4-1-u3-X16"},{"t":"「상류에는 물이 흐르지 않아.」","mis":"SC4-1-u3-X14"}],"explanation":["세 작용은 함께예요.","더 활발한 것이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L03_challenge#10','sci',4,1,'u3','L03','g4_1_sci_u3_L03_challenge','lesson_challenge','SC4-1-u3-C16',4,'essay','teacher','「강 주변의 모습 ㉮와 ㉯」를 보고 ㉮와 ㉯가 각각 강의 어느 곳인지 쓰고, 두 곳의 모습이 다른 까닭을 흐르는 물의 작용과 관련지어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C16","difficulty":4,"kind":"essay","stem":"「강 주변의 모습 ㉮와 ㉯」를 보고 ㉮와 ㉯가 각각 강의 어느 곳인지 쓰고, 두 곳의 모습이 다른 까닭을 흐르는 물의 작용과 관련지어 쓰세요.","answer_guide":{"answer":"예: ㉮는 강 상류, ㉯는 강 하류이다. 강 상류는 경사가 급해 침식 작용이 퇴적 작용보다 활발해서 큰 바위와 모난 돌이 많다. 강 하류는 경사가 완만해 퇴적 작용이 침식 작용보다 활발해서 모래와 흙이 쌓인다.","scoring_points":["㉮와 ㉯를 바르게 썼는가","상류에서 침식 작용이 더 활발함을 썼는가","하류에서 퇴적 작용이 더 활발함을 썼는가"]},"explanation":["㉮와 ㉯를 읽어요.","더 활발한 작용을 떠올려요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 강의 경사가 급하다.","㉮ 큰 바위와 모난 돌이 많다.","㉯ 강폭이 넓고 강의 경사가 완만하다.","㉯ 고운 모래와 흙이 많이 쌓여 있다."],"title":"강 주변의 모습 ㉮와 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#1','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C21',1,'mc','auto','땅속 깊은 곳에서 암석이 녹아 있는 것을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X22','SC4-1-u3-X26']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C21","difficulty":1,"kind":"mc","stem":"땅속 깊은 곳에서 암석이 녹아 있는 것을 무엇이라고 하나요?","options":[{"t":"마그마","correct":true},{"t":"용암","mis":"SC4-1-u3-X22"},{"t":"화산재","mis":"SC4-1-u3-X26"},{"t":"화산 가스","mis":"SC4-1-u3-X26"}],"explanation":["땅속 깊은 곳이에요.","녹아 있어요.","마그마예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#2','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C25',1,'mc','auto','액체 상태의 화산 분출물은 무엇인가요?',ARRAY['SC4-1-u3-X26']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C25","difficulty":1,"kind":"mc","stem":"액체 상태의 화산 분출물은 무엇인가요?","options":[{"t":"용암","correct":true},{"t":"화산 가스","mis":"SC4-1-u3-X26"},{"t":"화산재","mis":"SC4-1-u3-X26"},{"t":"화산 암석 조각","mis":"SC4-1-u3-X26"}],"explanation":["흘러요.","액체예요.","용암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#3','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C23',1,'ox','auto','꼭대기에 분화구가 있는 산은 화산이라고 할 수 있어요.',ARRAY['SC4-1-u3-X27']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C23","difficulty":1,"kind":"ox","stem":"꼭대기에 분화구가 있는 산은 화산이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"분화구는 마그마가 분출하면서 생긴 움푹 파인 곳이기 때문에","correct":true},{"t":"분화구는 사람이 일부러 판 곳이기 때문에","mis":"SC4-1-u3-X27"}],"mis":"SC4-1-u3-X27","explanation":["분화구를 떠올려요.","분출하며 생겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#4','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C22',1,'sa','auto','화산이 분출하면서 생긴 움푹 파인 곳을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C22","difficulty":1,"kind":"sa","stem":"화산이 분출하면서 생긴 움푹 파인 곳을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["분화구"],"explanation":["꼭대기를 봐요.","움푹 파였어요.","분화구예요."],"mis":"SC4-1-u3-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#5','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C25',2,'match','auto','화산 분출물과 물질의 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C25","difficulty":2,"kind":"match","stem":"화산 분출물과 물질의 상태를 알맞게 이으세요.","pairs":[{"l":"화산 가스","r":"기체"},{"l":"용암","r":"액체"},{"l":"화산재","r":"고체"}],"mis":"SC4-1-u3-X26","explanation":["가스는 기체예요.","용암은 흘러요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#6','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C23',2,'mc','auto','화산과 화산이 아닌 산을 구분하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X24','SC4-1-u3-X25']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C23","difficulty":2,"kind":"mc","stem":"화산과 화산이 아닌 산을 구분하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"물질이 분출하는지, 분화구가 있는지 살펴본다","correct":true},{"t":"꼭대기에 눈이 쌓였는지 살펴본다","mis":"SC4-1-u3-X24"},{"t":"산이 얼마나 높은지만 살펴본다","mis":"SC4-1-u3-X24"},{"t":"모든 화산은 생김새가 같으니 모양만 본다","mis":"SC4-1-u3-X25"}],"explanation":["화산의 특징을 떠올려요.","분출과 분화구예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#7','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C27',2,'mc','auto','「화산 활동 모형실험」 ②에서 피어오른 연기는 실제 화산 활동의 무엇에 해당하나요?',ARRAY['SC4-1-u3-X28']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C27","difficulty":2,"kind":"mc","stem":"「화산 활동 모형실험」 ②에서 피어오른 연기는 실제 화산 활동의 무엇에 해당하나요?","options":[{"t":"화산 가스","correct":true},{"t":"용암","mis":"SC4-1-u3-X28"},{"t":"화산 암석 조각","mis":"SC4-1-u3-X28"},{"t":"분화구","mis":"SC4-1-u3-X28"}],"explanation":["②를 읽어요.","연기는 기체예요.","화산 가스예요."],"asset":{"type":"passage","lines":["① 알루미늄 포일로 화산 모형을 만들고 마시멜로와 빨간 색소를 넣었다.","② 모형을 가열하자 냄새가 나고 입구에서 연기가 피어올랐다.","③ 녹은 마시멜로가 흘러내리고 작은 덩어리가 튀었다.","④ 시간이 지나자 흘러내린 마시멜로가 식어 굳었다."],"title":"화산 활동 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#8','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C24',2,'ox','auto','용암은 마그마가 땅 위로 분출하여 흐르는 것이에요.',ARRAY['SC4-1-u3-X22']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C24","difficulty":2,"kind":"ox","stem":"용암은 마그마가 땅 위로 분출하여 흐르는 것이에요.","answer":"O","reason_options":[{"t":"땅속에 있으면 마그마, 땅 위로 나와 흐르면 용암이기 때문에","correct":true},{"t":"용암은 땅속 깊은 곳에 녹아 있는 암석이기 때문에","mis":"SC4-1-u3-X22"}],"mis":"SC4-1-u3-X22","explanation":["어디에 있나요?","땅 위로 나왔어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#9','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C29',2,'mc','auto','화산 활동 모형실험을 할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X31']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C29","difficulty":2,"kind":"mc","stem":"화산 활동 모형실험을 할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"보안경과 두꺼운 면장갑을 끼고, 실험 재료는 먹지 않는다","correct":true},{"t":"녹은 마시멜로를 맛본다","mis":"SC4-1-u3-X31"},{"t":"가열한 포일을 맨손으로 만진다","mis":"SC4-1-u3-X31"},{"t":"창문을 모두 닫고 실험한다","mis":"SC4-1-u3-X31"}],"explanation":["뜨거워요.","연기도 나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_basic#10','sci',4,1,'u3','L04','g4_1_sci_u3_L04_basic','lesson_basic','SC4-1-u3-C26',3,'mc','auto','화산에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X23','SC4-1-u3-X26']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C26","difficulty":3,"kind":"mc","stem":"화산에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"용암이 나오지 않고 화산재나 화산 가스가 주로 나올 때도 있다","correct":true},{"t":"용암이 흘러나와야만 화산이다","mis":"SC4-1-u3-X23"},{"t":"화산에서는 용암 한 가지만 나온다","mis":"SC4-1-u3-X23"},{"t":"화산 가스는 고체 상태의 분출물이다","mis":"SC4-1-u3-X26"}],"explanation":["여러 물질이 나와요.","한두 가지만 나오기도 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#1','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C22',2,'blank','auto','「화산은 땅속의 (      )이/가 분출하여 만들어진 산이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X24','SC4-1-u3-X27','SC4-1-u3-X26']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C22","difficulty":2,"kind":"blank","stem":"「화산은 땅속의 (      )이/가 분출하여 만들어진 산이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"마그마","correct":true},{"t":"눈","mis":"SC4-1-u3-X24"},{"t":"흙탕물","mis":"SC4-1-u3-X27"},{"t":"화산 암석 조각","mis":"SC4-1-u3-X26"}],"explanation":["땅속에 녹아 있어요.","분출해요.","마그마예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#2','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C28',2,'mc','auto','모형실험과 실제 화산 활동의 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X29','SC4-1-u3-X23','SC4-1-u3-X28']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C28","difficulty":2,"kind":"mc","stem":"모형실험과 실제 화산 활동의 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"모형실험에서는 단단한 암석 조각이 나오지 않는다","correct":true},{"t":"모형실험과 실제 화산 활동은 모든 것이 똑같다","mis":"SC4-1-u3-X29"},{"t":"실제 화산에서는 아무 물질도 나오지 않는다","mis":"SC4-1-u3-X23"},{"t":"모형실험에서는 연기가 전혀 나지 않는다","mis":"SC4-1-u3-X28"}],"explanation":["③을 떠올려요.","마시멜로는 말랑해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#3','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C26',3,'error','auto','화산 사진을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X23','SC4-1-u3-X27','SC4-1-u3-X26']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C26","difficulty":3,"kind":"error","stem":"화산 사진을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「용암이 보이지 않으니 이 산은 화산이 아니야.」","correct":true,"mis_target":"SC4-1-u3-X23"},{"t":"친구 가 — 「꼭대기에 분화구가 있어.」","mis":"SC4-1-u3-X27"},{"t":"친구 다 — 「화산재와 화산 가스가 나오고 있어.」","mis":"SC4-1-u3-X26"}],"explanation":["용암만 보면 안 돼요.","분화구와 분출물을 봐요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#4','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C27',3,'mc','auto','「화산 활동 모형실험」 ③에서 흘러내린 마시멜로와 튄 덩어리는 실제 화산 활동의 무엇에 해당하나요?',ARRAY['SC4-1-u3-X28','SC4-1-u3-X22']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C27","difficulty":3,"kind":"mc","stem":"「화산 활동 모형실험」 ③에서 흘러내린 마시멜로와 튄 덩어리는 실제 화산 활동의 무엇에 해당하나요?","options":[{"t":"흘러내린 마시멜로는 용암, 튄 덩어리는 화산 암석 조각","correct":true},{"t":"흘러내린 마시멜로는 화산 가스, 튄 덩어리는 용암","mis":"SC4-1-u3-X28"},{"t":"흘러내린 마시멜로는 마그마, 튄 덩어리는 분화구","mis":"SC4-1-u3-X22"},{"t":"둘 다 화산 가스","mis":"SC4-1-u3-X28"}],"explanation":["③을 읽어요.","흐르는 것과 튄 것이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 알루미늄 포일로 화산 모형을 만들고 마시멜로와 빨간 색소를 넣었다.","② 모형을 가열하자 냄새가 나고 입구에서 연기가 피어올랐다.","③ 녹은 마시멜로가 흘러내리고 작은 덩어리가 튀었다.","④ 시간이 지나자 흘러내린 마시멜로가 식어 굳었다."],"title":"화산 활동 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#5','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C29',3,'mc','auto','화산 활동이 끝난 뒤 흘러나온 용암은 어떻게 될까요?',ARRAY['SC4-1-u3-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C29","difficulty":3,"kind":"mc","stem":"화산 활동이 끝난 뒤 흘러나온 용암은 어떻게 될까요?","options":[{"t":"점점 식으면서 단단하게 굳어 암석이 된다","correct":true},{"t":"물이 되어 강으로 흘러간다","mis":"SC4-1-u3-X30"},{"t":"모두 하늘로 날아간다","mis":"SC4-1-u3-X30"},{"t":"언제까지나 뜨겁게 흐른다","mis":"SC4-1-u3-X30"}],"explanation":["④를 떠올려요.","식으면 굳어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#6','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C22',3,'ox','auto','화산의 분화구에 물이 고이면 호수가 되기도 해요.',ARRAY['SC4-1-u3-X27']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C22","difficulty":3,"kind":"ox","stem":"화산의 분화구에 물이 고이면 호수가 되기도 해요.","answer":"O","reason_options":[{"t":"분화구는 움푹 파인 곳이라 물이 고일 수 있기 때문에","correct":true},{"t":"분화구는 늘 뾰족하게 솟은 곳이기 때문에","mis":"SC4-1-u3-X27"}],"mis":"SC4-1-u3-X27","explanation":["움푹 파였어요.","물이 고여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#7','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C25',3,'mc','auto','「화산 활동」과 「화산 분출물」을 바르게 구별한 것은 무엇인가요?',ARRAY['SC4-1-u3-X32']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C25","difficulty":3,"kind":"mc","stem":"「화산 활동」과 「화산 분출물」을 바르게 구별한 것은 무엇인가요?","options":[{"t":"화산 활동은 물질이 나오는 일이고, 화산 분출물은 나온 물질이다","correct":true},{"t":"화산 활동과 화산 분출물은 같은 뜻이다","mis":"SC4-1-u3-X32"},{"t":"화산 분출물은 물질이 나오는 일이다","mis":"SC4-1-u3-X32"},{"t":"화산 활동은 나온 물질의 이름이다","mis":"SC4-1-u3-X32"}],"explanation":["일과 물질을 나눠요.","나온 것이 분출물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#8','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C23',4,'mc','auto','친구가 「저 산은 꼭대기에 하얀 눈이 쌓였으니 화산이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X24','SC4-1-u3-X23','SC4-1-u3-X25']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C23","difficulty":4,"kind":"mc","stem":"친구가 「저 산은 꼭대기에 하얀 눈이 쌓였으니 화산이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「눈은 화산의 특징이 아니야. 분출하는 물질이나 분화구가 있는지 봐야 해.」","correct":true},{"t":"「맞아, 높은 산은 모두 화산이야.」","mis":"SC4-1-u3-X24"},{"t":"「용암이 흐르는지만 보면 돼.」","mis":"SC4-1-u3-X23"},{"t":"「화산은 모두 생김새가 같아서 바로 알 수 있어.」","mis":"SC4-1-u3-X25"}],"explanation":["눈은 다른 산에도 쌓여요.","분출·분화구를 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#9','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C28',4,'mc','auto','친구가 「모형실험에서 빨간 액체가 흘렀으니 실제 화산 활동과 모든 것이 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X29','SC4-1-u3-X28','SC4-1-u3-X22']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C28","difficulty":4,"kind":"mc","stem":"친구가 「모형실험에서 빨간 액체가 흘렀으니 실제 화산 활동과 모든 것이 똑같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「흘러나와 굳는 점은 같지만, 모형에서는 단단한 암석 조각이 나오지 않고 연기 색도 달라.」","correct":true},{"t":"「맞아, 모형과 실제는 완전히 똑같아.」","mis":"SC4-1-u3-X29"},{"t":"「마시멜로는 화산 가스에 해당해.」","mis":"SC4-1-u3-X28"},{"t":"「모형에서 흐른 것은 땅속 마그마를 그대로 보여 줘.」","mis":"SC4-1-u3-X22"}],"explanation":["같은 점과 다른 점이 있어요.","암석 조각을 떠올려요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L04_challenge#10','sci',4,1,'u3','L04','g4_1_sci_u3_L04_challenge','lesson_challenge','SC4-1-u3-C27',4,'essay','teacher','「화산 활동 모형실험」을 보고 연기·흘러내린 마시멜로·튄 덩어리가 실제 화산 활동의 무엇에 해당하는지 쓰고, 모형실험과 실제 화산 활동의 다른 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C27","difficulty":4,"kind":"essay","stem":"「화산 활동 모형실험」을 보고 연기·흘러내린 마시멜로·튄 덩어리가 실제 화산 활동의 무엇에 해당하는지 쓰고, 모형실험과 실제 화산 활동의 다른 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 연기는 화산 가스, 흘러내린 마시멜로는 용암, 튄 덩어리는 화산 암석 조각에 해당한다. 모형실험에서는 단단한 암석 조각이 나오지 않지만 실제 화산에서는 나온다.","scoring_points":["세 가지를 바르게 짝 지었는가","다른 점을 한 가지 바르게 썼는가","실제 화산 활동의 분출물 이름을 바르게 썼는가"]},"explanation":["②~③을 읽어요.","하나씩 짝 지어요.","다른 점을 써요."],"asset":{"type":"passage","lines":["① 알루미늄 포일로 화산 모형을 만들고 마시멜로와 빨간 색소를 넣었다.","② 모형을 가열하자 냄새가 나고 입구에서 연기가 피어올랐다.","③ 녹은 마시멜로가 흘러내리고 작은 덩어리가 튀었다.","④ 시간이 지나자 흘러내린 마시멜로가 식어 굳었다."],"title":"화산 활동 모형실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#1','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C30',1,'mc','auto','마그마가 식어서 만들어진 암석을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X37']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C30","difficulty":1,"kind":"mc","stem":"마그마가 식어서 만들어진 암석을 무엇이라고 하나요?","options":[{"t":"화성암","correct":true},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"용암","mis":"SC4-1-u3-X37"},{"t":"분화구","mis":"SC4-1-u3-X37"}],"explanation":["마그마가 식었어요.","암석이에요.","화성암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#2','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C31',1,'mc','auto','현무암의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X33']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C31","difficulty":1,"kind":"mc","stem":"현무암의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"색이 어두운 편이다","correct":true},{"t":"색이 밝은 편이다","mis":"SC4-1-u3-X33"},{"t":"알갱이가 커서 눈으로 잘 보인다","mis":"SC4-1-u3-X33"},{"t":"분홍색 알갱이가 많이 섞여 있다","mis":"SC4-1-u3-X33"}],"explanation":["돌하르방을 떠올려요.","어두워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#3','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C32',1,'ox','auto','화강암은 알갱이가 커서 눈으로 잘 보여요.',ARRAY['SC4-1-u3-X33']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C32","difficulty":1,"kind":"ox","stem":"화강암은 알갱이가 커서 눈으로 잘 보여요.","answer":"O","reason_options":[{"t":"화강암을 이루는 알갱이가 크기 때문에","correct":true},{"t":"화강암은 알갱이가 아주 작기 때문에","mis":"SC4-1-u3-X33"}],"mis":"SC4-1-u3-X33","explanation":["화강암을 떠올려요.","알갱이가 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#4','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C34',1,'sa','auto','제주도의 돌하르방을 만든 암석은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C34","difficulty":1,"kind":"sa","stem":"제주도의 돌하르방을 만든 암석은 무엇인가요? 세 글자로 쓰세요.","answer":["현무암"],"explanation":["어둡고 구멍이 있어요.","「현○○」이에요.","현무암이에요."],"mis":"SC4-1-u3-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#5','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C32',2,'match','auto','암석과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C32","difficulty":2,"kind":"match","stem":"암석과 특징을 알맞게 이으세요.","pairs":[{"l":"현무암","r":"색이 어둡고 알갱이가 작다"},{"l":"화강암","r":"색이 밝고 알갱이가 크다"},{"l":"화성암","r":"마그마가 식어서 만들어진 암석"}],"mis":"SC4-1-u3-X33","explanation":["색을 견줘요.","알갱이 크기도요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#6','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C33',2,'mc','auto','현무암과 화강암을 나누는 기준으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C33","difficulty":2,"kind":"mc","stem":"현무암과 화강암을 나누는 기준으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"색깔과 알갱이의 크기","correct":true},{"t":"암석의 무게","mis":"SC4-1-u3-X36"},{"t":"암석 덩어리의 크기","mis":"SC4-1-u3-X36"},{"t":"암석을 주운 장소","mis":"SC4-1-u3-X36"}],"explanation":["두 암석의 차이를 떠올려요.","색과 알갱이예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#7','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C34',2,'mc','auto','석굴암을 만든 암석으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X38','SC4-1-u3-X37']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C34","difficulty":2,"kind":"mc","stem":"석굴암을 만든 암석으로 알맞은 것은 무엇인가요?","options":[{"t":"화강암","correct":true},{"t":"현무암","mis":"SC4-1-u3-X38"},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"용암","mis":"SC4-1-u3-X37"}],"explanation":["밝은 돌이에요.","알갱이가 커요.","화강암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#8','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C31',2,'ox','auto','현무암은 모두 겉에 구멍이 뚫려 있어요.',ARRAY['SC4-1-u3-X34']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C31","difficulty":2,"kind":"ox","stem":"현무암은 모두 겉에 구멍이 뚫려 있어요.","answer":"X","reason_options":[{"t":"구멍이 없는 현무암도 있기 때문에","correct":true},{"t":"현무암이라면 반드시 구멍이 있기 때문에","mis":"SC4-1-u3-X34"}],"mis":"SC4-1-u3-X34","explanation":["「모두」를 조심해요.","구멍 없는 것도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#9','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C35',2,'mc','auto','암석을 관찰하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X39']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C35","difficulty":2,"kind":"mc","stem":"암석을 관찰하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"맨눈으로 먼저 보고 돋보기로 자세히 관찰한다","correct":true},{"t":"암석을 입에 대어 맛을 본다","mis":"SC4-1-u3-X39"},{"t":"면장갑 없이 맨손으로 문지르고 손을 씻지 않는다","mis":"SC4-1-u3-X39"},{"t":"암석 알갱이를 흙 알갱이처럼 물에 풀어 본다","mis":"SC4-1-u3-X39"}],"explanation":["눈으로 보아요.","돋보기도 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_basic#10','sci',4,1,'u3','L05','g4_1_sci_u3_L05_basic','lesson_basic','SC4-1-u3-C32',3,'mc','auto','「암석 표본 ㉠~㉣」에서 화강암을 모두 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X33','SC4-1-u3-X35']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C32","difficulty":3,"kind":"mc","stem":"「암석 표본 ㉠~㉣」에서 화강암을 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠, ㉡","mis":"SC4-1-u3-X33"},{"t":"㉡, ㉢","mis":"SC4-1-u3-X33"},{"t":"㉠만","mis":"SC4-1-u3-X35"}],"explanation":["밝은 것을 찾아요.","분홍색도 화강암일 수 있어요.","㉠, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 색이 밝고, 알갱이가 커서 눈으로 잘 보인다.","㉡ 색이 어둡고, 알갱이가 작아 눈으로 구별하기 어렵다.","㉢ 색이 어둡고 알갱이가 작으며, 겉에 구멍이 없다.","㉣ 색이 밝고, 분홍색 알갱이가 많이 섞여 있다."],"title":"암석 표본 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#1','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C30',2,'blank','auto','「현무암과 화강암은 마그마가 식어서 만들어진 (      )이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X37']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C30","difficulty":2,"kind":"blank","stem":"「현무암과 화강암은 마그마가 식어서 만들어진 (      )이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"화성암","correct":true},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"모래","mis":"SC4-1-u3-X37"},{"t":"분출물","mis":"SC4-1-u3-X37"}],"explanation":["마그마가 식었어요.","암석의 이름이에요.","화성암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#2','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C34',2,'mc','auto','제주도의 돌담은 색이 어둡고 겉에 구멍이 있어요. 어느 암석으로 만들었을까요?',ARRAY['SC4-1-u3-X38','SC4-1-u3-X37']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C34","difficulty":2,"kind":"mc","stem":"제주도의 돌담은 색이 어둡고 겉에 구멍이 있어요. 어느 암석으로 만들었을까요?","options":[{"t":"현무암","correct":true},{"t":"화강암","mis":"SC4-1-u3-X38"},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"용암","mis":"SC4-1-u3-X37"}],"explanation":["어둡고 구멍이 있어요.","돌하르방과 같아요.","현무암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#3','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C31',3,'error','auto','암석을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X34','SC4-1-u3-X36']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C31","difficulty":3,"kind":"error","stem":"암석을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「구멍이 없으니 이 어두운 암석은 현무암일 리가 없어.」","correct":true,"mis_target":"SC4-1-u3-X34"},{"t":"친구 나 — 「구멍이 없는 현무암도 있어.」","mis":"SC4-1-u3-X34"},{"t":"친구 다 — 「색깔과 알갱이의 크기를 함께 봐야 해.」","mis":"SC4-1-u3-X36"}],"explanation":["구멍만 보면 안 돼요.","색과 알갱이를 봐요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
