INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#5','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C32',3,'ox','auto','화강암은 모두 흰색과 검은색 알갱이로만 되어 있어요.',ARRAY['SC4-1-u3-X35']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C32","difficulty":3,"kind":"ox","stem":"화강암은 모두 흰색과 검은색 알갱이로만 되어 있어요.","answer":"X","reason_options":[{"t":"분홍색이나 반짝이는 알갱이가 섞인 화강암도 있기 때문에","correct":true},{"t":"화강암에는 다른 색 알갱이가 섞일 수 없기 때문에","mis":"SC4-1-u3-X35"}],"mis":"SC4-1-u3-X35","explanation":["「모두」를 조심해요.","분홍색도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#6','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C33',3,'mc','auto','암석을 분류하는 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-1-u3-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C33","difficulty":3,"kind":"mc","stem":"암석을 분류하는 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"「손에 쥐었을 때 기분이 좋은가?」","correct":true},{"t":"「색깔이 밝은가?」","mis":"SC4-1-u3-X36"},{"t":"「알갱이가 눈에 잘 보이는가?」","mis":"SC4-1-u3-X36"},{"t":"「알갱이의 크기가 큰가?」","mis":"SC4-1-u3-X36"}],"explanation":["누가 해도 같은 답이 나와야 해요.","기분은 사람마다 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#7','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C35',3,'mc','auto','현무암과 화강암을 관찰할 때 말하는 「알갱이」로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X39','SC4-1-u3-X37']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C35","difficulty":3,"kind":"mc","stem":"현무암과 화강암을 관찰할 때 말하는 「알갱이」로 알맞은 것은 무엇인가요?","options":[{"t":"암석을 이루는 알갱이","correct":true},{"t":"흙 언덕의 흙 알갱이","mis":"SC4-1-u3-X39"},{"t":"강 하류의 모래 알갱이","mis":"SC4-1-u3-X39"},{"t":"화산재 가루","mis":"SC4-1-u3-X37"}],"explanation":["암석 속을 들여다봐요.","흙 알갱이가 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#8','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C32',4,'mc','auto','친구가 「분홍색 알갱이가 많은 이 밝은 암석은 흰색과 검은색이 아니니 화강암이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X35','SC4-1-u3-X33','SC4-1-u3-X36']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C32","difficulty":4,"kind":"mc","stem":"친구가 「분홍색 알갱이가 많은 이 밝은 암석은 흰색과 검은색이 아니니 화강암이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「색이 밝고 알갱이가 크면 화강암이야. 분홍색 알갱이가 많은 화강암도 있어.」","correct":true},{"t":"「맞아, 화강암은 흰색과 검은색뿐이야.」","mis":"SC4-1-u3-X35"},{"t":"「분홍색이니 현무암이야.」","mis":"SC4-1-u3-X33"},{"t":"「무게를 재 봐야 알 수 있어.」","mis":"SC4-1-u3-X36"}],"explanation":["밝고 알갱이가 커요.","분홍색도 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#9','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C31',4,'mc','auto','친구가 「현무암은 구멍이 있는 암석이니까 구멍만 보면 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X34','SC4-1-u3-X33']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C31","difficulty":4,"kind":"mc","stem":"친구가 「현무암은 구멍이 있는 암석이니까 구멍만 보면 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「구멍이 없는 현무암도 있어. 색깔과 알갱이의 크기를 함께 봐야 해.」","correct":true},{"t":"「맞아, 구멍만 보면 돼.」","mis":"SC4-1-u3-X34"},{"t":"「구멍이 있으면 모두 화강암이야.」","mis":"SC4-1-u3-X33"},{"t":"「현무암은 알갱이가 커서 잘 보여.」","mis":"SC4-1-u3-X33"}],"explanation":["㉢을 떠올려요.","두 기준을 함께 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L05_challenge#10','sci',4,1,'u3','L05','g4_1_sci_u3_L05_challenge','lesson_challenge','SC4-1-u3-C33',4,'essay','teacher','「암석 표본 ㉠~㉣」을 현무암과 화강암으로 나누고, 어떤 기준으로 나누었는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C33","difficulty":4,"kind":"essay","stem":"「암석 표본 ㉠~㉣」을 현무암과 화강암으로 나누고, 어떤 기준으로 나누었는지 쓰세요.","answer_guide":{"answer":"예: ㉠과 ㉣은 화강암, ㉡과 ㉢은 현무암이다. 색깔이 밝고 알갱이가 큰지, 색깔이 어둡고 알갱이가 작은지를 기준으로 나누었다. ㉢처럼 구멍이 없어도 색이 어둡고 알갱이가 작으면 현무암이다.","scoring_points":["네 표본을 바르게 나누었는가","색깔과 알갱이의 크기를 기준으로 썼는가","㉢·㉣처럼 헷갈리는 표본의 까닭을 썼는가"]},"explanation":["색을 먼저 봐요.","알갱이도 봐요.","기준을 써요."],"asset":{"type":"passage","lines":["㉠ 색이 밝고, 알갱이가 커서 눈으로 잘 보인다.","㉡ 색이 어둡고, 알갱이가 작아 눈으로 구별하기 어렵다.","㉢ 색이 어둡고 알갱이가 작으며, 겉에 구멍이 없다.","㉣ 색이 밝고, 분홍색 알갱이가 많이 섞여 있다."],"title":"암석 표본 ㉠~㉣"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#1','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C36',1,'mc','auto','용암이 산이나 마을로 흐르면 어떤 피해가 생길 수 있나요?',ARRAY['SC4-1-u3-X42','SC4-1-u3-X41']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C36","difficulty":1,"kind":"mc","stem":"용암이 산이나 마을로 흐르면 어떤 피해가 생길 수 있나요?","options":[{"t":"산불이나 화재가 난다","correct":true},{"t":"눈이 많이 내린다","mis":"SC4-1-u3-X42"},{"t":"무지개가 자주 뜬다","mis":"SC4-1-u3-X42"},{"t":"땅이 곧바로 비옥해진다","mis":"SC4-1-u3-X41"}],"explanation":["용암은 뜨거워요.","불이 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#2','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C38',1,'mc','auto','화산 활동의 이로운 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X45']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C38","difficulty":1,"kind":"mc","stem":"화산 활동의 이로운 점으로 알맞은 것은 무엇인가요?","options":[{"t":"온천을 관광지로 개발할 수 있다","correct":true},{"t":"화산재가 비행기 운항을 막는다","mis":"SC4-1-u3-X41"},{"t":"바람으로 전기를 만든다","mis":"SC4-1-u3-X45"},{"t":"우주로 가는 길을 열어 준다","mis":"SC4-1-u3-X45"}],"explanation":["도움이 되는 점이에요.","따뜻한 물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#3','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C39',1,'ox','auto','화산 활동은 우리 생활에 피해만 줘요.',ARRAY['SC4-1-u3-X40']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C39","difficulty":1,"kind":"ox","stem":"화산 활동은 우리 생활에 피해만 줘요.","answer":"X","reason_options":[{"t":"피해도 주지만 비옥한 땅·온천처럼 이로운 점도 있기 때문에","correct":true},{"t":"화산 활동에는 이로운 점이 하나도 없기 때문에","mis":"SC4-1-u3-X40"}],"mis":"SC4-1-u3-X40","explanation":["「만」을 조심해요.","이로운 점도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#4','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C37',1,'sa','auto','비행기 운항을 어렵게 하고 마을과 농경지를 뒤덮는 화산 분출물은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C37","difficulty":1,"kind":"sa","stem":"비행기 운항을 어렵게 하고 마을과 농경지를 뒤덮는 화산 분출물은 무엇인가요? 세 글자로 쓰세요.","answer":["화산재"],"explanation":["고체 분출물이에요.","가루처럼 퍼져요.","화산재예요."],"mis":"SC4-1-u3-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#5','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C38',2,'match','auto','무엇을 이용한 것인지 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C38","difficulty":2,"kind":"match","stem":"무엇을 이용한 것인지 알맞게 이으세요.","pairs":[{"l":"온천","r":"땅속에서 데워진 따뜻한 물"},{"l":"전기 생산","r":"땅속의 높은 열"},{"l":"농작물 재배","r":"화산재가 쌓여 비옥해진 땅"}],"mis":"SC4-1-u3-X46","explanation":["㉡, ㉣, ㉥을 떠올려요.","무엇을 썼나요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#6','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C40',2,'mc','auto','화산이 분출할 때 바깥에 있다면 어떻게 해야 하나요?',ARRAY['SC4-1-u3-X44']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C40","difficulty":2,"kind":"mc","stem":"화산이 분출할 때 바깥에 있다면 어떻게 해야 하나요?","options":[{"t":"마스크나 손수건으로 코와 입을 막고 건물 안으로 대피한다","correct":true},{"t":"화산 가까이 가서 구경한다","mis":"SC4-1-u3-X44"},{"t":"안내 방송을 듣지 않고 무작정 뛰어다닌다","mis":"SC4-1-u3-X44"},{"t":"코와 입을 막지 않고 밖에 계속 머문다","mis":"SC4-1-u3-X44"}],"explanation":["화산재와 가스를 피해요.","코와 입을 막아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#7','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C37',2,'mc','auto','화산재가 하늘 높이 퍼져 태양 빛을 가리면 어떤 일이 생길 수 있나요?',ARRAY['SC4-1-u3-X42','SC4-1-u3-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C37","difficulty":2,"kind":"mc","stem":"화산재가 하늘 높이 퍼져 태양 빛을 가리면 어떤 일이 생길 수 있나요?","options":[{"t":"기온이 낮아져 날씨가 변한다","correct":true},{"t":"기온이 높아져 더 더워진다","mis":"SC4-1-u3-X42"},{"t":"하늘이 더 맑아진다","mis":"SC4-1-u3-X42"},{"t":"농작물이 곧바로 더 잘 자란다","mis":"SC4-1-u3-X41"}],"explanation":["햇빛이 가려져요.","따뜻함이 줄어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#8','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C39',2,'ox','auto','화산 활동은 사람의 힘으로 막을 수 없는 자연 현상이에요.',ARRAY['SC4-1-u3-X43']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C39","difficulty":2,"kind":"ox","stem":"화산 활동은 사람의 힘으로 막을 수 없는 자연 현상이에요.","answer":"O","reason_options":[{"t":"사람이 마그마가 나오는 것을 멈추게 할 수 없기 때문에","correct":true},{"t":"튼튼한 벽을 쌓으면 화산 활동을 멈출 수 있기 때문에","mis":"SC4-1-u3-X43"}],"mis":"SC4-1-u3-X43","explanation":["땅속의 일이에요.","사람이 멈출 수 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#9','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C40',2,'mc','auto','화산 분출에 대비해 평소에 준비할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X44','SC4-1-u3-X43']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C40","difficulty":2,"kind":"mc","stem":"화산 분출에 대비해 평소에 준비할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"마스크·손전등·비상식량·물·라디오 같은 비상 용품","correct":true},{"t":"화산을 구경할 때 쓸 사진기만","mis":"SC4-1-u3-X44"},{"t":"아무것도 준비하지 않는다","mis":"SC4-1-u3-X44"},{"t":"화산 분출을 막을 커다란 벽","mis":"SC4-1-u3-X43"}],"explanation":["미리 챙겨요.","쓸모 있는 것이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_basic#10','sci',4,1,'u3','L06','g4_1_sci_u3_L06_basic','lesson_basic','SC4-1-u3-C36',3,'mc','auto','「조사한 붙임쪽지」에서 피해에 붙일 쪽지를 모두 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X41']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C36","difficulty":3,"kind":"mc","stem":"「조사한 붙임쪽지」에서 피해에 붙일 쪽지를 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉢, ㉤","correct":true},{"t":"㉡, ㉣, ㉥","mis":"SC4-1-u3-X41"},{"t":"㉠, ㉡, ㉢","mis":"SC4-1-u3-X41"},{"t":"㉠, ㉢, ㉤, ㉥","mis":"SC4-1-u3-X41"}],"explanation":["나쁜 일을 찾아요.","산불·비행기·숨쉬기예요.","㉠, ㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 용암이 산과 마을로 흘러 산불이 났다.","㉡ 화산재가 쌓였던 땅에서 시간이 지나 농작물이 잘 자랐다.","㉢ 화산재가 하늘을 덮어 비행기가 뜨지 못했다.","㉣ 땅속에서 데워진 따뜻한 물로 온천을 만들었다.","㉤ 화산 가스 때문에 숨쉬기 어려웠다.","㉥ 땅속의 높은 열로 전기를 만들었다."],"title":"조사한 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#1','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C38',2,'blank','auto','「화산 주변 지형이나 (      )은/는 관광지로 개발되기도 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X45']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C38","difficulty":2,"kind":"blank","stem":"「화산 주변 지형이나 (      )은/는 관광지로 개발되기도 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"온천","correct":true},{"t":"화산 가스","mis":"SC4-1-u3-X41"},{"t":"풍력 발전기","mis":"SC4-1-u3-X45"},{"t":"산불","mis":"SC4-1-u3-X41"}],"explanation":["따뜻한 물이 솟아요.","사람들이 찾아와요.","온천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#2','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C36',2,'mc','auto','화산재와 화산 가스가 사람에게 줄 수 있는 피해는 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X42','SC4-1-u3-X40']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C36","difficulty":2,"kind":"mc","stem":"화산재와 화산 가스가 사람에게 줄 수 있는 피해는 무엇인가요?","options":[{"t":"숨쉬기 어렵게 한다","correct":true},{"t":"몸을 더 튼튼하게 한다","mis":"SC4-1-u3-X41"},{"t":"눈이 더 잘 보이게 한다","mis":"SC4-1-u3-X42"},{"t":"아무 피해도 주지 않는다","mis":"SC4-1-u3-X40"}],"explanation":["공기에 섞여요.","코와 입으로 들어가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#3','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C39',3,'error','auto','조사 결과를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X40','SC4-1-u3-X41','SC4-1-u3-X46']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C39","difficulty":3,"kind":"error","stem":"조사 결과를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「화산 활동은 무섭기만 하고 우리에게 도움 되는 건 없어.」","correct":true,"mis_target":"SC4-1-u3-X40"},{"t":"친구 가 — 「화산재가 쌓인 땅은 시간이 지나면 비옥해져.」","mis":"SC4-1-u3-X41"},{"t":"친구 나 — 「땅속의 높은 열로 전기를 만들기도 해.」","mis":"SC4-1-u3-X46"}],"explanation":["이로운 점을 떠올려요.","도움도 돼요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#4','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C38',3,'mc','auto','「조사한 붙임쪽지」에서 이로운 점에 붙일 쪽지를 모두 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X40']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C38","difficulty":3,"kind":"mc","stem":"「조사한 붙임쪽지」에서 이로운 점에 붙일 쪽지를 모두 고른 것은 무엇인가요?","options":[{"t":"㉡, ㉣, ㉥","correct":true},{"t":"㉠, ㉢, ㉤","mis":"SC4-1-u3-X41"},{"t":"㉡, ㉣","mis":"SC4-1-u3-X40"},{"t":"㉢, ㉣, ㉥","mis":"SC4-1-u3-X41"}],"explanation":["도움이 되는 일이에요.","농작물·온천·전기예요.","㉡, ㉣, ㉥이에요."],"asset":{"type":"passage","lines":["㉠ 용암이 산과 마을로 흘러 산불이 났다.","㉡ 화산재가 쌓였던 땅에서 시간이 지나 농작물이 잘 자랐다.","㉢ 화산재가 하늘을 덮어 비행기가 뜨지 못했다.","㉣ 땅속에서 데워진 따뜻한 물로 온천을 만들었다.","㉤ 화산 가스 때문에 숨쉬기 어려웠다.","㉥ 땅속의 높은 열로 전기를 만들었다."],"title":"조사한 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#5','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C40',3,'mc','auto','화산이 분출했다는 안내 방송이 나왔을 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u3-X44','SC4-1-u3-X43']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C40","difficulty":3,"kind":"mc","stem":"화산이 분출했다는 안내 방송이 나왔을 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"안내 방송을 끝까지 듣고 그에 따라 침착하게 행동한다","correct":true},{"t":"방송을 끄고 밖으로 구경하러 나간다","mis":"SC4-1-u3-X44"},{"t":"친구에게 화산 사진을 찍어 오라고 한다","mis":"SC4-1-u3-X44"},{"t":"벽을 쌓아 화산을 멈추러 간다","mis":"SC4-1-u3-X43"}],"explanation":["방송이 길잡이예요.","침착하게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#6','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C37',3,'ox','auto','화산재는 비행기 운항을 막고 농작물을 뒤덮는 피해를 주기도 해요.',ARRAY['SC4-1-u3-X42']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C37","difficulty":3,"kind":"ox","stem":"화산재는 비행기 운항을 막고 농작물을 뒤덮는 피해를 주기도 해요.","answer":"O","reason_options":[{"t":"하늘과 땅을 화산재가 덮기 때문에","correct":true},{"t":"화산재는 아주 가벼워 아무것도 덮지 못하기 때문에","mis":"SC4-1-u3-X42"}],"mis":"SC4-1-u3-X42","explanation":["㉢을 떠올려요.","하늘도 땅도 덮어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#7','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C38',3,'mc','auto','화산 활동을 이용하는 일로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-1-u3-X45','SC4-1-u3-X46']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C38","difficulty":3,"kind":"mc","stem":"화산 활동을 이용하는 일로 알맞지 않은 것은 무엇인가요?","options":[{"t":"바람으로 전기를 만드는 풍력 발전","correct":true},{"t":"온천 개발","mis":"SC4-1-u3-X45"},{"t":"화산 지형 관광","mis":"SC4-1-u3-X45"},{"t":"땅속의 높은 열로 전기를 만드는 일","mis":"SC4-1-u3-X46"}],"explanation":["화산과 이어지나요?","바람은 화산과 상관없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#8','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C39',4,'mc','auto','친구가 「화산이 있는 곳에는 이로운 점이 하나도 없으니 사람이 살면 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X40','SC4-1-u3-X43','SC4-1-u3-X45']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C39","difficulty":4,"kind":"mc","stem":"친구가 「화산이 있는 곳에는 이로운 점이 하나도 없으니 사람이 살면 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「피해도 있지만 비옥한 땅, 온천, 땅속의 열 같은 이로운 점도 있어. 대처 방법을 알고 대비하면 돼.」","correct":true},{"t":"「맞아, 화산은 해로운 일만 일으켜.」","mis":"SC4-1-u3-X40"},{"t":"「벽을 쌓으면 화산을 멈출 수 있어.」","mis":"SC4-1-u3-X43"},{"t":"「화산 지형은 관광에 쓸 수 없어.」","mis":"SC4-1-u3-X45"}],"explanation":["두 쪽을 함께 봐요.","대비할 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#9','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C37',4,'mc','auto','친구가 「화산재가 하늘을 덮으면 햇빛이 모여서 땅이 더 따뜻해져.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X42','SC4-1-u3-X41']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C37","difficulty":4,"kind":"mc","stem":"친구가 「화산재가 하늘을 덮으면 햇빛이 모여서 땅이 더 따뜻해져.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「화산재가 태양 빛을 가려서 오히려 기온이 낮아지고 날씨가 변할 수 있어.」","correct":true},{"t":"「맞아, 화산재는 땅을 데워.」","mis":"SC4-1-u3-X42"},{"t":"「화산재는 하늘에 올라가지 않아.」","mis":"SC4-1-u3-X42"},{"t":"「화산재 덕분에 비행기가 더 잘 떠.」","mis":"SC4-1-u3-X41"}],"explanation":["빛을 가려요.","추워져요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L06_challenge#10','sci',4,1,'u3','L06','g4_1_sci_u3_L06_challenge','lesson_challenge','SC4-1-u3-C39',4,'essay','teacher','「조사한 붙임쪽지」를 피해와 이로운 점으로 나누어 쓰고, 화산 활동이 우리 생활에 미치는 영향을 한 문장으로 정리하세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C39","difficulty":4,"kind":"essay","stem":"「조사한 붙임쪽지」를 피해와 이로운 점으로 나누어 쓰고, 화산 활동이 우리 생활에 미치는 영향을 한 문장으로 정리하세요.","answer_guide":{"answer":"예: 피해는 ㉠, ㉢, ㉤이고 이로운 점은 ㉡, ㉣, ㉥이다. 화산 활동은 산불·비행기 운항 중단·숨쉬기 어려움 같은 피해를 주지만 비옥한 땅·온천·전기 생산 같은 이로운 점도 있다.","scoring_points":["피해 쪽지를 바르게 골랐는가","이로운 점 쪽지를 바르게 골랐는가","피해와 이로운 점을 함께 정리했는가"]},"explanation":["쪽지를 하나씩 봐요.","두 무리로 나눠요.","한 문장으로 써요."],"asset":{"type":"passage","lines":["㉠ 용암이 산과 마을로 흘러 산불이 났다.","㉡ 화산재가 쌓였던 땅에서 시간이 지나 농작물이 잘 자랐다.","㉢ 화산재가 하늘을 덮어 비행기가 뜨지 못했다.","㉣ 땅속에서 데워진 따뜻한 물로 온천을 만들었다.","㉤ 화산 가스 때문에 숨쉬기 어려웠다.","㉥ 땅속의 높은 열로 전기를 만들었다."],"title":"조사한 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#1','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C41',1,'mc','auto','땅이 흔들리는 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X51']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C41","difficulty":1,"kind":"mc","stem":"땅이 흔들리는 현상을 무엇이라고 하나요?","options":[{"t":"지진","correct":true},{"t":"화산 분출","mis":"SC4-1-u3-X51"},{"t":"태풍","mis":"SC4-1-u3-X51"},{"t":"산사태","mis":"SC4-1-u3-X51"}],"explanation":["땅이 흔들려요.","이름을 떠올려요.","지진이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#2','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C44',1,'mc','auto','교실에서 공부하다가 땅이 흔들리면 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-1-u3-X49']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C44","difficulty":1,"kind":"mc","stem":"교실에서 공부하다가 땅이 흔들리면 가장 먼저 할 일은 무엇인가요?","options":[{"t":"책상 아래로 들어가 머리와 몸을 보호한다","correct":true},{"t":"바로 밖으로 뛰어나간다","mis":"SC4-1-u3-X49"},{"t":"창문 옆에 서서 밖을 본다","mis":"SC4-1-u3-X49"},{"t":"친구에게 전화를 건다","mis":"SC4-1-u3-X49"}],"explanation":["물건이 떨어질 수 있어요.","머리를 지켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#3','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C45',1,'ox','auto','지진이 났을 때는 승강기 대신 계단을 이용해 대피해요.',ARRAY['SC4-1-u3-X50']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C45","difficulty":1,"kind":"ox","stem":"지진이 났을 때는 승강기 대신 계단을 이용해 대피해요.","answer":"O","reason_options":[{"t":"승강기는 전기가 끊기면 멈춰 안에 갇힐 수 있기 때문에","correct":true},{"t":"승강기가 계단보다 늘 빠르고 안전하기 때문에","mis":"SC4-1-u3-X50"}],"mis":"SC4-1-u3-X50","explanation":["승강기는 전기로 움직여요.","멈출 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#4','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C46',1,'sa','auto','지진에 대비해 비상식량·구급약품·물 등을 넣어 미리 준비해 두는 가방을 「○○ 가방」이라고 해요. ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C46","difficulty":1,"kind":"sa","stem":"지진에 대비해 비상식량·구급약품·물 등을 넣어 미리 준비해 두는 가방을 「○○ 가방」이라고 해요. ○○에 알맞은 말을 쓰세요.","answer":["생존"],"explanation":["살아남기 위한 가방이에요.","두 글자예요.","생존이에요."],"mis":"SC4-1-u3-X52"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#5','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C44',2,'match','auto','흔들릴 때 있는 곳과 알맞은 행동을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C44","difficulty":2,"kind":"match","stem":"흔들릴 때 있는 곳과 알맞은 행동을 이으세요.","pairs":[{"l":"교실","r":"책상 아래로 들어가 머리를 보호한다"},{"l":"승강기 안","r":"모든 층의 버튼을 눌러 먼저 열리는 층에서 내린다"},{"l":"운동장","r":"머리를 보호하고 건물이나 벽에서 먼 곳에 있는다"}],"mis":"SC4-1-u3-X53","explanation":["상황 1~3을 읽어요.","곳마다 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["상황 1 — 교실에서 공부하는데 땅이 흔들린다.","상황 2 — 승강기를 타고 가는데 땅이 흔들린다.","상황 3 — 운동장에서 놀다가 땅이 흔들린다.","상황 4 — 흔들림이 잠시 멈췄다."],"title":"지진 대처 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#6','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C42',2,'mc','auto','지진으로 생길 수 있는 피해로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X51']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C42","difficulty":2,"kind":"mc","stem":"지진으로 생길 수 있는 피해로 알맞은 것은 무엇인가요?","options":[{"t":"땅이 갈라지고 도로가 끊어진다","correct":true},{"t":"땅이 더 비옥해진다","mis":"SC4-1-u3-X51"},{"t":"하늘에 무지개가 뜬다","mis":"SC4-1-u3-X51"},{"t":"강물이 깨끗해진다","mis":"SC4-1-u3-X51"}],"explanation":["땅이 흔들려요.","갈라질 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#7','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C43',2,'ox','auto','지진이 나면 반드시 건물이 무너져요.',ARRAY['SC4-1-u3-X47']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C43","difficulty":2,"kind":"ox","stem":"지진이 나면 반드시 건물이 무너져요.","answer":"X","reason_options":[{"t":"약한 흔들림으로 그칠 때도 있기 때문에","correct":true},{"t":"지진은 언제나 건물을 무너뜨리기 때문에","mis":"SC4-1-u3-X47"}],"mis":"SC4-1-u3-X47","explanation":["「반드시」를 조심해요.","약한 지진도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#8','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C45',2,'mc','auto','흔들림이 잠시 멈췄을 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u3-X50','SC4-1-u3-X54']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C45","difficulty":2,"kind":"mc","stem":"흔들림이 잠시 멈췄을 때 알맞은 행동은 무엇인가요?","options":[{"t":"전기와 가스를 차단하고 문을 열어 둔 뒤 계단으로 대피한다","correct":true},{"t":"승강기를 타고 빨리 내려간다","mis":"SC4-1-u3-X50"},{"t":"가스 불을 그대로 켜 둔다","mis":"SC4-1-u3-X54"},{"t":"문을 꼭 닫고 방 안에 숨어 있는다","mis":"SC4-1-u3-X54"}],"explanation":["상황 4를 읽어요.","불이 나지 않게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#9','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C46',2,'mc','auto','지진이 일어나기 전 평소에 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X52','SC4-1-u3-X50']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C46","difficulty":2,"kind":"mc","stem":"지진이 일어나기 전 평소에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"가구나 가전제품이 넘어지지 않게 고정한다","correct":true},{"t":"지진은 미리 알 수 있으니 그때 준비한다","mis":"SC4-1-u3-X52"},{"t":"승강기로 대피하는 연습을 한다","mis":"SC4-1-u3-X50"},{"t":"대피장소는 지진이 난 뒤에 찾는다","mis":"SC4-1-u3-X52"}],"explanation":["넘어지면 다쳐요.","미리 고정해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_basic#10','sci',4,1,'u3','L07','g4_1_sci_u3_L07_basic','lesson_basic','SC4-1-u3-C43',3,'mc','auto','우리나라의 지진에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X48']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C43","difficulty":3,"kind":"mc","stem":"우리나라의 지진에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"우리나라에서도 지진으로 건물에 금이 가고 다친 사람이 생긴 적이 있다","correct":true},{"t":"우리나라에서는 지진 피해가 한 번도 없었다","mis":"SC4-1-u3-X48"},{"t":"우리나라는 지진이 날 수 없는 곳이다","mis":"SC4-1-u3-X48"},{"t":"지진은 다른 나라 이야기라 준비할 필요가 없다","mis":"SC4-1-u3-X48"}],"explanation":["우리나라도 흔들렸어요.","피해가 있었어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#1','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C44',2,'blank','auto','「건물 밖에 있을 때 땅이 흔들리면 건물이나 벽에서 (      ) 곳으로 대피해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X53']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C44","difficulty":2,"kind":"blank","stem":"「건물 밖에 있을 때 땅이 흔들리면 건물이나 벽에서 (      ) 곳으로 대피해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"먼","correct":true},{"t":"가까운","mis":"SC4-1-u3-X53"},{"t":"바로 옆","mis":"SC4-1-u3-X53"},{"t":"높은","mis":"SC4-1-u3-X53"}],"explanation":["무엇이 떨어질 수 있나요?","멀리 떨어져요.","「먼」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#2','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C41',2,'mc','auto','지진에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X52','SC4-1-u3-X51']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C41","difficulty":2,"kind":"mc","stem":"지진에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"언제 일어날지 정확히 알기 어렵다","correct":true},{"t":"언제 일어날지 정확히 알 수 있다","mis":"SC4-1-u3-X52"},{"t":"지진은 사람의 힘으로 멈출 수 있다","mis":"SC4-1-u3-X52"},{"t":"땅이 흔들리지 않는 현상이다","mis":"SC4-1-u3-X51"}],"explanation":["갑자기 일어나요.","미리 알기 어려워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#3','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C45',3,'error','auto','지진 대처 훈련 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X50','SC4-1-u3-X49','SC4-1-u3-X54']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C45","difficulty":3,"kind":"error","stem":"지진 대처 훈련 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「흔들림이 멈추면 승강기를 타고 빨리 내려가.」","correct":true,"mis_target":"SC4-1-u3-X50"},{"t":"친구 가 — 「흔들릴 때는 책상 아래에서 머리를 보호해.」","mis":"SC4-1-u3-X49"},{"t":"친구 다 — 「멈추면 전기와 가스를 끄고 계단으로 나가.」","mis":"SC4-1-u3-X54"}],"explanation":["승강기를 떠올려요.","계단이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#4','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C45',3,'mc','auto','지진이 났을 때 승강기를 이용하면 안 되는 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X50']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C45","difficulty":3,"kind":"mc","stem":"지진이 났을 때 승강기를 이용하면 안 되는 까닭은 무엇인가요?","options":[{"t":"전기가 끊기면 승강기가 멈춰 안에 갇힐 수 있어서","correct":true},{"t":"승강기가 너무 느려서","mis":"SC4-1-u3-X50"},{"t":"승강기는 요금을 내야 해서","mis":"SC4-1-u3-X50"},{"t":"승강기에는 사람이 많이 타서","mis":"SC4-1-u3-X50"}],"explanation":["승강기는 전기로 움직여요.","멈추면 갇혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#5','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C44',3,'mc','auto','「지진 대처 훈련」의 상황 2에서 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u3-X49','SC4-1-u3-X50']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C44","difficulty":3,"kind":"mc","stem":"「지진 대처 훈련」의 상황 2에서 알맞은 행동은 무엇인가요?","options":[{"t":"모든 층의 버튼을 눌러 가장 먼저 열리는 층에서 내린다","correct":true},{"t":"승강기 안에서 뛰어 문을 연다","mis":"SC4-1-u3-X49"},{"t":"맨 위층 버튼만 눌러 끝까지 타고 간다","mis":"SC4-1-u3-X50"},{"t":"문이 열려도 흔들림이 끝날 때까지 승강기에 남는다","mis":"SC4-1-u3-X50"}],"explanation":["상황 2를 읽어요.","빨리 내려야 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["상황 1 — 교실에서 공부하는데 땅이 흔들린다.","상황 2 — 승강기를 타고 가는데 땅이 흔들린다.","상황 3 — 운동장에서 놀다가 땅이 흔들린다.","상황 4 — 흔들림이 잠시 멈췄다."],"title":"지진 대처 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#6','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C42',3,'ox','auto','지진이 나면 화재나 산사태가 일어날 수도 있어요.',ARRAY['SC4-1-u3-X51']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C42","difficulty":3,"kind":"ox","stem":"지진이 나면 화재나 산사태가 일어날 수도 있어요.","answer":"O","reason_options":[{"t":"땅이 흔들려 가스관이 부서지거나 비탈이 무너질 수 있기 때문에","correct":true},{"t":"지진은 땅만 흔들 뿐 다른 피해는 주지 않기 때문에","mis":"SC4-1-u3-X51"}],"mis":"SC4-1-u3-X51","explanation":["흔들리면 부서져요.","불과 무너짐이요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#7','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C46',3,'mc','auto','가족과 함께 세울 지진 대비 계획으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X52','SC4-1-u3-X50']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C46","difficulty":3,"kind":"mc","stem":"가족과 함께 세울 지진 대비 계획으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 동네 대피장소를 함께 알아 두고, 흩어졌을 때 만날 곳을 정한다","correct":true},{"t":"지진이 나면 각자 알아서 하기로 한다","mis":"SC4-1-u3-X52"},{"t":"대피장소는 지진이 난 뒤에 찾기로 한다","mis":"SC4-1-u3-X52"},{"t":"흔들리면 모두 승강기 앞에 모이기로 한다","mis":"SC4-1-u3-X50"}],"explanation":["미리 정해요.","함께 알아 둬요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#8','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C43',4,'mc','auto','친구가 「아주 약하게 흔들렸으니 지진이 아니야. 지진이면 건물이 꼭 무너져.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X47','SC4-1-u3-X52','SC4-1-u3-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C43","difficulty":4,"kind":"mc","stem":"친구가 「아주 약하게 흔들렸으니 지진이 아니야. 지진이면 건물이 꼭 무너져.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「땅이 흔들렸으면 지진이야. 지진은 약한 흔들림으로 그칠 때도 있어.」","correct":true},{"t":"「맞아, 지진은 늘 건물을 무너뜨려.」","mis":"SC4-1-u3-X47"},{"t":"「약한 흔들림이면 대비할 필요가 없어.」","mis":"SC4-1-u3-X52"},{"t":"「우리나라에는 지진이 없어.」","mis":"SC4-1-u3-X48"}],"explanation":["지진의 뜻을 떠올려요.","약한 지진도 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#9','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C44',4,'mc','auto','친구가 「땅이 흔들리면 운동장 쪽 건물 벽에 붙어 서 있는 게 안전해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X53','SC4-1-u3-X50','SC4-1-u3-X49']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C44","difficulty":4,"kind":"mc","stem":"친구가 「땅이 흔들리면 운동장 쪽 건물 벽에 붙어 서 있는 게 안전해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물건이 떨어질 수 있으니 머리를 보호하고 건물이나 벽에서 먼 곳으로 가야 해.」","correct":true},{"t":"「맞아, 벽에 붙어 있으면 안전해.」","mis":"SC4-1-u3-X53"},{"t":"「바로 승강기를 타고 내려가.」","mis":"SC4-1-u3-X50"},{"t":"「창문 옆에서 밖을 살펴봐.」","mis":"SC4-1-u3-X49"}],"explanation":["상황 3을 떠올려요.","떨어지는 물건을 피해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L07_challenge#10','sci',4,1,'u3','L07','g4_1_sci_u3_L07_challenge','lesson_challenge','SC4-1-u3-C44',4,'essay','teacher','「지진 대처 훈련」의 상황 1~4에서 어떻게 행동해야 하는지 각각 쓰고, 지진이 났을 때 가장 중요한 마음가짐을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C44","difficulty":4,"kind":"essay","stem":"「지진 대처 훈련」의 상황 1~4에서 어떻게 행동해야 하는지 각각 쓰고, 지진이 났을 때 가장 중요한 마음가짐을 쓰세요.","answer_guide":{"answer":"예: 상황 1에서는 책상 아래로 들어가 머리와 몸을 보호한다. 상황 2에서는 모든 층의 버튼을 눌러 먼저 열리는 층에서 내린다. 상황 3에서는 머리를 보호하고 건물이나 벽에서 먼 곳으로 간다. 상황 4에서는 전기와 가스를 차단하고 문을 연 뒤 계단으로 대피한다. 당황하지 않고 침착하게 행동하는 것이 가장 중요하다.","scoring_points":["상황 1~3의 행동을 바르게 썼는가","상황 4에서 계단으로 대피한다고 썼는가","침착한 마음가짐을 썼는가"]},"explanation":["상황을 하나씩 읽어요.","곳마다 달라요.","마음가짐도 써요."],"asset":{"type":"passage","lines":["상황 1 — 교실에서 공부하는데 땅이 흔들린다.","상황 2 — 승강기를 타고 가는데 땅이 흔들린다.","상황 3 — 운동장에서 놀다가 땅이 흔들린다.","상황 4 — 흔들림이 잠시 멈췄다."],"title":"지진 대처 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#1','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C47',1,'mc','auto','화산 활동이나 지진처럼 우리에게 큰 피해를 주는 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X61']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C47","difficulty":1,"kind":"mc","stem":"화산 활동이나 지진처럼 우리에게 큰 피해를 주는 현상을 무엇이라고 하나요?","options":[{"t":"재난","correct":true},{"t":"축제","mis":"SC4-1-u3-X61"},{"t":"공연","mis":"SC4-1-u3-X61"},{"t":"여행","mis":"SC4-1-u3-X61"}],"explanation":["큰 피해를 줘요.","이름을 떠올려요.","재난이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#2','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C48',1,'mc','auto','재난 대비 안내 자료에 꼭 담아야 할 내용은 무엇인가요?',ARRAY['SC4-1-u3-X55','SC4-1-u3-X56']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C48","difficulty":1,"kind":"mc","stem":"재난 대비 안내 자료에 꼭 담아야 할 내용은 무엇인가요?","options":[{"t":"대처 방법","correct":true},{"t":"무서운 장면만 잔뜩","mis":"SC4-1-u3-X55"},{"t":"확인하지 않은 소문","mis":"SC4-1-u3-X55"},{"t":"화려한 꾸밈 글씨","mis":"SC4-1-u3-X56"}],"explanation":["사람들이 할 일을 알려 줘요.","실천할 수 있어요.","대처 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#3','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C52',1,'ox','auto','제주도의 용암 동굴은 사람들이 땅을 파서 만들었어요.',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C52","difficulty":1,"kind":"ox","stem":"제주도의 용암 동굴은 사람들이 땅을 파서 만들었어요.","answer":"X","reason_options":[{"t":"용암이 지하를 뚫고 지나가면서 만들어졌기 때문에","correct":true},{"t":"동굴은 모두 사람이 만든 것이기 때문에","mis":"SC4-1-u3-X60"}],"mis":"SC4-1-u3-X60","explanation":["셋째 줄을 읽어요.","용암이 만들었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["한라산 — 제주도 한가운데 솟은 산, 꼭대기에 백록담이 있다.","오름 — 제주도 곳곳에 있는 작은 화산이다.","용암 동굴 — 용암이 지하를 뚫고 지나가며 만들어진 동굴이다.","성산일출봉 — 바다에서 마그마가 분출하여 만들어진 화산이다."],"title":"화산이 만든 섬, 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#4','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C49',1,'sa','auto','재난방송에서 스마트 기기로 방송 영상을 찍는 역할을 「○○ 감독」이라고 해요. ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u3-C49","difficulty":1,"kind":"sa","stem":"재난방송에서 스마트 기기로 방송 영상을 찍는 역할을 「○○ 감독」이라고 해요. ○○에 알맞은 말을 쓰세요.","answer":["촬영"],"explanation":["영상을 찍어요.","두 글자예요.","촬영이에요."],"mis":"SC4-1-u3-X58"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#5','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C49',2,'match','auto','역할과 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u3-C49","difficulty":2,"kind":"match","stem":"역할과 할 일을 알맞게 이으세요.","pairs":[{"l":"기자","r":"피해 사례를 취재해 알린다"},{"l":"재난 전문가","r":"재난에 대처하는 방법을 안내한다"},{"l":"촬영 감독","r":"방송 영상을 촬영한다"}],"mis":"SC4-1-u3-X58","explanation":["계획을 읽어요.","역할마다 할 일이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["담을 내용 — 발생 일시, 발생 장소, 피해 내용, 대처 방법","촬영 감독 — 스마트 기기로 방송 영상을 촬영한다.","기자 — 피해 사례를 취재해 알린다.","진행자 — 방송을 이끌며 순서를 안내한다.","재난 전문가 — 재난에 대처하는 방법을 안내한다."],"title":"우리 모둠 재난방송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#6','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C47',2,'mc','auto','재난방송이 필요한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X61']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C47","difficulty":2,"kind":"mc","stem":"재난방송이 필요한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"재난 상황을 전달하고 대처 방법을 안내해 주기 때문에","correct":true},{"t":"재미있는 놀이를 알려 주기 때문에","mis":"SC4-1-u3-X61"},{"t":"신나는 음악을 들려주기 때문에","mis":"SC4-1-u3-X61"},{"t":"맛있는 음식을 소개해 주기 때문에","mis":"SC4-1-u3-X61"}],"explanation":["재난 때 무엇이 필요할까요?","소식과 할 일이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#7','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C51',2,'mc','auto','재난 대비 가방에 넣을 물품으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X59']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C51","difficulty":2,"kind":"mc","stem":"재난 대비 가방에 넣을 물품으로 알맞은 것은 무엇인가요?","options":[{"t":"물, 비상식량, 손전등, 구급약품","correct":true},{"t":"무거운 장난감 상자","mis":"SC4-1-u3-X59"},{"t":"깨지기 쉬운 유리 장식품","mis":"SC4-1-u3-X59"},{"t":"게임기와 만화책만","mis":"SC4-1-u3-X59"}],"explanation":["살아가는 데 필요한 것이에요.","가볍고 쓸모 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#8','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C50',2,'ox','auto','안내 자료는 소품을 화려하게 꾸미는 것이 내용보다 중요해요.',ARRAY['SC4-1-u3-X56']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C50","difficulty":2,"kind":"ox","stem":"안내 자료는 소품을 화려하게 꾸미는 것이 내용보다 중요해요.","answer":"X","reason_options":[{"t":"실천할 수 있는 대처 방법 같은 내용을 정확하게 담는 것이 더 중요하기 때문에","correct":true},{"t":"꾸밈이 화려해야 정보가 맞기 때문에","mis":"SC4-1-u3-X56"}],"mis":"SC4-1-u3-X56","explanation":["무엇을 알려야 하나요?","내용이 먼저예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#9','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C52',2,'mc','auto','제주도가 세계자연유산이 된 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C52","difficulty":2,"kind":"mc","stem":"제주도가 세계자연유산이 된 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"화산 활동이 만든 독특한 지형의 가치를 인정받았기 때문에","correct":true},{"t":"사람이 만든 큰 건물이 많기 때문에","mis":"SC4-1-u3-X60"},{"t":"화산 활동이 한 번도 없었던 섬이기 때문에","mis":"SC4-1-u3-X60"},{"t":"화산 지형은 쓸모가 없어 아무렇게나 둬도 되기 때문에","mis":"SC4-1-u3-X60"}],"explanation":["제주도를 떠올려요.","화산이 만들었어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_basic#10','sci',4,1,'u3','L08','g4_1_sci_u3_L08_basic','lesson_basic','SC4-1-u3-C50',3,'mc','auto','친구 모둠의 발표를 들을 때 알맞은 태도는 무엇인가요?',ARRAY['SC4-1-u3-X57']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C50","difficulty":3,"kind":"mc","stem":"친구 모둠의 발표를 들을 때 알맞은 태도는 무엇인가요?","options":[{"t":"귀 기울여 듣고 칭찬할 점을 찾아 이야기한다","correct":true},{"t":"아쉬운 점만 골라 큰 소리로 비난한다","mis":"SC4-1-u3-X57"},{"t":"우리 모둠 발표 준비만 한다","mis":"SC4-1-u3-X57"},{"t":"발표가 끝나기 전에 끼어든다","mis":"SC4-1-u3-X57"}],"explanation":["서로 배워요.","잘한 점도 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#1','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C47',2,'blank','auto','「재난 상황을 전달하고 대처 방법을 안내하는 방송을 (      )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X61']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C47","difficulty":2,"kind":"blank","stem":"「재난 상황을 전달하고 대처 방법을 안내하는 방송을 (      )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"재난방송","correct":true},{"t":"광고 방송","mis":"SC4-1-u3-X61"},{"t":"음악 방송","mis":"SC4-1-u3-X61"},{"t":"놀이 방송","mis":"SC4-1-u3-X61"}],"explanation":["재난 때 나와요.","대처 방법을 알려요.","재난방송이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#2','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C52',2,'mc','auto','「화산이 만든 섬, 제주도」에서 바다에서 마그마가 분출하여 만들어진 화산은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C52","difficulty":2,"kind":"mc","stem":"「화산이 만든 섬, 제주도」에서 바다에서 마그마가 분출하여 만들어진 화산은 무엇인가요?","options":[{"t":"성산일출봉","correct":true},{"t":"용암 동굴","mis":"SC4-1-u3-X60"},{"t":"백록담","mis":"SC4-1-u3-X60"},{"t":"제주도에는 화산이 없다","mis":"SC4-1-u3-X60"}],"explanation":["넷째 줄을 읽어요.","바다에서 생겼어요.","성산일출봉이에요."],"asset":{"type":"passage","lines":["한라산 — 제주도 한가운데 솟은 산, 꼭대기에 백록담이 있다.","오름 — 제주도 곳곳에 있는 작은 화산이다.","용암 동굴 — 용암이 지하를 뚫고 지나가며 만들어진 동굴이다.","성산일출봉 — 바다에서 마그마가 분출하여 만들어진 화산이다."],"title":"화산이 만든 섬, 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#3','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C48',3,'error','auto','재난방송 계획을 세우며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u3-X55','SC4-1-u3-X56']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C48","difficulty":3,"kind":"error","stem":"재난방송 계획을 세우며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「사람들이 놀라게 무서운 장면만 잔뜩 넣자.」","correct":true,"mis_target":"SC4-1-u3-X55"},{"t":"친구 가 — 「지진이 난 일시와 장소를 넣자.」","mis":"SC4-1-u3-X55"},{"t":"친구 다 — 「실천할 수 있는 대처 방법을 꼭 넣자.」","mis":"SC4-1-u3-X56"}],"explanation":["담을 내용을 떠올려요.","겁주는 게 목적이 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#4','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C50',3,'mc','auto','안내 자료를 만들 때 조사한 정보를 다루는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X55','SC4-1-u3-X56']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C50","difficulty":3,"kind":"mc","stem":"안내 자료를 만들 때 조사한 정보를 다루는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"출처를 확인하고 옳은 정보와 거짓 정보를 구분한다","correct":true},{"t":"누가 말했는지 몰라도 재미있는 소문을 넣는다","mis":"SC4-1-u3-X55"},{"t":"확인하지 않은 피해 이야기를 크게 부풀린다","mis":"SC4-1-u3-X55"},{"t":"출처는 상관없이 많이 모으기만 한다","mis":"SC4-1-u3-X56"}],"explanation":["믿을 수 있나요?","출처를 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#5','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C49',3,'mc','auto','「우리 모둠 재난방송 계획」에서 피해 사례를 취재해 알리는 역할은 누구인가요?',ARRAY['SC4-1-u3-X58']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C49","difficulty":3,"kind":"mc","stem":"「우리 모둠 재난방송 계획」에서 피해 사례를 취재해 알리는 역할은 누구인가요?","options":[{"t":"기자","correct":true},{"t":"촬영 감독","mis":"SC4-1-u3-X58"},{"t":"진행자","mis":"SC4-1-u3-X58"},{"t":"재난 전문가","mis":"SC4-1-u3-X58"}],"explanation":["셋째 줄을 읽어요.","취재해요.","기자예요."],"asset":{"type":"passage","lines":["담을 내용 — 발생 일시, 발생 장소, 피해 내용, 대처 방법","촬영 감독 — 스마트 기기로 방송 영상을 촬영한다.","기자 — 피해 사례를 취재해 알린다.","진행자 — 방송을 이끌며 순서를 안내한다.","재난 전문가 — 재난에 대처하는 방법을 안내한다."],"title":"우리 모둠 재난방송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#6','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C51',3,'ox','auto','재난 대비 가방에는 오래 두어도 먹을 수 있는 비상식량과 물을 넣어요.',ARRAY['SC4-1-u3-X59']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C51","difficulty":3,"kind":"ox","stem":"재난 대비 가방에는 오래 두어도 먹을 수 있는 비상식량과 물을 넣어요.","answer":"O","reason_options":[{"t":"재난이 나면 먹을 것과 물을 구하기 어려울 수 있기 때문에","correct":true},{"t":"재난이 나도 가게에서 무엇이든 바로 살 수 있기 때문에","mis":"SC4-1-u3-X59"}],"mis":"SC4-1-u3-X59","explanation":["재난 때를 떠올려요.","구하기 어려워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#7','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C52',3,'mc','auto','제주도의 화산 지형을 대하는 태도로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C52","difficulty":3,"kind":"mc","stem":"제주도의 화산 지형을 대하는 태도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"가치를 알고 소중히 보존한다","correct":true},{"t":"화산이 만든 곳이니 무섭게만 여긴다","mis":"SC4-1-u3-X60"},{"t":"기념으로 돌을 마음대로 가져간다","mis":"SC4-1-u3-X60"},{"t":"쓸모없으니 아무렇게나 둔다","mis":"SC4-1-u3-X60"}],"explanation":["세계자연유산이에요.","지켜야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#8','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C50',4,'mc','auto','친구가 「우리 모둠은 화려한 소품을 많이 만들었으니 대처 방법은 빼도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X56','SC4-1-u3-X55','SC4-1-u3-X57']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C50","difficulty":4,"kind":"mc","stem":"친구가 「우리 모둠은 화려한 소품을 많이 만들었으니 대처 방법은 빼도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「소품보다 내용이 중요해. 사람들이 실천할 수 있는 대처 방법을 꼭 담아야 해.」","correct":true},{"t":"「맞아, 꾸미기가 제일 중요해.」","mis":"SC4-1-u3-X56"},{"t":"「무서운 장면을 더 넣으면 돼.」","mis":"SC4-1-u3-X55"},{"t":"「다른 모둠 것을 비난하면 돼.」","mis":"SC4-1-u3-X57"}],"explanation":["무엇을 알려야 하나요?","대처 방법이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#9','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C52',4,'mc','auto','친구가 「화산은 해롭기만 하니까 화산이 만든 지형도 쓸모없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C52","difficulty":4,"kind":"mc","stem":"친구가 「화산은 해롭기만 하니까 화산이 만든 지형도 쓸모없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「제주도의 한라산과 오름, 용암 동굴은 화산 활동이 만든 아름다운 지형이라 세계자연유산이 되었어.」","correct":true},{"t":"「맞아, 화산 지형은 아무 가치가 없어.」","mis":"SC4-1-u3-X60"},{"t":"「용암 동굴은 사람이 판 거라 화산과 상관없어.」","mis":"SC4-1-u3-X60"},{"t":"「제주도는 화산과 관계없는 섬이야.」","mis":"SC4-1-u3-X60"}],"explanation":["제주도를 떠올려요.","화산이 만든 아름다움이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_L08_challenge#10','sci',4,1,'u3','L08','g4_1_sci_u3_L08_challenge','lesson_challenge','SC4-1-u3-C48',4,'essay','teacher','「우리 모둠 재난방송 계획」을 보고 재난방송에 담을 내용 네 가지를 쓰고, 넣지 말아야 할 내용을 한 가지 골라 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u3-C48","difficulty":4,"kind":"essay","stem":"「우리 모둠 재난방송 계획」을 보고 재난방송에 담을 내용 네 가지를 쓰고, 넣지 말아야 할 내용을 한 가지 골라 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 발생 일시, 발생 장소, 피해 내용, 대처 방법을 담는다. 확인하지 않은 소문은 넣지 않는다. 거짓 정보가 사람들을 혼란스럽게 하고 잘못 행동하게 할 수 있기 때문이다.","scoring_points":["담을 내용 네 가지를 썼는가","넣지 말아야 할 내용을 바르게 골랐는가","그 까닭을 썼는가"]},"explanation":["첫 줄을 읽어요.","네 가지예요.","뺄 것과 까닭을 써요."],"asset":{"type":"passage","lines":["담을 내용 — 발생 일시, 발생 장소, 피해 내용, 대처 방법","촬영 감독 — 스마트 기기로 방송 영상을 촬영한다.","기자 — 피해 사례를 취재해 알린다.","진행자 — 방송을 이끌며 순서를 안내한다.","재난 전문가 — 재난에 대처하는 방법을 안내한다."],"title":"우리 모둠 재난방송 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#1','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C2',1,'mc','auto','노을반 일지 ①에서 물을 뿌린 곳의 흙은 어떻게 되었나요?',ARRAY['SC4-1-u3-X01','SC4-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C2","difficulty":1,"kind":"mc","stem":"노을반 일지 ①에서 물을 뿌린 곳의 흙은 어떻게 되었나요?","options":[{"t":"깎였다","correct":true},{"t":"더 단단해졌다","mis":"SC4-1-u3-X01"},{"t":"위로 올라갔다","mis":"SC4-1-u3-X02"},{"t":"그대로였다","mis":"SC4-1-u3-X01"}],"explanation":["둘째 줄을 읽어요.","물이 닿았어요.","깎였어요."],"asset":{"type":"passage","lines":["운동장 흙으로 성을 쌓고 깃발을 꽂았다.","스포이트로 물을 뿌리자 흙이 깎였다.","흙탕물이 흐르고 성 아래에 흙이 쌓였다.","친구 가 — 「진짜 땅은 흙 성과 달라서 절대 변하지 않아.」"],"title":"노을반 일지 ① 흙 성 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#2','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C10',1,'mc','auto','노을반 일지 ②에서 아래쪽에 흙과 색 모래가 쌓인 것은 어떤 작용인가요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X13']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C10","difficulty":1,"kind":"mc","stem":"노을반 일지 ②에서 아래쪽에 흙과 색 모래가 쌓인 것은 어떤 작용인가요?","options":[{"t":"퇴적 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X07"},{"t":"운반 작용","mis":"SC4-1-u3-X07"},{"t":"아무 작용도 아니다","mis":"SC4-1-u3-X13"}],"explanation":["셋째 줄을 읽어요.","쌓였어요.","퇴적 작용이에요."],"asset":{"type":"passage","lines":["흙 언덕 꼭대기에 물을 흘려 보냈다.","위쪽은 움푹 파이고 흙탕물이 아래로 흘렀다.","아래쪽에 흙과 색 모래가 쌓였다.","친구 나 — 「위쪽은 깎이기만, 아래쪽은 쌓이기만 해.」"],"title":"노을반 일지 ② 흙 언덕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#3','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C14',1,'mc','auto','노을반 일지 ③의 ㉮는 강의 어느 곳인가요?',ARRAY['SC4-1-u3-X14','SC4-1-u3-X21']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C14","difficulty":1,"kind":"mc","stem":"노을반 일지 ③의 ㉮는 강의 어느 곳인가요?","options":[{"t":"강 상류","correct":true},{"t":"강 하류","mis":"SC4-1-u3-X14"},{"t":"바다","mis":"SC4-1-u3-X14"},{"t":"알 수 없다","mis":"SC4-1-u3-X21"}],"explanation":["첫 줄을 읽어요.","좁고 바위가 많아요.","강 상류예요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 큰 바위와 모난 돌이 많았다.","㉯ 강폭이 넓고 고운 모래가 많았다.","굽은 곳 바깥쪽은 물이 빠르고, 안쪽은 느렸다.","친구 다 — 「강의 한 곳에서는 물이 늘 똑같이 흘러.」"],"title":"노을반 일지 ③ 강 탐험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#4','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C22',1,'mc','auto','노을반 일지 ④에서 화산 꼭대기의 움푹 파인 곳을 무엇이라고 하나요?',ARRAY['SC4-1-u3-X27','SC4-1-u3-X22']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C22","difficulty":1,"kind":"mc","stem":"노을반 일지 ④에서 화산 꼭대기의 움푹 파인 곳을 무엇이라고 하나요?","options":[{"t":"분화구","correct":true},{"t":"용암","mis":"SC4-1-u3-X27"},{"t":"마그마","mis":"SC4-1-u3-X22"},{"t":"화산재","mis":"SC4-1-u3-X27"}],"explanation":["첫 줄을 읽어요.","움푹 파였어요.","분화구예요."],"asset":{"type":"passage","lines":["화산 사진 속 꼭대기에 움푹 파인 곳이 있었다.","모형실험에서 연기가 나고 마시멜로가 흘렀다.","흘러내린 마시멜로는 식어서 굳었다.","친구 가 — 「용암이 안 보이면 화산이 아니야.」"],"title":"노을반 일지 ④ 화산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#5','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C32',1,'mc','auto','노을반 일지 ⑤의 표본 ㉠은 어떤 암석인가요?',ARRAY['SC4-1-u3-X33','SC4-1-u3-X37']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C32","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑤의 표본 ㉠은 어떤 암석인가요?","options":[{"t":"화강암","correct":true},{"t":"현무암","mis":"SC4-1-u3-X33"},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"용암","mis":"SC4-1-u3-X37"}],"explanation":["밝고 알갱이가 커요.","화강암의 특징이에요.","화강암이에요."],"asset":{"type":"passage","lines":["표본 ㉠ — 색이 밝고 알갱이가 크다.","표본 ㉡ — 색이 어둡고 알갱이가 작으며 구멍이 많다.","표본 ㉢ — 색이 어둡고 알갱이가 작으며 구멍이 없다.","친구 나 — 「구멍이 없으니 ㉢은 현무암이 아니야.」"],"title":"노을반 일지 ⑤ 암석 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#6','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C37',1,'mc','auto','노을반 일지 ⑥에서 비행기가 뜨지 못하게 한 것은 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X42']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C37","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑥에서 비행기가 뜨지 못하게 한 것은 무엇인가요?","options":[{"t":"화산재","correct":true},{"t":"온천","mis":"SC4-1-u3-X41"},{"t":"용암","mis":"SC4-1-u3-X42"},{"t":"농작물","mis":"SC4-1-u3-X41"}],"explanation":["첫 줄을 읽어요.","하늘을 덮었어요.","화산재예요."],"asset":{"type":"passage","lines":["화산재가 하늘을 덮어 비행기가 뜨지 못했다.","화산재가 쌓였던 땅에서 몇 해 뒤 농작물이 잘 자랐다.","화산 근처 온천에 관광객이 많이 왔다.","친구 다 — 「화산은 해롭기만 하니 좋은 점은 없어.」"],"title":"노을반 일지 ⑥ 화산과 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#7','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C44',1,'mc','auto','노을반 일지 ⑦에서 교실에서 흔들릴 때 한 행동은 무엇인가요?',ARRAY['SC4-1-u3-X49','SC4-1-u3-X50']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C44","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑦에서 교실에서 흔들릴 때 한 행동은 무엇인가요?","options":[{"t":"책상 아래로 들어가 머리를 보호했다","correct":true},{"t":"바로 운동장으로 뛰어나갔다","mis":"SC4-1-u3-X49"},{"t":"창문 옆에 서 있었다","mis":"SC4-1-u3-X49"},{"t":"승강기를 탔다","mis":"SC4-1-u3-X50"}],"explanation":["둘째 줄을 읽어요.","머리를 지켰어요.","첫 번째예요."],"asset":{"type":"passage","lines":["지진 대피 훈련 방송이 나왔다.","교실에서 책상 아래로 들어가 머리를 보호했다.","흔들림이 멈추자 계단으로 운동장에 나갔다.","친구 가 — 「다음엔 승강기를 타고 빨리 내려가자.」"],"title":"노을반 일지 ⑦ 지진 대피 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#8','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C48',1,'mc','auto','노을반 일지 ⑧의 재난방송에 담은 내용 가운데 사람들이 실천할 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u3-X55','SC4-1-u3-X56']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C48","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑧의 재난방송에 담은 내용 가운데 사람들이 실천할 수 있는 것은 무엇인가요?","options":[{"t":"대처 방법","correct":true},{"t":"무서운 장면","mis":"SC4-1-u3-X55"},{"t":"확인 안 된 소문","mis":"SC4-1-u3-X55"},{"t":"화려한 꾸밈","mis":"SC4-1-u3-X56"}],"explanation":["둘째 줄을 읽어요.","할 일을 알려 줘요.","대처 방법이에요."],"asset":{"type":"passage","lines":["모둠별로 지진 대비 재난방송을 만들었다.","발생 일시·장소·피해 내용·대처 방법을 담았다.","제주도의 오름과 용암 동굴 자료도 찾아보았다.","친구 나 — 「다른 모둠 발표는 아쉬운 점만 말해 주자.」"],"title":"노을반 일지 ⑧ 재난방송과 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#9','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C1',2,'mc','auto','흙으로 성을 만들 때 흙에 넣는 물의 양으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C1","difficulty":2,"kind":"mc","stem":"흙으로 성을 만들 때 흙에 넣는 물의 양으로 알맞은 것은 무엇인가요?","options":[{"t":"흙이 잘 뭉쳐질 만큼 알맞게 넣는다","correct":true},{"t":"물을 많이 넣을수록 좋다","mis":"SC4-1-u3-X06"},{"t":"물은 넣지 않는다","mis":"SC4-1-u3-X06"},{"t":"흙보다 물을 더 많이 넣는다","mis":"SC4-1-u3-X06"}],"explanation":["너무 적으면 안 뭉쳐요.","너무 많으면 무너져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#10','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C7',2,'mc','auto','흙 언덕 실험에서 흙이 가장 많이 깎인 곳과 가장 많이 쌓인 곳을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X09']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C7","difficulty":2,"kind":"mc","stem":"흙 언덕 실험에서 흙이 가장 많이 깎인 곳과 가장 많이 쌓인 곳을 바르게 말한 것은 무엇인가요?","options":[{"t":"가장 많이 깎인 곳은 위쪽, 가장 많이 쌓인 곳은 아래쪽","correct":true},{"t":"가장 많이 깎인 곳은 아래쪽, 가장 많이 쌓인 곳은 위쪽","mis":"SC4-1-u3-X09"},{"t":"둘 다 위쪽","mis":"SC4-1-u3-X09"},{"t":"둘 다 아래쪽","mis":"SC4-1-u3-X09"}],"explanation":["물은 위에서 출발해요.","아래로 모여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#11','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C17',2,'mc','auto','강 하류에 쌓인 고운 모래는 어디에서 왔을까요?',ARRAY['SC4-1-u3-X17']::text[],false,'{"seq":11,"concept":"SC4-1-u3-C17","difficulty":2,"kind":"mc","stem":"강 하류에 쌓인 고운 모래는 어디에서 왔을까요?","options":[{"t":"상류 쪽 바위가 깎이고 운반되며 작아진 것","correct":true},{"t":"하늘에서 비와 함께 내린 것","mis":"SC4-1-u3-X17"},{"t":"사람이 강가에 부어 놓은 것","mis":"SC4-1-u3-X17"},{"t":"하류의 물이 스스로 만든 것","mis":"SC4-1-u3-X17"}],"explanation":["물은 위에서 와요.","깎이고 옮겨져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#12','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C25',2,'mc','auto','고체 상태의 화산 분출물을 모두 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X26']::text[],false,'{"seq":12,"concept":"SC4-1-u3-C25","difficulty":2,"kind":"mc","stem":"고체 상태의 화산 분출물을 모두 고른 것은 무엇인가요?","options":[{"t":"화산재, 화산 암석 조각","correct":true},{"t":"화산 가스, 용암","mis":"SC4-1-u3-X26"},{"t":"용암, 화산재","mis":"SC4-1-u3-X26"},{"t":"화산 가스만","mis":"SC4-1-u3-X26"}],"explanation":["단단한 것을 찾아요.","두 가지예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#13','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C32',2,'mc','auto','화강암에 섞여 있는 알갱이의 색으로 볼 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u3-X35','SC4-1-u3-X33']::text[],false,'{"seq":13,"concept":"SC4-1-u3-C32","difficulty":2,"kind":"mc","stem":"화강암에 섞여 있는 알갱이의 색으로 볼 수 있는 것은 무엇인가요?","options":[{"t":"검은색, 흰색, 분홍색, 반짝이는 알갱이","correct":true},{"t":"흰색과 검은색뿐","mis":"SC4-1-u3-X35"},{"t":"검은색 한 가지","mis":"SC4-1-u3-X33"},{"t":"알갱이가 보이지 않는다","mis":"SC4-1-u3-X33"}],"explanation":["여러 색이 섞여요.","분홍색도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#14','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C40',2,'mc','auto','화산이 분출했을 때 건물 안에 있다면 어떻게 하는 것이 알맞은가요?',ARRAY['SC4-1-u3-X44']::text[],false,'{"seq":14,"concept":"SC4-1-u3-C40","difficulty":2,"kind":"mc","stem":"화산이 분출했을 때 건물 안에 있다면 어떻게 하는 것이 알맞은가요?","options":[{"t":"창문을 닫고 실내에 머물며 안내 방송을 듣는다","correct":true},{"t":"밖으로 나가 화산재를 구경한다","mis":"SC4-1-u3-X44"},{"t":"안내 방송을 끄고 잠을 잔다","mis":"SC4-1-u3-X44"},{"t":"창문을 활짝 연다","mis":"SC4-1-u3-X44"}],"explanation":["화산재를 막아요.","방송을 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#15','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C42',2,'mc','auto','지진으로 생길 수 있는 피해를 모두 고른 것은 무엇인가요? ㉠ 건물이 무너짐 ㉡ 산사태 ㉢ 땅이 비옥해짐 ㉣ 화재',ARRAY['SC4-1-u3-X51']::text[],false,'{"seq":15,"concept":"SC4-1-u3-C42","difficulty":2,"kind":"mc","stem":"지진으로 생길 수 있는 피해를 모두 고른 것은 무엇인가요? ㉠ 건물이 무너짐 ㉡ 산사태 ㉢ 땅이 비옥해짐 ㉣ 화재","options":[{"t":"㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢","mis":"SC4-1-u3-X51"},{"t":"㉡, ㉢, ㉣","mis":"SC4-1-u3-X51"},{"t":"㉢만","mis":"SC4-1-u3-X51"}],"explanation":["피해를 찾아요.","㉢은 화산 이야기예요.","㉠, ㉡, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#16','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C49',2,'mc','auto','재난방송에서 재난에 대처하는 방법을 안내하는 역할은 누구인가요?',ARRAY['SC4-1-u3-X58']::text[],false,'{"seq":16,"concept":"SC4-1-u3-C49","difficulty":2,"kind":"mc","stem":"재난방송에서 재난에 대처하는 방법을 안내하는 역할은 누구인가요?","options":[{"t":"재난 전문가","correct":true},{"t":"촬영 감독","mis":"SC4-1-u3-X58"},{"t":"기자","mis":"SC4-1-u3-X58"},{"t":"진행자","mis":"SC4-1-u3-X58"}],"explanation":["대처 방법을 잘 알아요.","전문가예요.","재난 전문가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#17','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C11',3,'mc','auto','흙 언덕 아래쪽에서 일어나는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X08','SC4-1-u3-X09']::text[],false,'{"seq":17,"concept":"SC4-1-u3-C11","difficulty":3,"kind":"mc","stem":"흙 언덕 아래쪽에서 일어나는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"퇴적 작용이 더 활발하지만 침식·운반 작용도 함께 일어난다","correct":true},{"t":"퇴적 작용 하나만 일어난다","mis":"SC4-1-u3-X08"},{"t":"침식 작용이 가장 활발하다","mis":"SC4-1-u3-X09"},{"t":"아무 작용도 일어나지 않는다","mis":"SC4-1-u3-X08"}],"explanation":["아래쪽은 쌓여요.","다른 일도 함께요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#18','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C16',3,'mc','auto','강 상류와 하류의 모습이 다른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X17','SC4-1-u3-X15']::text[],false,'{"seq":18,"concept":"SC4-1-u3-C16","difficulty":3,"kind":"mc","stem":"강 상류와 하류의 모습이 다른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"위치마다 더 활발하게 일어나는 물의 작용이 다르기 때문에","correct":true},{"t":"상류와 하류에 사는 사람 수가 다르기 때문에","mis":"SC4-1-u3-X17"},{"t":"상류에서는 침식만, 하류에서는 퇴적만 일어나기 때문에","mis":"SC4-1-u3-X15"},{"t":"하류에만 비가 오기 때문에","mis":"SC4-1-u3-X17"}],"explanation":["물의 작용을 떠올려요.","더 활발한 것이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#19','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C28',3,'mc','auto','모형실험과 실제 화산 활동의 같은 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X29','SC4-1-u3-X23']::text[],false,'{"seq":19,"concept":"SC4-1-u3-C28","difficulty":3,"kind":"mc","stem":"모형실험과 실제 화산 활동의 같은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"연기가 나고 붉은 액체가 흘러나와 굳는다","correct":true},{"t":"둘 다 단단한 암석 조각이 튀어나온다","mis":"SC4-1-u3-X29"},{"t":"둘 다 연기 색깔이 똑같다","mis":"SC4-1-u3-X29"},{"t":"둘 다 아무것도 나오지 않는다","mis":"SC4-1-u3-X23"}],"explanation":["모형실험을 떠올려요.","흘러나와 굳어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#20','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C33',3,'mc','auto','친구 모둠이 「무거운 암석」과 「가벼운 암석」으로 분류했어요. 이 기준에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X36','SC4-1-u3-X33','SC4-1-u3-X37']::text[],false,'{"seq":20,"concept":"SC4-1-u3-C33","difficulty":3,"kind":"mc","stem":"친구 모둠이 「무거운 암석」과 「가벼운 암석」으로 분류했어요. 이 기준에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"무게는 덩어리 크기에 따라 달라져 현무암과 화강암을 나누는 기준으로 알맞지 않다","correct":true},{"t":"무게가 가장 좋은 기준이다","mis":"SC4-1-u3-X36"},{"t":"무거운 것은 모두 화강암이다","mis":"SC4-1-u3-X33"},{"t":"가벼운 것은 모두 화산재이다","mis":"SC4-1-u3-X37"}],"explanation":["큰 덩어리는 무거워요.","암석 종류와 상관없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#21','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C37',3,'mc','auto','화산재가 일으킬 수 있는 피해를 모두 고른 것은 무엇인가요? ㉠ 비행기 운항 중단 ㉡ 농작물을 뒤덮음 ㉢ 땅속 열로 전기 생산 ㉣ 태양 빛을 가려 기온이 낮아짐',ARRAY['SC4-1-u3-X41','SC4-1-u3-X42']::text[],false,'{"seq":21,"concept":"SC4-1-u3-C37","difficulty":3,"kind":"mc","stem":"화산재가 일으킬 수 있는 피해를 모두 고른 것은 무엇인가요? ㉠ 비행기 운항 중단 ㉡ 농작물을 뒤덮음 ㉢ 땅속 열로 전기 생산 ㉣ 태양 빛을 가려 기온이 낮아짐","options":[{"t":"㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢","mis":"SC4-1-u3-X41"},{"t":"㉡, ㉢, ㉣","mis":"SC4-1-u3-X41"},{"t":"㉢만","mis":"SC4-1-u3-X42"}],"explanation":["피해를 찾아요.","㉢은 이로운 점이에요.","㉠, ㉡, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#22','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C45',3,'mc','auto','흔들림이 멈춘 뒤 문을 열어 두는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X54','SC4-1-u3-X50','SC4-1-u3-X49']::text[],false,'{"seq":22,"concept":"SC4-1-u3-C45","difficulty":3,"kind":"mc","stem":"흔들림이 멈춘 뒤 문을 열어 두는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"문이 비틀려 열리지 않으면 밖으로 나가기 어렵기 때문에","correct":true},{"t":"바람을 쐬어 시원해지려고","mis":"SC4-1-u3-X54"},{"t":"승강기를 빨리 부르려고","mis":"SC4-1-u3-X50"},{"t":"지진을 구경하려고","mis":"SC4-1-u3-X49"}],"explanation":["나갈 길이 필요해요.","문이 끼일 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#23','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C16',4,'mc','auto','친구가 「강 하류는 퇴적만 일어나니 바위가 깎이는 일은 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X15','SC4-1-u3-X16','SC4-1-u3-X14']::text[],false,'{"seq":23,"concept":"SC4-1-u3-C16","difficulty":4,"kind":"mc","stem":"친구가 「강 하류는 퇴적만 일어나니 바위가 깎이는 일은 전혀 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「하류에서도 깎이는 일이 일어나. 퇴적 작용이 더 활발할 뿐이야.」","correct":true},{"t":"「맞아, 하류는 쌓이는 일만 있어.」","mis":"SC4-1-u3-X15"},{"t":"「하류는 침식 작용이 가장 활발해.」","mis":"SC4-1-u3-X16"},{"t":"「하류에는 물이 흐르지 않아.」","mis":"SC4-1-u3-X14"}],"explanation":["세 작용은 함께예요.","더 활발할 뿐이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#24','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C8',4,'mc','auto','친구가 「단단한 바위는 흐르는 물로 절대 깎이지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X04','SC4-1-u3-X07','SC4-1-u3-X10']::text[],false,'{"seq":24,"concept":"SC4-1-u3-C8","difficulty":4,"kind":"mc","stem":"친구가 「단단한 바위는 흐르는 물로 절대 깎이지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「흐르는 물은 오랜 시간에 걸쳐 바위나 돌도 깎아 내. 그게 침식 작용이야.」","correct":true},{"t":"「맞아, 물은 흙만 깎을 수 있어.」","mis":"SC4-1-u3-X04"},{"t":"「바위가 깎이는 것은 퇴적 작용이야.」","mis":"SC4-1-u3-X07"},{"t":"「바위는 물을 거슬러 위로 올라가.」","mis":"SC4-1-u3-X10"}],"explanation":["침식 작용의 뜻을 떠올려요.","바위나 돌도요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_a#25','sci',4,1,'u3','','g4_1_sci_u3_review_a','unit_review','SC4-1-u3-C11',4,'essay','teacher','노을반 일지 ②를 보고 흙 언덕의 위쪽과 아래쪽에서 더 활발한 작용을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u3-C11","difficulty":4,"kind":"essay","stem":"노을반 일지 ②를 보고 흙 언덕의 위쪽과 아래쪽에서 더 활발한 작용을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 위쪽은 침식 작용이, 아래쪽은 퇴적 작용이 더 활발하다. 위쪽은 깎이기만 하는 것이 아니라 세 작용이 함께 일어나고, 곳에 따라 더 활발한 작용이 있을 뿐이다.","scoring_points":["위쪽·아래쪽에서 더 활발한 작용을 썼는가","세 작용이 함께 일어남을 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","더 활발한 작용이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["흙 언덕 꼭대기에 물을 흘려 보냈다.","위쪽은 움푹 파이고 흙탕물이 아래로 흘렀다.","아래쪽에 흙과 색 모래가 쌓였다.","친구 나 — 「위쪽은 깎이기만, 아래쪽은 쌓이기만 해.」"],"title":"노을반 일지 ② 흙 언덕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#1','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C4',1,'ox','auto','노을반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u3-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C4","difficulty":1,"kind":"ox","stem":"노을반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"진짜 땅도 물 때문에 조금씩 깎이고 쌓이며 변하기 때문에","correct":true},{"t":"땅은 한번 생기면 그대로이기 때문에","mis":"SC4-1-u3-X04"}],"mis":"SC4-1-u3-X04","explanation":["흙 성을 떠올려요.","진짜 땅도 변해요.","그래서 X예요."],"asset":{"type":"passage","lines":["운동장 흙으로 성을 쌓고 깃발을 꽂았다.","스포이트로 물을 뿌리자 흙이 깎였다.","흙탕물이 흐르고 성 아래에 흙이 쌓였다.","친구 가 — 「진짜 땅은 흙 성과 달라서 절대 변하지 않아.」"],"title":"노을반 일지 ① 흙 성 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#2','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C11',1,'ox','auto','노을반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u3-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C11","difficulty":1,"kind":"ox","stem":"노을반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"세 작용은 보통 함께 일어나고 곳에 따라 더 활발한 작용이 있을 뿐이기 때문에","correct":true},{"t":"위쪽과 아래쪽에서는 한 가지 작용만 일어나기 때문에","mis":"SC4-1-u3-X08"}],"mis":"SC4-1-u3-X08","explanation":["세 작용을 떠올려요.","함께 일어나요.","그래서 X예요."],"asset":{"type":"passage","lines":["흙 언덕 꼭대기에 물을 흘려 보냈다.","위쪽은 움푹 파이고 흙탕물이 아래로 흘렀다.","아래쪽에 흙과 색 모래가 쌓였다.","친구 나 — 「위쪽은 깎이기만, 아래쪽은 쌓이기만 해.」"],"title":"노을반 일지 ② 흙 언덕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#3','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C19',1,'ox','auto','노을반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC4-1-u3-X19']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C19","difficulty":1,"kind":"ox","stem":"노을반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"굽은 곳 바깥쪽은 빠르고 안쪽은 느리기 때문에","correct":true},{"t":"강의 한 곳에서는 물이 늘 같은 빠르기로 흐르기 때문에","mis":"SC4-1-u3-X19"}],"mis":"SC4-1-u3-X19","explanation":["셋째 줄을 읽어요.","빠르기가 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 큰 바위와 모난 돌이 많았다.","㉯ 강폭이 넓고 고운 모래가 많았다.","굽은 곳 바깥쪽은 물이 빠르고, 안쪽은 느렸다.","친구 다 — 「강의 한 곳에서는 물이 늘 똑같이 흘러.」"],"title":"노을반 일지 ③ 강 탐험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#4','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C26',1,'ox','auto','노을반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u3-X23']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C26","difficulty":1,"kind":"ox","stem":"노을반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"용암이 보이지 않아도 화산 가스나 화산재가 나오거나 분화구가 있으면 화산이기 때문에","correct":true},{"t":"용암이 흘러나와야만 화산이기 때문에","mis":"SC4-1-u3-X23"}],"mis":"SC4-1-u3-X23","explanation":["분화구가 있었어요.","용암만 보면 안 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["화산 사진 속 꼭대기에 움푹 파인 곳이 있었다.","모형실험에서 연기가 나고 마시멜로가 흘렀다.","흘러내린 마시멜로는 식어서 굳었다.","친구 가 — 「용암이 안 보이면 화산이 아니야.」"],"title":"노을반 일지 ④ 화산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#5','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C31',1,'ox','auto','노을반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u3-X34']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C31","difficulty":1,"kind":"ox","stem":"노을반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"구멍이 없어도 색이 어둡고 알갱이가 작으면 현무암이기 때문에","correct":true},{"t":"현무암은 모두 구멍이 있기 때문에","mis":"SC4-1-u3-X34"}],"mis":"SC4-1-u3-X34","explanation":["㉢을 읽어요.","어둡고 작아요.","그래서 X예요."],"asset":{"type":"passage","lines":["표본 ㉠ — 색이 밝고 알갱이가 크다.","표본 ㉡ — 색이 어둡고 알갱이가 작으며 구멍이 많다.","표본 ㉢ — 색이 어둡고 알갱이가 작으며 구멍이 없다.","친구 나 — 「구멍이 없으니 ㉢은 현무암이 아니야.」"],"title":"노을반 일지 ⑤ 암석 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#6','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C39',1,'ox','auto','노을반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC4-1-u3-X40']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C39","difficulty":1,"kind":"ox","stem":"노을반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"비옥한 땅과 온천처럼 이로운 점도 있기 때문에","correct":true},{"t":"화산은 해로운 일만 일으키기 때문에","mis":"SC4-1-u3-X40"}],"mis":"SC4-1-u3-X40","explanation":["둘째·셋째 줄을 읽어요.","좋은 점도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["화산재가 하늘을 덮어 비행기가 뜨지 못했다.","화산재가 쌓였던 땅에서 몇 해 뒤 농작물이 잘 자랐다.","화산 근처 온천에 관광객이 많이 왔다.","친구 다 — 「화산은 해롭기만 하니 좋은 점은 없어.」"],"title":"노을반 일지 ⑥ 화산과 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#7','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C45',1,'ox','auto','노을반 일지 ⑦의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u3-X50']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C45","difficulty":1,"kind":"ox","stem":"노을반 일지 ⑦의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"전기가 끊기면 승강기가 멈춰 갇힐 수 있어 계단을 이용해야 하기 때문에","correct":true},{"t":"승강기가 계단보다 늘 안전하기 때문에","mis":"SC4-1-u3-X50"}],"mis":"SC4-1-u3-X50","explanation":["승강기를 떠올려요.","계단이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["지진 대피 훈련 방송이 나왔다.","교실에서 책상 아래로 들어가 머리를 보호했다.","흔들림이 멈추자 계단으로 운동장에 나갔다.","친구 가 — 「다음엔 승강기를 타고 빨리 내려가자.」"],"title":"노을반 일지 ⑦ 지진 대피 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#8','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C50',1,'ox','auto','노을반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u3-X57']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C50","difficulty":1,"kind":"ox","stem":"노을반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"귀 기울여 듣고 칭찬할 점도 찾아 이야기해야 하기 때문에","correct":true},{"t":"아쉬운 점만 말해야 발표가 좋아지기 때문에","mis":"SC4-1-u3-X57"}],"mis":"SC4-1-u3-X57","explanation":["발표 듣는 태도예요.","칭찬도 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["모둠별로 지진 대비 재난방송을 만들었다.","발생 일시·장소·피해 내용·대처 방법을 담았다.","제주도의 오름과 용암 동굴 자료도 찾아보았다.","친구 나 — 「다른 모둠 발표는 아쉬운 점만 말해 주자.」"],"title":"노을반 일지 ⑧ 재난방송과 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#9','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C5',2,'ox','auto','흙 놀이를 할 때 흙에 쇳조각이나 유리 조각이 있는지 살펴요.',ARRAY['SC4-1-u3-X05']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C5","difficulty":2,"kind":"ox","stem":"흙 놀이를 할 때 흙에 쇳조각이나 유리 조각이 있는지 살펴요.","answer":"O","reason_options":[{"t":"날카로운 조각에 다칠 수 있기 때문에","correct":true},{"t":"흙에는 위험한 것이 절대 섞이지 않기 때문에","mis":"SC4-1-u3-X05"}],"mis":"SC4-1-u3-X05","explanation":["안전을 떠올려요.","다칠 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#10','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C12',2,'ox','auto','흐르는 물의 양이 많을수록 땅의 모습이 더 많이 변해요.',ARRAY['SC4-1-u3-X11']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C12","difficulty":2,"kind":"ox","stem":"흐르는 물의 양이 많을수록 땅의 모습이 더 많이 변해요.","answer":"O","reason_options":[{"t":"물이 많을수록 더 많이 깎고 옮기고 쌓기 때문에","correct":true},{"t":"물의 양은 땅의 변화와 상관없기 때문에","mis":"SC4-1-u3-X11"}],"mis":"SC4-1-u3-X11","explanation":["큰 구멍 컵을 떠올려요.","더 많이 변했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#11','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C20',2,'ox','auto','흐르는 물은 오랜 시간에 걸쳐 강 주변의 모습을 바꿔요.',ARRAY['SC4-1-u3-X21']::text[],false,'{"seq":11,"concept":"SC4-1-u3-C20","difficulty":2,"kind":"ox","stem":"흐르는 물은 오랜 시간에 걸쳐 강 주변의 모습을 바꿔요.","answer":"O","reason_options":[{"t":"강물이 오랫동안 조금씩 깎고 옮기고 쌓기 때문에","correct":true},{"t":"강 주변의 모습은 하루 만에 다 바뀌기 때문에","mis":"SC4-1-u3-X21"}],"mis":"SC4-1-u3-X21","explanation":["강은 오래 흘러요.","조금씩 바꿔요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#12','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C23',2,'ox','auto','화산은 크기와 생김새가 모두 같아요.',ARRAY['SC4-1-u3-X25']::text[],false,'{"seq":12,"concept":"SC4-1-u3-C23","difficulty":2,"kind":"ox","stem":"화산은 크기와 생김새가 모두 같아요.","answer":"X","reason_options":[{"t":"화산은 크기와 생김새가 다양하기 때문에","correct":true},{"t":"모든 화산은 똑같은 원뿔 모양이기 때문에","mis":"SC4-1-u3-X25"}],"mis":"SC4-1-u3-X25","explanation":["여러 화산을 떠올려요.","다양해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#13','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C30',2,'ox','auto','현무암과 화강암은 모두 화성암이에요.',ARRAY['SC4-1-u3-X37']::text[],false,'{"seq":13,"concept":"SC4-1-u3-C30","difficulty":2,"kind":"ox","stem":"현무암과 화강암은 모두 화성암이에요.","answer":"O","reason_options":[{"t":"둘 다 마그마가 식어서 만들어진 암석이기 때문에","correct":true},{"t":"현무암은 화산재가 굳은 것이고 화강암은 흙이 굳은 것이기 때문에","mis":"SC4-1-u3-X37"}],"mis":"SC4-1-u3-X37","explanation":["화성암의 뜻을 떠올려요.","마그마가 식었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
