INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#15','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C46',2,'ox','auto','지진이 났을 때는 당황하지 않고 침착하게 행동해야 해요.',ARRAY['SC4-1-u3-X49']::text[],false,'{"seq":15,"concept":"SC4-1-u3-C46","difficulty":2,"kind":"ox","stem":"지진이 났을 때는 당황하지 않고 침착하게 행동해야 해요.","answer":"O","reason_options":[{"t":"침착해야 상황과 장소에 맞게 안전하게 대처할 수 있기 때문에","correct":true},{"t":"무조건 빨리 뛰어나가는 것이 무엇보다 중요하기 때문에","mis":"SC4-1-u3-X49"}],"mis":"SC4-1-u3-X49","explanation":["당황하면 실수해요.","침착하게요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#16','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C51',2,'ox','auto','재난 대비 가방에 손전등과 라디오를 넣어요.',ARRAY['SC4-1-u3-X59']::text[],false,'{"seq":16,"concept":"SC4-1-u3-C51","difficulty":2,"kind":"ox","stem":"재난 대비 가방에 손전등과 라디오를 넣어요.","answer":"O","reason_options":[{"t":"전기가 끊겨도 빛과 소식을 얻을 수 있기 때문에","correct":true},{"t":"재난 때에는 소식을 들을 필요가 없기 때문에","mis":"SC4-1-u3-X59"}],"mis":"SC4-1-u3-X59","explanation":["어두울 수 있어요.","소식도 들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#17','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C10',3,'ox','auto','흙 언덕 아래쪽에 흙이 쌓이는 것은 물의 흐름이 느려지는 곳에 운반된 흙이 모이기 때문이에요.',ARRAY['SC4-1-u3-X09']::text[],false,'{"seq":17,"concept":"SC4-1-u3-C10","difficulty":3,"kind":"ox","stem":"흙 언덕 아래쪽에 흙이 쌓이는 것은 물의 흐름이 느려지는 곳에 운반된 흙이 모이기 때문이에요.","answer":"O","reason_options":[{"t":"물이 느려지면 옮기던 흙을 내려놓기 때문에","correct":true},{"t":"흙은 물이 가장 빠른 곳에만 쌓이기 때문에","mis":"SC4-1-u3-X09"}],"mis":"SC4-1-u3-X09","explanation":["느려지는 곳을 떠올려요.","내려놓아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#18','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C19',3,'ox','auto','굽은 강의 안쪽은 물이 느려 퇴적 작용이 주로 일어나요.',ARRAY['SC4-1-u3-X20']::text[],false,'{"seq":18,"concept":"SC4-1-u3-C19","difficulty":3,"kind":"ox","stem":"굽은 강의 안쪽은 물이 느려 퇴적 작용이 주로 일어나요.","answer":"O","reason_options":[{"t":"물이 느리면 옮기던 모래와 흙을 쌓기 때문에","correct":true},{"t":"강의 안쪽은 물이 가장 빨라 깎이기 때문에","mis":"SC4-1-u3-X20"}],"mis":"SC4-1-u3-X20","explanation":["안쪽은 느려요.","쌓여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#19','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C26',3,'ox','auto','화산이 분출할 때 분출물이 모두 함께 나올 때도, 한두 가지만 주로 나올 때도 있어요.',ARRAY['SC4-1-u3-X23']::text[],false,'{"seq":19,"concept":"SC4-1-u3-C26","difficulty":3,"kind":"ox","stem":"화산이 분출할 때 분출물이 모두 함께 나올 때도, 한두 가지만 주로 나올 때도 있어요.","answer":"O","reason_options":[{"t":"화산마다 분출하는 물질이 다를 수 있기 때문에","correct":true},{"t":"화산은 언제나 용암 한 가지만 내놓기 때문에","mis":"SC4-1-u3-X23"}],"mis":"SC4-1-u3-X23","explanation":["화산마다 달라요.","여러 가지예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#20','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C32',3,'ox','auto','색이 밝고 알갱이가 크며 분홍색 알갱이가 많은 암석은 화강암일 수 있어요.',ARRAY['SC4-1-u3-X35']::text[],false,'{"seq":20,"concept":"SC4-1-u3-C32","difficulty":3,"kind":"ox","stem":"색이 밝고 알갱이가 크며 분홍색 알갱이가 많은 암석은 화강암일 수 있어요.","answer":"O","reason_options":[{"t":"화강암은 색이 밝고 알갱이가 크며 분홍색 알갱이가 많은 것도 있기 때문에","correct":true},{"t":"화강암은 흰색과 검은색 알갱이로만 되어 있기 때문에","mis":"SC4-1-u3-X35"}],"mis":"SC4-1-u3-X35","explanation":["밝고 알갱이가 커요.","분홍색도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#21','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C40',3,'ox','auto','화산에 대비해 평소에 마스크와 보안경을 준비해 두면 좋아요.',ARRAY['SC4-1-u3-X44']::text[],false,'{"seq":21,"concept":"SC4-1-u3-C40","difficulty":3,"kind":"ox","stem":"화산에 대비해 평소에 마스크와 보안경을 준비해 두면 좋아요.","answer":"O","reason_options":[{"t":"화산재와 화산 가스로부터 코와 입, 눈을 보호할 수 있기 때문에","correct":true},{"t":"화산재는 몸에 전혀 해롭지 않기 때문에","mis":"SC4-1-u3-X44"}],"mis":"SC4-1-u3-X44","explanation":["무엇을 막아야 할까요?","코·입·눈이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#22','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C43',3,'ox','auto','지진은 다른 나라에서만 일어나는 일이라 우리는 준비하지 않아도 돼요.',ARRAY['SC4-1-u3-X48']::text[],false,'{"seq":22,"concept":"SC4-1-u3-C43","difficulty":3,"kind":"ox","stem":"지진은 다른 나라에서만 일어나는 일이라 우리는 준비하지 않아도 돼요.","answer":"X","reason_options":[{"t":"우리나라도 지진으로부터 안전하지 않기 때문에","correct":true},{"t":"우리나라에는 지진 피해가 한 번도 없었기 때문에","mis":"SC4-1-u3-X48"}],"mis":"SC4-1-u3-X48","explanation":["우리나라도 흔들렸어요.","피해가 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#23','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C22',4,'mc','auto','친구가 「땅속에 녹아 있는 암석도, 땅 위로 흐르는 것도 모두 마그마야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X22','SC4-1-u3-X26']::text[],false,'{"seq":23,"concept":"SC4-1-u3-C22","difficulty":4,"kind":"mc","stem":"친구가 「땅속에 녹아 있는 암석도, 땅 위로 흐르는 것도 모두 마그마야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「땅속에 있으면 마그마, 땅 위로 나와 흐르면 용암이라고 해.」","correct":true},{"t":"「맞아, 둘은 같은 말이야.」","mis":"SC4-1-u3-X22"},{"t":"「땅속에 있는 것이 용암이야.」","mis":"SC4-1-u3-X22"},{"t":"「땅 위로 흐르는 것은 화산 가스야.」","mis":"SC4-1-u3-X26"}],"explanation":["있는 곳이 달라요.","이름도 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#24','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C29',4,'mc','auto','친구가 「화산 모형실험은 재미있으니 장갑 없이 해도 괜찮아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X31']::text[],false,'{"seq":24,"concept":"SC4-1-u3-C29","difficulty":4,"kind":"mc","stem":"친구가 「화산 모형실험은 재미있으니 장갑 없이 해도 괜찮아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「가열한 포일은 아주 뜨거워. 두꺼운 면장갑과 보안경을 꼭 써야 해.」","correct":true},{"t":"「맞아, 맨손이 더 편해.」","mis":"SC4-1-u3-X31"},{"t":"「마시멜로는 맛을 봐도 돼.」","mis":"SC4-1-u3-X31"},{"t":"「환기는 하지 않아도 돼.」","mis":"SC4-1-u3-X31"}],"explanation":["뜨거워요.","안전이 먼저예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_b#25','sci',4,1,'u3','','g4_1_sci_u3_review_b','unit_review','SC4-1-u3-C26',4,'essay','teacher','노을반 일지 ④를 보고 화산인지 아닌지 구분하는 방법을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u3-C26","difficulty":4,"kind":"essay","stem":"노을반 일지 ④를 보고 화산인지 아닌지 구분하는 방법을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 물질이 분출하는지, 분화구가 있는지로 구분한다. 화산은 용암이 아니라 화산 가스나 화산재만 주로 나올 때도 있으므로 용암이 보이지 않아도 분화구가 있으면 화산일 수 있다.","scoring_points":["분출 여부와 분화구로 구분한다고 썼는가","용암 말고 다른 분출물도 있음을 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","분화구가 있었어요.","고쳐 써요."],"asset":{"type":"passage","lines":["화산 사진 속 꼭대기에 움푹 파인 곳이 있었다.","모형실험에서 연기가 나고 마시멜로가 흘렀다.","흘러내린 마시멜로는 식어서 굳었다.","친구 가 — 「용암이 안 보이면 화산이 아니야.」"],"title":"노을반 일지 ④ 화산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#1','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C2',1,'mc','auto','노을반 일지 ①에서 깎인 흙은 마지막에 어디에 있었나요?',ARRAY['SC4-1-u3-X02','SC4-1-u3-X06']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C2","difficulty":1,"kind":"mc","stem":"노을반 일지 ①에서 깎인 흙은 마지막에 어디에 있었나요?","options":[{"t":"성 아래","correct":true},{"t":"하늘","mis":"SC4-1-u3-X02"},{"t":"깃발 위","mis":"SC4-1-u3-X02"},{"t":"스포이트 속","mis":"SC4-1-u3-X06"}],"explanation":["셋째 줄을 읽어요.","아래에 쌓였어요.","성 아래예요."],"asset":{"type":"passage","lines":["운동장 흙으로 성을 쌓고 깃발을 꽂았다.","스포이트로 물을 뿌리자 흙이 깎였다.","흙탕물이 흐르고 성 아래에 흙이 쌓였다.","친구 가 — 「진짜 땅은 흙 성과 달라서 절대 변하지 않아.」"],"title":"노을반 일지 ① 흙 성 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#2','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C8',1,'mc','auto','노을반 일지 ②에서 위쪽이 움푹 파인 것은 어떤 작용인가요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X13']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C8","difficulty":1,"kind":"mc","stem":"노을반 일지 ②에서 위쪽이 움푹 파인 것은 어떤 작용인가요?","options":[{"t":"침식 작용","correct":true},{"t":"퇴적 작용","mis":"SC4-1-u3-X07"},{"t":"운반 작용","mis":"SC4-1-u3-X07"},{"t":"흙이 스스로 움직인 것","mis":"SC4-1-u3-X13"}],"explanation":["둘째 줄을 읽어요.","깎였어요.","침식 작용이에요."],"asset":{"type":"passage","lines":["흙 언덕 꼭대기에 물을 흘려 보냈다.","위쪽은 움푹 파이고 흙탕물이 아래로 흘렀다.","아래쪽에 흙과 색 모래가 쌓였다.","친구 나 — 「위쪽은 깎이기만, 아래쪽은 쌓이기만 해.」"],"title":"노을반 일지 ② 흙 언덕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#3','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C15',1,'mc','auto','노을반 일지 ③의 ㉯에서 더 활발한 작용은 무엇인가요?',ARRAY['SC4-1-u3-X16','SC4-1-u3-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C15","difficulty":1,"kind":"mc","stem":"노을반 일지 ③의 ㉯에서 더 활발한 작용은 무엇인가요?","options":[{"t":"퇴적 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X16"},{"t":"퇴적 작용은 일어나지 않는다","mis":"SC4-1-u3-X15"},{"t":"운반 작용만","mis":"SC4-1-u3-X15"}],"explanation":["둘째 줄을 읽어요.","모래가 쌓였어요.","퇴적 작용이에요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 큰 바위와 모난 돌이 많았다.","㉯ 강폭이 넓고 고운 모래가 많았다.","굽은 곳 바깥쪽은 물이 빠르고, 안쪽은 느렸다.","친구 다 — 「강의 한 곳에서는 물이 늘 똑같이 흘러.」"],"title":"노을반 일지 ③ 강 탐험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#4','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C27',1,'mc','auto','노을반 일지 ④의 모형실험에서 피어오른 연기는 실제 화산의 무엇에 해당하나요?',ARRAY['SC4-1-u3-X28','SC4-1-u3-X22']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C27","difficulty":1,"kind":"mc","stem":"노을반 일지 ④의 모형실험에서 피어오른 연기는 실제 화산의 무엇에 해당하나요?","options":[{"t":"화산 가스","correct":true},{"t":"용암","mis":"SC4-1-u3-X28"},{"t":"화산 암석 조각","mis":"SC4-1-u3-X28"},{"t":"마그마","mis":"SC4-1-u3-X22"}],"explanation":["연기는 기체예요.","가스예요.","화산 가스예요."],"asset":{"type":"passage","lines":["화산 사진 속 꼭대기에 움푹 파인 곳이 있었다.","모형실험에서 연기가 나고 마시멜로가 흘렀다.","흘러내린 마시멜로는 식어서 굳었다.","친구 가 — 「용암이 안 보이면 화산이 아니야.」"],"title":"노을반 일지 ④ 화산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#5','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C31',1,'mc','auto','노을반 일지 ⑤의 표본 ㉡은 어떤 암석인가요?',ARRAY['SC4-1-u3-X33','SC4-1-u3-X37','SC4-1-u3-X39']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C31","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑤의 표본 ㉡은 어떤 암석인가요?","options":[{"t":"현무암","correct":true},{"t":"화강암","mis":"SC4-1-u3-X33"},{"t":"분화구","mis":"SC4-1-u3-X37"},{"t":"흙","mis":"SC4-1-u3-X39"}],"explanation":["어둡고 알갱이가 작아요.","구멍도 많아요.","현무암이에요."],"asset":{"type":"passage","lines":["표본 ㉠ — 색이 밝고 알갱이가 크다.","표본 ㉡ — 색이 어둡고 알갱이가 작으며 구멍이 많다.","표본 ㉢ — 색이 어둡고 알갱이가 작으며 구멍이 없다.","친구 나 — 「구멍이 없으니 ㉢은 현무암이 아니야.」"],"title":"노을반 일지 ⑤ 암석 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#6','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C38',1,'mc','auto','노을반 일지 ⑥에서 이로운 점에 해당하는 것은 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X45']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C38","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑥에서 이로운 점에 해당하는 것은 무엇인가요?","options":[{"t":"화산 근처 온천에 관광객이 많이 왔다","correct":true},{"t":"화산재가 하늘을 덮었다","mis":"SC4-1-u3-X41"},{"t":"비행기가 뜨지 못했다","mis":"SC4-1-u3-X41"},{"t":"바람으로 전기를 만들었다","mis":"SC4-1-u3-X45"}],"explanation":["도움이 된 일이에요.","셋째 줄이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["화산재가 하늘을 덮어 비행기가 뜨지 못했다.","화산재가 쌓였던 땅에서 몇 해 뒤 농작물이 잘 자랐다.","화산 근처 온천에 관광객이 많이 왔다.","친구 다 — 「화산은 해롭기만 하니 좋은 점은 없어.」"],"title":"노을반 일지 ⑥ 화산과 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#7','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C45',1,'mc','auto','노을반 일지 ⑦에서 흔들림이 멈춘 뒤 대피할 때 이용한 것은 무엇인가요?',ARRAY['SC4-1-u3-X50','SC4-1-u3-X49']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C45","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑦에서 흔들림이 멈춘 뒤 대피할 때 이용한 것은 무엇인가요?","options":[{"t":"계단","correct":true},{"t":"승강기","mis":"SC4-1-u3-X50"},{"t":"창문","mis":"SC4-1-u3-X49"},{"t":"옥상","mis":"SC4-1-u3-X49"}],"explanation":["셋째 줄을 읽어요.","걸어서 내려갔어요.","계단이에요."],"asset":{"type":"passage","lines":["지진 대피 훈련 방송이 나왔다.","교실에서 책상 아래로 들어가 머리를 보호했다.","흔들림이 멈추자 계단으로 운동장에 나갔다.","친구 가 — 「다음엔 승강기를 타고 빨리 내려가자.」"],"title":"노을반 일지 ⑦ 지진 대피 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#8','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C52',1,'mc','auto','노을반 일지 ⑧에서 찾아본 오름은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C52","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑧에서 찾아본 오름은 무엇인가요?","options":[{"t":"제주도 곳곳에 있는 작은 화산","correct":true},{"t":"사람이 쌓은 흙더미","mis":"SC4-1-u3-X60"},{"t":"바닷물이 깎은 바위","mis":"SC4-1-u3-X60"},{"t":"화산과 관계없는 언덕","mis":"SC4-1-u3-X60"}],"explanation":["제주도를 떠올려요.","작은 화산이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 지진 대비 재난방송을 만들었다.","발생 일시·장소·피해 내용·대처 방법을 담았다.","제주도의 오름과 용암 동굴 자료도 찾아보았다.","친구 나 — 「다른 모둠 발표는 아쉬운 점만 말해 주자.」"],"title":"노을반 일지 ⑧ 재난방송과 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#9','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C2',2,'mc','auto','흙 성에 물을 뿌린 뒤 흘러내린 물이 흙탕물이 된 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X02','SC4-1-u3-X01','SC4-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C2","difficulty":2,"kind":"mc","stem":"흙 성에 물을 뿌린 뒤 흘러내린 물이 흙탕물이 된 까닭은 무엇인가요?","options":[{"t":"물이 깎인 흙을 함께 옮겼기 때문에","correct":true},{"t":"물이 흙을 없앴기 때문에","mis":"SC4-1-u3-X02"},{"t":"흙이 물을 더 맑게 했기 때문에","mis":"SC4-1-u3-X01"},{"t":"스포이트에 흙이 들어 있었기 때문에","mis":"SC4-1-u3-X06"}],"explanation":["흙이 섞였어요.","물이 옮겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#10','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C9',2,'blank','auto','「침식 작용으로 만들어진 돌이나 흙 등이 물과 함께 이동하는 것을 (      ) 작용이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X13']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C9","difficulty":2,"kind":"blank","stem":"「침식 작용으로 만들어진 돌이나 흙 등이 물과 함께 이동하는 것을 (      ) 작용이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"운반","correct":true},{"t":"침식","mis":"SC4-1-u3-X07"},{"t":"퇴적","mis":"SC4-1-u3-X07"},{"t":"정지","mis":"SC4-1-u3-X13"}],"explanation":["이동해요.","옮겨요.","운반이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
