INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#12','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C21',2,'mc','auto','마그마와 용암을 바르게 구별한 것은 무엇인가요?',ARRAY['SC4-1-u3-X22','SC4-1-u3-X26']::text[],false,'{"seq":12,"concept":"SC4-1-u3-C21","difficulty":2,"kind":"mc","stem":"마그마와 용암을 바르게 구별한 것은 무엇인가요?","options":[{"t":"땅속에 녹아 있으면 마그마, 땅 위로 나와 흐르면 용암","correct":true},{"t":"땅속에 있으면 용암, 땅 위로 나오면 마그마","mis":"SC4-1-u3-X22"},{"t":"마그마와 용암은 화산 가스의 다른 이름","mis":"SC4-1-u3-X22"},{"t":"마그마는 고체, 용암은 기체","mis":"SC4-1-u3-X26"}],"explanation":["있는 곳을 봐요.","땅속과 땅 위예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#13','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C34',2,'mc','auto','돌하르방과 석굴암을 만든 암석을 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-1-u3-X38','SC4-1-u3-X37']::text[],false,'{"seq":13,"concept":"SC4-1-u3-C34","difficulty":2,"kind":"mc","stem":"돌하르방과 석굴암을 만든 암석을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"현무암, 화강암","correct":true},{"t":"화강암, 현무암","mis":"SC4-1-u3-X38"},{"t":"현무암, 현무암","mis":"SC4-1-u3-X38"},{"t":"화산재, 용암","mis":"SC4-1-u3-X37"}],"explanation":["돌하르방은 어두워요.","석굴암은 밝아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#14','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C36',2,'mc','auto','용암이 마을로 흘렀을 때 생길 수 있는 피해는 무엇인가요?',ARRAY['SC4-1-u3-X41','SC4-1-u3-X42']::text[],false,'{"seq":14,"concept":"SC4-1-u3-C36","difficulty":2,"kind":"mc","stem":"용암이 마을로 흘렀을 때 생길 수 있는 피해는 무엇인가요?","options":[{"t":"집과 건물에 불이 나고 사람이 다칠 수 있다","correct":true},{"t":"땅이 곧바로 비옥해진다","mis":"SC4-1-u3-X41"},{"t":"온천이 새로 생겨 관광객이 온다","mis":"SC4-1-u3-X41"},{"t":"하늘이 더 맑아진다","mis":"SC4-1-u3-X42"}],"explanation":["용암은 뜨거워요.","불이 나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#15','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C44',2,'mc','auto','대형 할인점에서 땅이 흔들릴 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u3-X53','SC4-1-u3-X50','SC4-1-u3-X49']::text[],false,'{"seq":15,"concept":"SC4-1-u3-C44","difficulty":2,"kind":"mc","stem":"대형 할인점에서 땅이 흔들릴 때 알맞은 행동은 무엇인가요?","options":[{"t":"장바구니 등으로 머리를 보호하고 진열대에서 떨어진다","correct":true},{"t":"진열대 바로 옆에 붙어 선다","mis":"SC4-1-u3-X53"},{"t":"승강기를 찾아 탄다","mis":"SC4-1-u3-X50"},{"t":"출입구로 한꺼번에 뛰어간다","mis":"SC4-1-u3-X49"}],"explanation":["물건이 떨어져요.","머리를 지켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#16','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C52',2,'mc','auto','백록담은 어떤 곳인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":16,"concept":"SC4-1-u3-C52","difficulty":2,"kind":"mc","stem":"백록담은 어떤 곳인가요?","options":[{"t":"한라산 꼭대기에 있는 물웅덩이","correct":true},{"t":"바닷가의 모래밭","mis":"SC4-1-u3-X60"},{"t":"사람이 판 연못","mis":"SC4-1-u3-X60"},{"t":"용암 동굴 속 강","mis":"SC4-1-u3-X60"}],"explanation":["한라산을 떠올려요.","꼭대기에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#17','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C3',3,'mc','auto','흙 성 놀이에서 스포이트를 세게 누르면 깃발이 더 빨리 쓰러지는 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X03','SC4-1-u3-X02']::text[],false,'{"seq":17,"concept":"SC4-1-u3-C3","difficulty":3,"kind":"mc","stem":"흙 성 놀이에서 스포이트를 세게 누르면 깃발이 더 빨리 쓰러지는 까닭은 무엇인가요?","options":[{"t":"물이 세게 뿌려져 흙을 더 많이 깎기 때문에","correct":true},{"t":"물이 약하게 퍼져 흙이 단단해지기 때문에","mis":"SC4-1-u3-X03"},{"t":"세게 누르면 물이 흙을 위로 올리기 때문에","mis":"SC4-1-u3-X02"},{"t":"깃발이 물에 닿으면 저절로 녹기 때문에","mis":"SC4-1-u3-X03"}],"explanation":["세게 뿌려요.","많이 깎여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#18','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C18',3,'mc','auto','강 상류에서 모난 돌이 많은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X18','SC4-1-u3-X14','SC4-1-u3-X17']::text[],false,'{"seq":18,"concept":"SC4-1-u3-C18","difficulty":3,"kind":"mc","stem":"강 상류에서 모난 돌이 많은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"바위에서 깎여 나온 지 얼마 되지 않아 아직 덜 닳았기 때문에","correct":true},{"t":"물에 실려 갈수록 돌이 더 뾰족해지기 때문에","mis":"SC4-1-u3-X18"},{"t":"상류에서는 물이 흐르지 않기 때문에","mis":"SC4-1-u3-X14"},{"t":"하류의 모난 돌이 상류로 거슬러 올라오기 때문에","mis":"SC4-1-u3-X17"}],"explanation":["막 깎여 나왔어요.","아직 덜 굴렀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#19','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C23',3,'mc','auto','화산이 아닌 산의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X24','SC4-1-u3-X25']::text[],false,'{"seq":19,"concept":"SC4-1-u3-C23","difficulty":3,"kind":"mc","stem":"화산이 아닌 산의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"분출하는 물질도 분화구도 없다","correct":true},{"t":"꼭대기에 눈이 쌓여 있다","mis":"SC4-1-u3-X24"},{"t":"키가 아주 크다","mis":"SC4-1-u3-X24"},{"t":"생김새가 모두 같다","mis":"SC4-1-u3-X25"}],"explanation":["화산의 특징을 떠올려요.","그것이 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#20','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C31',3,'mc','auto','색이 어둡고 알갱이가 눈에 안 보일 만큼 작은 표본은 무엇일까요?',ARRAY['SC4-1-u3-X33','SC4-1-u3-X37']::text[],false,'{"seq":20,"concept":"SC4-1-u3-C31","difficulty":3,"kind":"mc","stem":"색이 어둡고 알갱이가 눈에 안 보일 만큼 작은 표본은 무엇일까요?","options":[{"t":"현무암","correct":true},{"t":"화강암","mis":"SC4-1-u3-X33"},{"t":"화산재","mis":"SC4-1-u3-X37"},{"t":"마그마","mis":"SC4-1-u3-X37"}],"explanation":["어둡고 작아요.","현무암의 특징이에요.","현무암이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#21','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C38',3,'mc','auto','화산 분출물을 이용해 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X45','SC4-1-u3-X43','SC4-1-u3-X40']::text[],false,'{"seq":21,"concept":"SC4-1-u3-C38","difficulty":3,"kind":"mc","stem":"화산 분출물을 이용해 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"화산 분출물로 여러 가지 상품을 만든다","correct":true},{"t":"화산 분출물로 바람을 만든다","mis":"SC4-1-u3-X45"},{"t":"화산 분출물로 화산을 멈춘다","mis":"SC4-1-u3-X43"},{"t":"화산 분출물은 쓸모가 없어 모두 버린다","mis":"SC4-1-u3-X40"}],"explanation":["이로운 점을 떠올려요.","상품도 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#22','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C50',3,'mc','auto','안내 자료를 만들 때 역할을 나누는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X57','SC4-1-u3-X56']::text[],false,'{"seq":22,"concept":"SC4-1-u3-C50","difficulty":3,"kind":"mc","stem":"안내 자료를 만들 때 역할을 나누는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모두가 골고루 역할을 맡아 함께 만든다","correct":true},{"t":"잘하는 한 사람에게 모든 일을 맡긴다","mis":"SC4-1-u3-X57"},{"t":"역할 없이 각자 꾸미기에만 힘쓴다","mis":"SC4-1-u3-X56"},{"t":"맡을 일이 없는 친구는 빼고 만든다","mis":"SC4-1-u3-X57"}],"explanation":["함께 만들어요.","골고루요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#23','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C34',4,'mc','auto','친구가 「제주도 돌담은 밝은색 돌이니까 화강암이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X38','SC4-1-u3-X37','SC4-1-u3-X36']::text[],false,'{"seq":23,"concept":"SC4-1-u3-C34","difficulty":4,"kind":"mc","stem":"친구가 「제주도 돌담은 밝은색 돌이니까 화강암이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「제주도 돌담은 색이 어둡고 구멍이 있는 현무암이야.」","correct":true},{"t":"「맞아, 돌담은 화강암이야.」","mis":"SC4-1-u3-X38"},{"t":"「돌담은 화산재를 뭉친 거야.」","mis":"SC4-1-u3-X37"},{"t":"「돌담 돌은 무게로만 알 수 있어.」","mis":"SC4-1-u3-X36"}],"explanation":["돌담을 떠올려요.","어둡고 구멍이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#24','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C37',4,'mc','auto','친구가 「화산재는 가벼운 가루라서 아무 피해도 주지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X42','SC4-1-u3-X41','SC4-1-u3-X43']::text[],false,'{"seq":24,"concept":"SC4-1-u3-C37","difficulty":4,"kind":"mc","stem":"친구가 「화산재는 가벼운 가루라서 아무 피해도 주지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「화산재는 마을과 농작물을 뒤덮고 비행기 운항을 막고 숨쉬기 어렵게 할 수 있어.」","correct":true},{"t":"「맞아, 화산재는 안전해.」","mis":"SC4-1-u3-X42"},{"t":"「화산재는 땅을 바로 비옥하게만 해.」","mis":"SC4-1-u3-X41"},{"t":"「화산재는 막으면 그만이야.」","mis":"SC4-1-u3-X43"}],"explanation":["화산재의 피해를 떠올려요.","여러 가지예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_c#25','sci',4,1,'u3','','g4_1_sci_u3_review_c','unit_review','SC4-1-u3-C39',4,'essay','teacher','노을반 일지 ⑥을 보고 화산 활동의 피해와 이로운 점을 하나씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u3-C39","difficulty":4,"kind":"essay","stem":"노을반 일지 ⑥을 보고 화산 활동의 피해와 이로운 점을 하나씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 피해는 화산재가 하늘을 덮어 비행기가 뜨지 못한 것이고, 이로운 점은 화산재가 쌓인 땅이 비옥해져 농작물이 잘 자란 것이다. 화산 활동은 피해도 주지만 온천·관광처럼 이로운 점도 있다.","scoring_points":["피해를 하나 바르게 썼는가","이로운 점을 하나 바르게 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 쪽을 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["화산재가 하늘을 덮어 비행기가 뜨지 못했다.","화산재가 쌓였던 땅에서 몇 해 뒤 농작물이 잘 자랐다.","화산 근처 온천에 관광객이 많이 왔다.","친구 다 — 「화산은 해롭기만 하니 좋은 점은 없어.」"],"title":"노을반 일지 ⑥ 화산과 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#1','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C3',1,'mc','auto','노을반 일지 ①의 놀이에서 깃발을 더 빨리 쓰러뜨리는 방법은 무엇인가요?',ARRAY['SC4-1-u3-X03']::text[],false,'{"seq":1,"concept":"SC4-1-u3-C3","difficulty":1,"kind":"mc","stem":"노을반 일지 ①의 놀이에서 깃발을 더 빨리 쓰러뜨리는 방법은 무엇인가요?","options":[{"t":"한곳에 물을 집중해서 뿌린다","correct":true},{"t":"물을 아주 조금 뿌린다","mis":"SC4-1-u3-X03"},{"t":"물을 여기저기 흩뿌린다","mis":"SC4-1-u3-X03"},{"t":"깃발을 더 깊이 꽂는다","mis":"SC4-1-u3-X03"}],"explanation":["한곳을 노려요.","많이 깎여요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동장 흙으로 성을 쌓고 깃발을 꽂았다.","스포이트로 물을 뿌리자 흙이 깎였다.","흙탕물이 흐르고 성 아래에 흙이 쌓였다.","친구 가 — 「진짜 땅은 흙 성과 달라서 절대 변하지 않아.」"],"title":"노을반 일지 ① 흙 성 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#2','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C9',1,'mc','auto','노을반 일지 ②에서 흙탕물이 아래로 흐르며 흙을 옮긴 것은 어떤 작용인가요?',ARRAY['SC4-1-u3-X07','SC4-1-u3-X10']::text[],false,'{"seq":2,"concept":"SC4-1-u3-C9","difficulty":1,"kind":"mc","stem":"노을반 일지 ②에서 흙탕물이 아래로 흐르며 흙을 옮긴 것은 어떤 작용인가요?","options":[{"t":"운반 작용","correct":true},{"t":"침식 작용","mis":"SC4-1-u3-X07"},{"t":"퇴적 작용","mis":"SC4-1-u3-X07"},{"t":"흙이 물을 거슬러 오른 것","mis":"SC4-1-u3-X10"}],"explanation":["흙탕물이 흘렀어요.","옮겼어요.","운반 작용이에요."],"asset":{"type":"passage","lines":["흙 언덕 꼭대기에 물을 흘려 보냈다.","위쪽은 움푹 파이고 흙탕물이 아래로 흘렀다.","아래쪽에 흙과 색 모래가 쌓였다.","친구 나 — 「위쪽은 깎이기만, 아래쪽은 쌓이기만 해.」"],"title":"노을반 일지 ② 흙 언덕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#3','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C19',1,'mc','auto','노을반 일지 ③의 굽은 곳 바깥쪽에서 주로 일어나는 작용은 무엇인가요?',ARRAY['SC4-1-u3-X20','SC4-1-u3-X19']::text[],false,'{"seq":3,"concept":"SC4-1-u3-C19","difficulty":1,"kind":"mc","stem":"노을반 일지 ③의 굽은 곳 바깥쪽에서 주로 일어나는 작용은 무엇인가요?","options":[{"t":"침식 작용","correct":true},{"t":"퇴적 작용","mis":"SC4-1-u3-X20"},{"t":"아무 작용도 없다","mis":"SC4-1-u3-X19"},{"t":"모래가 쌓이는 작용","mis":"SC4-1-u3-X20"}],"explanation":["바깥쪽은 빨라요.","깎여요.","침식 작용이에요."],"asset":{"type":"passage","lines":["㉮ 강폭이 좁고 큰 바위와 모난 돌이 많았다.","㉯ 강폭이 넓고 고운 모래가 많았다.","굽은 곳 바깥쪽은 물이 빠르고, 안쪽은 느렸다.","친구 다 — 「강의 한 곳에서는 물이 늘 똑같이 흘러.」"],"title":"노을반 일지 ③ 강 탐험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#4','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C29',1,'mc','auto','노을반 일지 ④에서 흘러내린 마시멜로가 굳은 것처럼 실제 용암은 식으면 무엇이 되나요?',ARRAY['SC4-1-u3-X30']::text[],false,'{"seq":4,"concept":"SC4-1-u3-C29","difficulty":1,"kind":"mc","stem":"노을반 일지 ④에서 흘러내린 마시멜로가 굳은 것처럼 실제 용암은 식으면 무엇이 되나요?","options":[{"t":"암석","correct":true},{"t":"물","mis":"SC4-1-u3-X30"},{"t":"화산 가스","mis":"SC4-1-u3-X30"},{"t":"마그마","mis":"SC4-1-u3-X30"}],"explanation":["셋째 줄을 읽어요.","굳었어요.","암석이에요."],"asset":{"type":"passage","lines":["화산 사진 속 꼭대기에 움푹 파인 곳이 있었다.","모형실험에서 연기가 나고 마시멜로가 흘렀다.","흘러내린 마시멜로는 식어서 굳었다.","친구 가 — 「용암이 안 보이면 화산이 아니야.」"],"title":"노을반 일지 ④ 화산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#5','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C33',1,'mc','auto','노을반 일지 ⑤에서 표본을 나눈 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X36']::text[],false,'{"seq":5,"concept":"SC4-1-u3-C33","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑤에서 표본을 나눈 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"색깔과 알갱이의 크기","correct":true},{"t":"표본의 무게","mis":"SC4-1-u3-X36"},{"t":"표본 덩어리의 크기","mis":"SC4-1-u3-X36"},{"t":"표본을 주운 날짜","mis":"SC4-1-u3-X36"}],"explanation":["일지가 무엇을 적었나요?","색과 알갱이예요.","첫 번째예요."],"asset":{"type":"passage","lines":["표본 ㉠ — 색이 밝고 알갱이가 크다.","표본 ㉡ — 색이 어둡고 알갱이가 작으며 구멍이 많다.","표본 ㉢ — 색이 어둡고 알갱이가 작으며 구멍이 없다.","친구 나 — 「구멍이 없으니 ㉢은 현무암이 아니야.」"],"title":"노을반 일지 ⑤ 암석 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#6','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C38',1,'mc','auto','노을반 일지 ⑥에서 몇 해 뒤 농작물이 잘 자란 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X42','SC4-1-u3-X46']::text[],false,'{"seq":6,"concept":"SC4-1-u3-C38","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑥에서 몇 해 뒤 농작물이 잘 자란 까닭은 무엇인가요?","options":[{"t":"화산재가 쌓인 땅이 비옥해졌기 때문에","correct":true},{"t":"화산재가 태양 빛을 막아 주었기 때문에","mis":"SC4-1-u3-X42"},{"t":"땅속의 열로 전기를 만들었기 때문에","mis":"SC4-1-u3-X46"},{"t":"화산 가스가 비료가 되었기 때문에","mis":"SC4-1-u3-X42"}],"explanation":["둘째 줄을 읽어요.","땅이 기름져요.","첫 번째예요."],"asset":{"type":"passage","lines":["화산재가 하늘을 덮어 비행기가 뜨지 못했다.","화산재가 쌓였던 땅에서 몇 해 뒤 농작물이 잘 자랐다.","화산 근처 온천에 관광객이 많이 왔다.","친구 다 — 「화산은 해롭기만 하니 좋은 점은 없어.」"],"title":"노을반 일지 ⑥ 화산과 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#7','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C46',1,'mc','auto','노을반 일지 ⑦처럼 지진 대피 훈련을 하는 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X52','SC4-1-u3-X48']::text[],false,'{"seq":7,"concept":"SC4-1-u3-C46","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑦처럼 지진 대피 훈련을 하는 까닭은 무엇인가요?","options":[{"t":"지진은 언제 일어날지 정확히 알기 어려워 미리 익혀 두려고","correct":true},{"t":"지진은 언제 일어날지 정확히 알 수 있어서","mis":"SC4-1-u3-X52"},{"t":"우리나라에는 지진 피해가 없어서","mis":"SC4-1-u3-X48"},{"t":"훈련하면 지진을 멈출 수 있어서","mis":"SC4-1-u3-X52"}],"explanation":["갑자기 일어나요.","미리 익혀요.","첫 번째예요."],"asset":{"type":"passage","lines":["지진 대피 훈련 방송이 나왔다.","교실에서 책상 아래로 들어가 머리를 보호했다.","흔들림이 멈추자 계단으로 운동장에 나갔다.","친구 가 — 「다음엔 승강기를 타고 빨리 내려가자.」"],"title":"노을반 일지 ⑦ 지진 대피 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#8','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C47',1,'mc','auto','노을반 일지 ⑧에서 만든 재난방송은 무엇을 하는 방송인가요?',ARRAY['SC4-1-u3-X61']::text[],false,'{"seq":8,"concept":"SC4-1-u3-C47","difficulty":1,"kind":"mc","stem":"노을반 일지 ⑧에서 만든 재난방송은 무엇을 하는 방송인가요?","options":[{"t":"재난 상황을 전달하고 대처 방법을 안내한다","correct":true},{"t":"신나는 노래를 들려준다","mis":"SC4-1-u3-X61"},{"t":"맛집을 소개한다","mis":"SC4-1-u3-X61"},{"t":"놀이 규칙을 알려 준다","mis":"SC4-1-u3-X61"}],"explanation":["재난 때 필요해요.","소식과 할 일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 지진 대비 재난방송을 만들었다.","발생 일시·장소·피해 내용·대처 방법을 담았다.","제주도의 오름과 용암 동굴 자료도 찾아보았다.","친구 나 — 「다른 모둠 발표는 아쉬운 점만 말해 주자.」"],"title":"노을반 일지 ⑧ 재난방송과 제주도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#9','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C4',2,'mc','auto','비 온 다음 날 운동장에서 볼 수 있는 모습으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X01','SC4-1-u3-X02','SC4-1-u3-X04']::text[],false,'{"seq":9,"concept":"SC4-1-u3-C4","difficulty":2,"kind":"mc","stem":"비 온 다음 날 운동장에서 볼 수 있는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"물길이 생기고 흙이 낮은 곳에 쌓여 있다","correct":true},{"t":"운동장이 전보다 더 평평하고 단단해졌다","mis":"SC4-1-u3-X01"},{"t":"흙이 높은 곳으로 올라가 쌓였다","mis":"SC4-1-u3-X02"},{"t":"아무 변화도 없다","mis":"SC4-1-u3-X04"}],"explanation":["빗물이 흘렀어요.","흙을 옮겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#10','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C13',2,'mc','auto','흙 언덕 실험의 결과가 실제 자연과 다를 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X12','SC4-1-u3-X04']::text[],false,'{"seq":10,"concept":"SC4-1-u3-C13","difficulty":2,"kind":"mc","stem":"흙 언덕 실험의 결과가 실제 자연과 다를 수 있는 까닭은 무엇인가요?","options":[{"t":"실험의 크기와 경사가 실제 자연과 많이 다르기 때문에","correct":true},{"t":"실험은 실제 자연과 언제나 똑같기 때문에","mis":"SC4-1-u3-X12"},{"t":"색 모래를 뿌리면 흙이 움직이지 않기 때문에","mis":"SC4-1-u3-X12"},{"t":"흐르는 물은 실제 땅을 바꾸지 못하기 때문에","mis":"SC4-1-u3-X04"}],"explanation":["실험은 작아요.","실제는 커요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#11','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C18',2,'mc','auto','강 하류의 돌이 상류의 돌보다 둥근 까닭은 무엇인가요?',ARRAY['SC4-1-u3-X18']::text[],false,'{"seq":11,"concept":"SC4-1-u3-C18","difficulty":2,"kind":"mc","stem":"강 하류의 돌이 상류의 돌보다 둥근 까닭은 무엇인가요?","options":[{"t":"물에 실려 오는 동안 부딪치고 깎였기 때문에","correct":true},{"t":"하류의 돌은 처음부터 둥글게 생겼기 때문에","mis":"SC4-1-u3-X18"},{"t":"상류로 갈수록 돌이 둥글어지기 때문에","mis":"SC4-1-u3-X18"},{"t":"사람이 돌을 갈아서 놓았기 때문에","mis":"SC4-1-u3-X18"}],"explanation":["먼 길을 왔어요.","부딪쳤어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#12','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C29',2,'mc','auto','화산 활동 모형실험을 한 뒤 해야 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X31']::text[],false,'{"seq":12,"concept":"SC4-1-u3-C29","difficulty":2,"kind":"mc","stem":"화산 활동 모형실험을 한 뒤 해야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"과학실을 환기하고 쓰레기는 정해진 곳에 버린다","correct":true},{"t":"남은 마시멜로를 먹는다","mis":"SC4-1-u3-X31"},{"t":"뜨거운 포일을 바로 맨손으로 접는다","mis":"SC4-1-u3-X31"},{"t":"창문을 닫아 냄새를 가둔다","mis":"SC4-1-u3-X31"}],"explanation":["연기와 냄새가 났어요.","환기해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#13','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C31',2,'mc','auto','현무암을 맨눈으로 보았을 때의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X33','SC4-1-u3-X39']::text[],false,'{"seq":13,"concept":"SC4-1-u3-C31","difficulty":2,"kind":"mc","stem":"현무암을 맨눈으로 보았을 때의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"알갱이가 작아 하나하나 구별하기 어렵다","correct":true},{"t":"알갱이가 커서 하나하나 잘 보인다","mis":"SC4-1-u3-X33"},{"t":"분홍색 알갱이가 가장 많이 보인다","mis":"SC4-1-u3-X33"},{"t":"흙 알갱이처럼 손으로 쉽게 부서진다","mis":"SC4-1-u3-X39"}],"explanation":["알갱이가 작아요.","구별이 어려워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#14','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C39',2,'mc','auto','화산 활동에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X43','SC4-1-u3-X41','SC4-1-u3-X40']::text[],false,'{"seq":14,"concept":"SC4-1-u3-C39","difficulty":2,"kind":"mc","stem":"화산 활동에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"사람의 힘으로 막을 수 없으니 대처 방법을 알아 둔다","correct":true},{"t":"튼튼한 벽을 쌓으면 멈출 수 있다","mis":"SC4-1-u3-X43"},{"t":"이로운 점만 있으니 걱정할 필요가 없다","mis":"SC4-1-u3-X41"},{"t":"해롭기만 하니 화산 주변에는 아무것도 하지 않는다","mis":"SC4-1-u3-X40"}],"explanation":["멈출 수 없어요.","대비해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
