INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#16','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C48',2,'mc','auto','재난 대비 안내 자료를 평가할 때 가장 중요한 기준은 무엇인가요?',ARRAY['SC4-1-u3-X56','SC4-1-u3-X55','SC4-1-u3-X57']::text[],false,'{"seq":16,"concept":"SC4-1-u3-C48","difficulty":2,"kind":"mc","stem":"재난 대비 안내 자료를 평가할 때 가장 중요한 기준은 무엇인가요?","options":[{"t":"안내해야 할 내용이 들어 있는가","correct":true},{"t":"소품이 가장 화려한가","mis":"SC4-1-u3-X56"},{"t":"무서운 장면이 가장 많은가","mis":"SC4-1-u3-X55"},{"t":"누가 가장 크게 말했는가","mis":"SC4-1-u3-X57"}],"explanation":["무엇을 알려야 하나요?","내용이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#17','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C12',3,'mc','auto','비가 아주 많이 온 날과 조금 온 날을 견줄 때 흙 언덕은 언제 더 많이 변할까요?',ARRAY['SC4-1-u3-X11','SC4-1-u3-X04']::text[],false,'{"seq":17,"concept":"SC4-1-u3-C12","difficulty":3,"kind":"mc","stem":"비가 아주 많이 온 날과 조금 온 날을 견줄 때 흙 언덕은 언제 더 많이 변할까요?","options":[{"t":"비가 아주 많이 온 날","correct":true},{"t":"비가 조금 온 날","mis":"SC4-1-u3-X11"},{"t":"두 날 모두 변하지 않는다","mis":"SC4-1-u3-X04"},{"t":"두 날의 변화가 언제나 똑같다","mis":"SC4-1-u3-X11"}],"explanation":["물의 양을 견줘요.","많을수록 많이 변해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#18','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C20',3,'mc','auto','강 주변의 모습을 바꾸는 흐르는 물의 일을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u3-X21','SC4-1-u3-X15']::text[],false,'{"seq":18,"concept":"SC4-1-u3-C20","difficulty":3,"kind":"mc","stem":"강 주변의 모습을 바꾸는 흐르는 물의 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"오랜 시간에 걸쳐 깎고, 옮기고, 쌓으며 조금씩 바꾼다","correct":true},{"t":"하루 만에 모든 모습을 바꾼다","mis":"SC4-1-u3-X21"},{"t":"흐르는 물은 땅을 바꾸지 못한다","mis":"SC4-1-u3-X21"},{"t":"깎기만 하고 쌓지는 않는다","mis":"SC4-1-u3-X15"}],"explanation":["세 가지 일이에요.","오랜 시간이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#19','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C25',3,'mc','auto','화산 분출물을 상태별로 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-1-u3-X26']::text[],false,'{"seq":19,"concept":"SC4-1-u3-C25","difficulty":3,"kind":"mc","stem":"화산 분출물을 상태별로 바르게 나눈 것은 무엇인가요?","options":[{"t":"기체는 화산 가스, 액체는 용암, 고체는 화산재","correct":true},{"t":"기체는 화산재, 액체는 용암, 고체는 화산 가스","mis":"SC4-1-u3-X26"},{"t":"기체는 용암, 액체는 화산 가스, 고체는 화산재","mis":"SC4-1-u3-X26"},{"t":"셋 다 고체","mis":"SC4-1-u3-X26"}],"explanation":["가스는 기체예요.","용암은 흘러요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#20','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C35',3,'mc','auto','암석 관찰을 마친 뒤 해야 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u3-X39']::text[],false,'{"seq":20,"concept":"SC4-1-u3-C35","difficulty":3,"kind":"mc","stem":"암석 관찰을 마친 뒤 해야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"손을 깨끗이 씻는다","correct":true},{"t":"암석을 입에 대어 본다","mis":"SC4-1-u3-X39"},{"t":"암석을 친구에게 던진다","mis":"SC4-1-u3-X39"},{"t":"손을 씻지 않고 간식을 먹는다","mis":"SC4-1-u3-X39"}],"explanation":["암석을 만졌어요.","깨끗이 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#21','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C36',3,'mc','auto','화산 활동의 피해만 바르게 고른 것은 무엇인가요?',ARRAY['SC4-1-u3-X41']::text[],false,'{"seq":21,"concept":"SC4-1-u3-C36","difficulty":3,"kind":"mc","stem":"화산 활동의 피해만 바르게 고른 것은 무엇인가요?","options":[{"t":"산불, 숨쉬기 어려움, 비행기 운항 중단","correct":true},{"t":"온천, 관광지, 전기 생산","mis":"SC4-1-u3-X41"},{"t":"비옥한 땅, 산불, 온천","mis":"SC4-1-u3-X41"},{"t":"관광지, 화산재가 마을을 덮음","mis":"SC4-1-u3-X41"}],"explanation":["나쁜 일만 골라요.","섞이면 안 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#22','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C52',3,'mc','auto','제주도의 오름과 성산일출봉이 함께 알려 주는 것은 무엇인가요?',ARRAY['SC4-1-u3-X60']::text[],false,'{"seq":22,"concept":"SC4-1-u3-C52","difficulty":3,"kind":"mc","stem":"제주도의 오름과 성산일출봉이 함께 알려 주는 것은 무엇인가요?","options":[{"t":"제주도에서 화산 활동이 있었다","correct":true},{"t":"제주도는 사람이 만든 섬이다","mis":"SC4-1-u3-X60"},{"t":"제주도에는 화산 활동이 한 번도 없었다","mis":"SC4-1-u3-X60"},{"t":"화산 지형은 모두 바다에서만 생긴다","mis":"SC4-1-u3-X60"}],"explanation":["둘 다 화산이에요.","화산 활동의 흔적이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#23','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C46',4,'mc','auto','친구가 「지진은 언제 올지 알 수 있으니 그때 생존 가방을 싸면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X52','SC4-1-u3-X59','SC4-1-u3-X50']::text[],false,'{"seq":23,"concept":"SC4-1-u3-C46","difficulty":4,"kind":"mc","stem":"친구가 「지진은 언제 올지 알 수 있으니 그때 생존 가방을 싸면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「지진은 언제 일어날지 정확히 알기 어려워. 평소에 미리 준비해 둬야 해.」","correct":true},{"t":"「맞아, 그때 싸도 늦지 않아.」","mis":"SC4-1-u3-X52"},{"t":"「생존 가방은 필요 없어.」","mis":"SC4-1-u3-X59"},{"t":"「지진이 나면 승강기로 대피하면 돼.」","mis":"SC4-1-u3-X50"}],"explanation":["갑자기 일어나요.","미리 준비해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#24','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C48',4,'mc','auto','친구가 「재난방송에 사람들이 많이 볼 만한 소문을 넣자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u3-X55','SC4-1-u3-X56']::text[],false,'{"seq":24,"concept":"SC4-1-u3-C48","difficulty":4,"kind":"mc","stem":"친구가 「재난방송에 사람들이 많이 볼 만한 소문을 넣자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「확인 안 된 소문은 혼란을 줄 수 있어. 출처를 확인한 정보만 넣자.」","correct":true},{"t":"「좋아, 소문이 많을수록 좋아.」","mis":"SC4-1-u3-X55"},{"t":"「소문 대신 무서운 장면을 넣자.」","mis":"SC4-1-u3-X55"},{"t":"「내용보다 꾸미기에 힘쓰자.」","mis":"SC4-1-u3-X56"}],"explanation":["믿을 수 있나요?","출처를 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u3_review_d#25','sci',4,1,'u3','','g4_1_sci_u3_review_d','unit_review','SC4-1-u3-C45',4,'essay','teacher','노을반 일지 ⑦을 보고 지진이 났을 때 교실에서 할 일과 흔들림이 멈춘 뒤 할 일을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u3-C45","difficulty":4,"kind":"essay","stem":"노을반 일지 ⑦을 보고 지진이 났을 때 교실에서 할 일과 흔들림이 멈춘 뒤 할 일을 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 교실에서는 책상 아래로 들어가 머리와 몸을 보호한다. 흔들림이 멈추면 전기와 가스를 차단하고 계단으로 대피한다. 전기가 끊기면 승강기가 멈춰 갇힐 수 있으므로 승강기 대신 계단을 이용해야 한다.","scoring_points":["교실에서 할 일을 썼는가","멈춘 뒤 할 일을 썼는가","승강기 대신 계단인 까닭으로 고쳤는가"]},"explanation":["일지를 읽어요.","차례대로 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["지진 대피 훈련 방송이 나왔다.","교실에서 책상 아래로 들어가 머리를 보호했다.","흔들림이 멈추자 계단으로 운동장에 나갔다.","친구 가 — 「다음엔 승강기를 타고 빨리 내려가자.」"],"title":"노을반 일지 ⑦ 지진 대피 훈련"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
